-- ════════════════════════════════════════════════════════════════
-- v1.8.0 — Dati economici per anno di competenza
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.0 — migration_v1_8_0.sql
-- Dati economici per ANNO DI COMPETENZA.
-- I dati economici (input per-dipendente e valori di riferimento globali)
-- hanno validità annuale: vengono catalogati e consultati per esercizio.
--
--   • hr_economic_years        : catalogo delle annualità (esercizi)
--   • hr_employee_economics    : input economici per (dipendente, anno)
--   • hr_reference_values.year : i riferimenti globali diventano per-anno
--   • hr_reference_history.year: storico riferimenti con anno
--
-- I dati attuali presenti nella scheda dipendente sono migrati come
-- esercizio 2025 (annualità corrente). Nuove pagine:
--   hr_economic_years.php, finance_compare.php, import_economics_xlsx.php
--
-- Idempotente / ri-eseguibile.
-- ════════════════════════════════════════════════════════════════

-- ── Catalogo annualità (esercizi) ───────────────────────────────
CREATE TABLE IF NOT EXISTS `hr_economic_years` (
  `year` SMALLINT UNSIGNED NOT NULL,
  `label` VARCHAR(80) NOT NULL,
  `is_current` TINYINT(1) NOT NULL DEFAULT 0,
  `is_locked` TINYINT(1) NOT NULL DEFAULT 0,
  `note` VARCHAR(255) NULL,
  `created_by` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `hr_economic_years` (`year`,`label`,`is_current`,`is_locked`,`note`) VALUES
 (2025,'Esercizio 2025',1,0,'Annualità iniziale (dati migrati dalla scheda dipendente)');

-- ── Input economici per (dipendente, anno) ──────────────────────
CREATE TABLE IF NOT EXISTS `hr_employee_economics` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `employee_id` INT NOT NULL,
  `year` SMALLINT UNSIGNED NOT NULL,
  `ral` DECIMAL(10,2) NULL,
  `premio_concordato` DECIMAL(10,2) NULL,
  `km_concordati` DECIMAL(8,2) NULL,
  `km_effettivi` DECIMAL(8,2) NULL,
  `fuori_sede` TINYINT(1) NOT NULL DEFAULT 0,
  `fuori_sede_amount` DECIMAL(10,2) NULL,
  `classificazione_finanziaria` ENUM('Diretto','Indiretto') NULL,
  `moltiplicatore_fc` DECIMAL(12,5) NULL,
  `qt_trasferte_annue` DECIMAL(10,2) NULL,
  `qt_buoni_pasto` DECIMAL(10,2) NULL,
  `valore_tabp` DECIMAL(10,2) NULL,
  `val_km` DECIMAL(10,4) NULL,
  `incentivazione_extra` DECIMAL(12,2) NULL,
  `valore_medio_anno_auto` DECIMAL(12,2) NULL,
  `overhead_aziendale` DECIMAL(9,4) NULL,
  `moltiplicatore_fte` DECIMAL(10,4) NULL,
  `note` VARCHAR(255) NULL,
  `updated_by` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_emp_econ_year` (`employee_id`,`year`),
  KEY `idx_emp_econ_year` (`year`),
  KEY `idx_emp_econ_emp` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Backfill 2025 dai valori attuali della scheda dipendente (solo chi ha dati).
INSERT IGNORE INTO `hr_employee_economics`
  (`employee_id`,`year`,`ral`,`premio_concordato`,`km_concordati`,`km_effettivi`,
   `fuori_sede`,`fuori_sede_amount`,`classificazione_finanziaria`,`moltiplicatore_fc`,
   `qt_trasferte_annue`,`qt_buoni_pasto`,`valore_tabp`,`val_km`,`incentivazione_extra`,
   `valore_medio_anno_auto`,`overhead_aziendale`,`moltiplicatore_fte`)
SELECT `id`,2025,`ral`,`premio_concordato`,`km_concordati`,`km_effettivi`,
       COALESCE(`fuori_sede`,0),`fuori_sede_amount`,`classificazione_finanziaria`,`moltiplicatore_fc`,
       `qt_trasferte_annue`,`qt_buoni_pasto`,`valore_tabp`,`val_km`,`incentivazione_extra`,
       `valore_medio_anno_auto`,`overhead_aziendale`,`moltiplicatore_fte`
  FROM `employees`
 WHERE `ral` IS NOT NULL OR `premio_concordato` IS NOT NULL OR `km_concordati` IS NOT NULL
    OR `km_effettivi` IS NOT NULL OR `fuori_sede_amount` IS NOT NULL
    OR `classificazione_finanziaria` IS NOT NULL OR `moltiplicatore_fc` IS NOT NULL
    OR `qt_trasferte_annue` IS NOT NULL OR `qt_buoni_pasto` IS NOT NULL OR `valore_tabp` IS NOT NULL
    OR `val_km` IS NOT NULL OR `incentivazione_extra` IS NOT NULL OR `valore_medio_anno_auto` IS NOT NULL
    OR `overhead_aziendale` IS NOT NULL OR `moltiplicatore_fte` IS NOT NULL;

