-- ════════════════════════════════════════════════════════════════
-- v1.8.5 — Report & Avanzamento + Workflow di commessa
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.5 — migration_v1_8_5.sql
-- Commesse: sezione "Report & Avanzamento" (note datate, valutazioni,
-- allegati) e workflow programmabile agganciato al Gantt (step con fase,
-- stato, scadenza, responsabile, gate: l avanzamento degli step aggiorna
-- la percentuale della fase mostrata nel Gantt).
--
--   cm_project_updates       : note/report di avanzamento
--   cm_project_update_files  : allegati delle note
--   cm_workflow_steps        : step di workflow per commessa (aggancio Gantt)
--
-- Idempotente / ri-eseguibile.
-- ════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS `cm_project_updates` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `project_id` INT NOT NULL,
  `update_date` DATE NOT NULL,
  `kind` ENUM('nota','avanzamento','rischio','decisione','milestone') NOT NULL DEFAULT 'nota',
  `title` VARCHAR(180) NULL,
  `body` TEXT NULL,
  `rating` TINYINT NULL,
  `progress_pct` TINYINT NULL,
  `phase_id` INT NULL,
  `step_id` INT NULL,
  `created_by` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `idx_upd_project` (`project_id`),
  KEY `idx_upd_date` (`update_date`),
  KEY `idx_upd_phase` (`phase_id`),
  CONSTRAINT `fk_upd_proj` FOREIGN KEY (`project_id`) REFERENCES `cm_projects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `cm_project_update_files` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `update_id` INT NOT NULL,
  `project_id` INT NOT NULL,
  `original_name` VARCHAR(255) NOT NULL,
  `stored_name` VARCHAR(255) NOT NULL,
  `mime` VARCHAR(120) NULL,
  `size_bytes` BIGINT NULL,
  `uploaded_by` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_updfile_update` (`update_id`),
  KEY `idx_updfile_project` (`project_id`),
  CONSTRAINT `fk_updfile_upd` FOREIGN KEY (`update_id`) REFERENCES `cm_project_updates` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `cm_workflow_steps` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `project_id` INT NOT NULL,
  `name` VARCHAR(180) NOT NULL,
  `description` VARCHAR(500) NULL,
  `phase_id` INT NULL,
  `status` ENUM('da_fare','in_corso','completato','bloccato') NOT NULL DEFAULT 'da_fare',
  `start_date` DATE NULL,
  `due_date` DATE NULL,
  `assignee_employee_id` INT NULL,
  `progress_pct` TINYINT NOT NULL DEFAULT 0,
  `is_gate` TINYINT(1) NOT NULL DEFAULT 0,
  `sort_order` INT NOT NULL DEFAULT 0,
  `created_by` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `completed_at` DATETIME NULL,
  `deleted_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `idx_wf_project` (`project_id`),
  KEY `idx_wf_phase` (`phase_id`),
  CONSTRAINT `fk_wf_proj` FOREIGN KEY (`project_id`) REFERENCES `cm_projects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

