-- ════════════════════════════════════════════════════════════════
-- v1.8.8 — Modulo Attivita e Rendicontazione DGB (schema + viste + permessi)
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.8 — migration_v1_8_8.sql
-- Gestione Commesse: modulo "Attivita e Rendicontazione DGB" (sorgente
-- gestionale DogoBit). Ingestion dei 5 modelli (pipe CSV), gerarchia
-- pianificazione -> attivita -> incaricati, KPI (SLA innesco, consuntivo vs
-- pianificato, distribuzione carico sede/remoto) e data quality.
--
--   dgb_operator                  operatori/tecnici del gestionale
--   dgb_operator_allocation       allocazioni operatore su contratto
--   dgb_forms_activity_planning   piani ricorrenti (PADRE)
--   dgb_forms_activity            attivita/ticket (FIGLIO, FK id_activity_planning)
--   dgb_forms_activity_operator   incaricati per attivita (DETTAGLIO, FK id_activity)
--   dgb_import_log                log/diff delle importazioni (Task 5)
--
-- Nessuna FK hard tra le tabelle DGB: dataset esterno con possibili
-- riferimenti pendenti: si usano solo indici. Colonna sig per il diff.
-- Idempotente / ri-eseguibile.
-- ════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS `dgb_operator` (
  `id` INT NOT NULL,
  `username` VARCHAR(160) NULL,
  `abbr` VARCHAR(40) NULL,
  `first_name` VARCHAR(120) NULL,
  `second_name` VARCHAR(120) NULL,
  `email` VARCHAR(190) NULL,
  `company_abbr` VARCHAR(60) NULL,
  `type` VARCHAR(30) NULL,
  `hourly_cost` DECIMAL(10,2) NULL,
  `full_cost` DECIMAL(10,2) NULL,
  `active` TINYINT(1) NULL,
  `deleted` TINYINT(1) NULL,
  `id_role` INT NULL,
  `id_company` INT NULL,
  `created_at` DATETIME NULL,
  `updated_at` DATETIME NULL,
  `deleted_at` DATETIME NULL,
  `sig` CHAR(32) NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dop_company` (`id_company`),
  KEY `idx_dop_active` (`active`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `dgb_operator_allocation` (
  `id` INT NOT NULL,
  `id_operator` INT NULL,
  `id_division` INT NULL,
  `id_contract` INT NULL,
  `id_activitytype` INT NULL,
  `start_date` DATETIME NULL,
  `end_date` DATETIME NULL,
  `type` VARCHAR(30) NULL,
  `created_at` DATETIME NULL,
  `updated_at` DATETIME NULL,
  `sig` CHAR(32) NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dal_op` (`id_operator`),
  KEY `idx_dal_contract` (`id_contract`),
  KEY `idx_dal_dates` (`start_date`,`end_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `dgb_forms_activity_planning` (
  `id` INT NOT NULL,
  `name` VARCHAR(255) NULL,
  `repetition_type` VARCHAR(30) NULL,
  `fisrt_activity_start_date_time` DATETIME NULL,
  `first_activity_end_date_time` DATETIME NULL,
  `start_repetition_date` DATETIME NULL,
  `end_repetition_date` DATETIME NULL,
  `dutation_in_minutes` INT NULL,
  `num_of_planned` INT NULL,
  `planned_remote` TINYINT(1) NULL,
  `planned_smart_working` TINYINT(1) NULL,
  `deleted` TINYINT(1) NULL,
  `id_operator` INT NULL,
  `id_contract` INT NULL,
  `id_customer_comp` INT NULL,
  `id_place` INT NULL,
  `id_zone` INT NULL,
  `id_activitytype` INT NULL,
  `created_at` DATETIME NULL,
  `updated_at` DATETIME NULL,
  `deleted_at` DATETIME NULL,
  `sig` CHAR(32) NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dpl_contract` (`id_contract`),
  KEY `idx_dpl_operator` (`id_operator`),
  KEY `idx_dpl_start` (`fisrt_activity_start_date_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `dgb_forms_activity` (
