  PRIMARY KEY (`id`),
  KEY `idx_dfao_activity` (`id_activity`),
  KEY `idx_dfao_operator` (`id_operator`),
  KEY `idx_dfao_remote` (`from_remote`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `dgb_import_log` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `batch_uuid` CHAR(36) NOT NULL,
  `table_name` VARCHAR(64) NOT NULL,
  `source_file` VARCHAR(190) NULL,
  `rows_read` INT NOT NULL DEFAULT 0,
  `rows_inserted` INT NOT NULL DEFAULT 0,
  `rows_updated` INT NOT NULL DEFAULT 0,
  `rows_unchanged` INT NOT NULL DEFAULT 0,
  `rows_skipped` INT NOT NULL DEFAULT 0,
  `diff_json` LONGTEXT NULL,
  `created_by` INT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_dil_batch` (`batch_uuid`),
  KEY `idx_dil_table` (`table_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Task 2: gerarchia PADRE -> FIGLIO -> DETTAGLIO ──────────────────────────
CREATE OR REPLACE VIEW `vw_dgb_activity_hierarchy` AS
SELECT
  pl.id AS planning_id, pl.name AS planning_name, pl.repetition_type,
  pl.fisrt_activity_start_date_time AS planned_start, pl.dutation_in_minutes,
  a.id AS activity_id, a.code AS activity_code, a.ticket, a.status,
  a.date_start, a.report_date, a.planned_hours, a.human_resource_hours,
  a.total_cost, a.total_revenue, a.id_report_author, a.id_contract,
  au.username AS author_username, CONCAT(COALESCE(au.first_name,''),' ',COALESCE(au.second_name,'')) AS author_name,
  ao.id AS assignment_id, ao.id_operator AS assignee_id,
  op.username AS assignee_username, CONCAT(COALESCE(op.first_name,''),' ',COALESCE(op.second_name,'')) AS assignee_name,
  ao.hours AS assignee_hours, ao.cost AS assignee_cost, ao.revenue AS assignee_revenue,
  ao.from_remote, ao.smart_working, ao.trip_hours
FROM dgb_forms_activity a
LEFT JOIN dgb_forms_activity_planning pl ON pl.id = a.id_activity_planning
LEFT JOIN dgb_forms_activity_operator ao ON ao.id_activity = a.id
LEFT JOIN dgb_operator au ON au.id = a.id_report_author
LEFT JOIN dgb_operator op ON op.id = ao.id_operator;

-- ── Task 3a: SLA innesco (scostamento avvio previsto vs effettivo) ───────────
CREATE OR REPLACE VIEW `vw_dgb_sla` AS
SELECT
  a.id AS activity_id, a.code AS activity_code, a.status, a.id_activity_planning,
  pl.fisrt_activity_start_date_time AS planned_start, a.date_start AS actual_start,
  TIMESTAMPDIFF(HOUR, pl.fisrt_activity_start_date_time, a.date_start) AS sla_hours,
  TIMESTAMPDIFF(MINUTE, pl.fisrt_activity_start_date_time, a.date_start) AS sla_minutes
FROM dgb_forms_activity a
LEFT JOIN dgb_forms_activity_planning pl ON pl.id = a.id_activity_planning;

-- ── Task 3b: consuntivo vs pianificato ──────────────────────────────────────
CREATE OR REPLACE VIEW `vw_dgb_planned_vs_actual` AS
SELECT
  a.id AS activity_id, a.code AS activity_code, a.status, a.report_date,
  a.planned_hours,
  ROUND(pl.dutation_in_minutes/60,2) AS planning_hours,
  COALESCE(d.actual_hours,0) AS actual_hours,
  COALESCE(d.actual_cost,0) AS actual_cost,
  COALESCE(d.actual_revenue,0) AS actual_revenue,
  ROUND(COALESCE(d.actual_hours,0) - COALESCE(a.planned_hours,0),2) AS delta_hours
FROM dgb_forms_activity a
LEFT JOIN dgb_forms_activity_planning pl ON pl.id = a.id_activity_planning
LEFT JOIN (
  SELECT id_activity, ROUND(SUM(hours),2) AS actual_hours, ROUND(SUM(cost),2) AS actual_cost, ROUND(SUM(revenue),2) AS actual_revenue
  FROM dgb_forms_activity_operator GROUP BY id_activity
) d ON d.id_activity = a.id;

-- ── Task 3c: distribuzione carico per incaricato (sede vs remoto) ────────────
CREATE OR REPLACE VIEW `vw_dgb_load_by_operator` AS
SELECT
  ao.id_operator AS assignee_id,
  op.username AS assignee_username,
  CONCAT(COALESCE(op.first_name,''),' ',COALESCE(op.second_name,'')) AS assignee_name,
  ROUND(SUM(ao.hours),2) AS total_hours,
  ROUND(SUM(CASE WHEN ao.from_remote=1 THEN ao.hours ELSE 0 END),2) AS remote_hours,
  ROUND(SUM(CASE WHEN COALESCE(ao.from_remote,0)=0 THEN ao.hours ELSE 0 END),2) AS onsite_hours,
  ROUND(SUM(ao.cost),2) AS total_cost,
  ROUND(SUM(ao.revenue),2) AS total_revenue,
  COUNT(DISTINCT ao.id_activity) AS activities
FROM dgb_forms_activity_operator ao
LEFT JOIN dgb_operator op ON op.id = ao.id_operator
GROUP BY ao.id_operator, op.username, assignee_name;

