-- ════════════════════════════════════════════════════════════════
-- v1.8.11 — Riconciliazione DGB <-> Commesse (mappatura + vista rollup)
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.11 — migration_v1_8_11.sql
-- Riconciliazione DGB <-> Commesse native. Il collegamento e' dedotto da
-- cm_projects.external_link (.../contract/editV2/<id>) dove <id> = dgb id_contract.
-- Si materializza in cm_projects.dgb_contract_id (mappatura persistente, indicizzata)
-- e in una vista di rollup che aggrega per contratto attivita', ore
-- (ordinario/straordinario/trasferta), costi, ricavi e periodo, cosi' che ogni
-- commessa e le sue voci mostrino i dati DGB correlati.
-- Popolamento idempotente (solo dove non gia' valorizzato: preserva override manuali).
-- Idempotente / ri-eseguibile.
-- ════════════════════════════════════════════════════════════════

ALTER TABLE `cm_projects` ADD COLUMN IF NOT EXISTS `dgb_contract_id` INT NULL AFTER `external_link`;
ALTER TABLE `cm_projects` ADD INDEX IF NOT EXISTS `idx_cmp_dgb_contract` (`dgb_contract_id`);

UPDATE `cm_projects` SET `dgb_contract_id` = CAST(REGEXP_SUBSTR(`external_link`, '[0-9]+$') AS UNSIGNED) WHERE `dgb_contract_id` IS NULL AND `external_link` REGEXP 'contract/editV2/[0-9]+$';

CREATE OR REPLACE VIEW `vw_dgb_commessa_rollup` AS
SELECT
  a.id_contract AS dgb_contract_id,
  COUNT(DISTINCT a.id) AS activities,
  SUM(a.id_activity_planning IS NULL) AS orphan_activities,
  ROUND(SUM(COALESCE(a.total_cost,0)),2) AS total_cost,
  ROUND(SUM(COALESCE(a.total_revenue,0)),2) AS total_revenue,
  ROUND(SUM(COALESCE(hh.hours,0)),2) AS actual_hours,
  ROUND(SUM(COALESCE(hh.extra_hours,0)),2) AS overtime_hours,
  ROUND(SUM(COALESCE(hh.trip_hours,0)),2) AS trip_hours,
  MIN(COALESCE(a.report_date, DATE(a.date_start))) AS first_date,
  MAX(COALESCE(a.report_date, DATE(a.date_start))) AS last_date
FROM dgb_forms_activity a
LEFT JOIN (
  SELECT id_activity, SUM(hours) hours, SUM(extra_hours) extra_hours, SUM(trip_hours) trip_hours
  FROM dgb_forms_activity_operator GROUP BY id_activity
) hh ON hh.id_activity = a.id
WHERE a.deleted = 0 AND a.id_contract IS NOT NULL
GROUP BY a.id_contract;

