-- ════════════════════════════════════════════════════════════════
-- v1.8.13 — DGB -> Commesse native (sync moduli intervento) + classificazione persone
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.13 — migration_v1_8_13.sql
-- (A) Sincronizzazione DGB -> Commesse native: marker idempotente sui moduli di
--     intervento (cm_intervention_reports.dgb_source_id = dgb_forms_activity_operator.id)
--     e mappa operatore DGB -> dipendente (email, poi nome).
-- (B) Profilo persona: tipo orario (ordinario/turni) e reperibilita' (on_call),
--     con seed per gli operatori che hanno rendicontato.
-- Idempotente / ri-eseguibile. Nessun dato distruttivo.
-- ════════════════════════════════════════════════════════════════

-- (A) marker sui moduli di intervento
ALTER TABLE `cm_intervention_reports` ADD COLUMN IF NOT EXISTS `dgb_source_id` INT NULL AFTER `import_batch_id`;
ALTER TABLE `cm_intervention_reports` ADD UNIQUE INDEX IF NOT EXISTS `uq_cir_dgb_source` (`dgb_source_id`);

-- (A) mappa operatore DGB -> dipendente
CREATE TABLE IF NOT EXISTS `dgb_operator_map` (
  `dgb_operator_id` INT NOT NULL,
  `employee_id` INT NULL,
  `match_type` VARCHAR(20) NULL,
  `updated_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`dgb_operator_id`),
  KEY `idx_dom_emp` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `dgb_operator_map` (`dgb_operator_id`,`employee_id`,`match_type`)
 SELECT o.id, e.id, 'email' FROM `dgb_operator` o JOIN `employees` e ON LOWER(e.business_email)=LOWER(o.email) WHERE o.email IS NOT NULL AND o.email<>'';
INSERT IGNORE INTO `dgb_operator_map` (`dgb_operator_id`,`employee_id`,`match_type`)
 SELECT o.id, e.id, 'name' FROM `dgb_operator` o JOIN `employees` e ON LOWER(TRIM(e.first_name))=LOWER(TRIM(o.first_name)) AND LOWER(TRIM(e.last_name))=LOWER(TRIM(o.second_name)) WHERE o.first_name IS NOT NULL AND o.first_name<>'';

-- (B) profilo persona (orario + reperibilita')
CREATE TABLE IF NOT EXISTS `dgb_operator_profile` (
  `dgb_operator_id` INT NOT NULL,
  `schedule_type` ENUM('ordinario','turni') NOT NULL DEFAULT 'ordinario',
  `on_call` TINYINT(1) NOT NULL DEFAULT 0,
  `ordinary_start` TIME NULL DEFAULT '09:00:00',
  `ordinary_end` TIME NULL DEFAULT '18:00:00',
  `note` VARCHAR(255) NULL,
  `auto_classified` TINYINT(1) NOT NULL DEFAULT 0,
  `updated_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`dgb_operator_id`),
  KEY `idx_dopf_sched` (`schedule_type`),
  KEY `idx_dopf_oncall` (`on_call`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `dgb_operator_profile` (`dgb_operator_id`)
 SELECT DISTINCT `id_operator` FROM `dgb_forms_activity_operator` WHERE `id_operator` IS NOT NULL;

