-- ════════════════════════════════════════════════════════════════
-- v1.8.23 — DGB import contratti + mapping commessa (Code / code_x_installation)
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.23 — migration_v1_8_23.sql
-- Nuova tabella dgb_forms_contract (import contratti DogoBit). La commessa
-- collegata usa: project_code = Code, name = code_x_installation. In Attività &
-- Rendicontazione DGB la colonna Commessa mostra il Code (project_code).
-- La sincronizzazione crea e aggiorna le commesse dai contratti importati.
-- Idempotente.
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `dgb_forms_contract` (
  `id` INT NOT NULL,
  `code` VARCHAR(100) NULL,
  `code_x_installation` VARCHAR(255) NULL,
  `description` VARCHAR(255) NULL,
  `id_customer_comp` INT NULL,
  `id_company` INT NULL,
  `start_date` DATETIME NULL,
  `end_date` DATETIME NULL,
  `active` TINYINT NULL,
  `deleted` TINYINT NULL DEFAULT 0,
  `created_at` DATETIME NULL,
  `updated_at` DATETIME NULL,
  `deleted_at` DATETIME NULL,
  `sig` CHAR(32) NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dfc_code` (`code`),
  KEY `idx_dfc_deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
