-- ════════════════════════════════════════════════════════════════
-- v1.8.28 — Sotto-categorie 1-a-molti (department_subcategories)
-- ════════════════════════════════════════════════════════════════
-- ════════════════════════════════════════════════════════════════
-- PortalManager 1.8.28 — migration_v1_8_28.sql
-- Sotto-categorie dei dipartimenti come relazione una-a-molti pulita: tabella
-- dedicata department_subcategories con department_id (una sotto-categoria
-- appartiene a UNA sola categoria, una categoria ha MOLTE sotto-categorie).
-- Il dipendente si assegna categoria (department_id) e sotto-categoria
-- (subcategory_id). Migra i dati dal modello provvisorio v1.8.27 (departments.parent_id).
-- Idempotente.
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `department_subcategories` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `department_id` INT UNSIGNED NOT NULL,
  `name` VARCHAR(150) NOT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_subcat_dept_name` (`department_id`,`name`),
  KEY `idx_subcat_dept` (`department_id`),
  CONSTRAINT `fk_subcat_dept` FOREIGN KEY (`department_id`) REFERENCES `departments`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE `employees` ADD COLUMN IF NOT EXISTS `subcategory_id` INT UNSIGNED NULL AFTER `department_id`;
CREATE INDEX IF NOT EXISTS `idx_emp_subcategory` ON `employees` (`subcategory_id`);
INSERT IGNORE INTO `department_subcategories` (`department_id`,`name`,`is_active`) SELECT `parent_id`,`name`,`is_active` FROM `departments` WHERE `parent_id` IS NOT NULL;
UPDATE `employees` e JOIN `departments` d ON d.id=e.department_id AND d.parent_id IS NOT NULL JOIN `department_subcategories` s ON s.department_id=d.parent_id AND s.name=d.name SET e.subcategory_id=s.id, e.department_id=d.parent_id;
DELETE FROM `departments` WHERE `parent_id` IS NOT NULL;
INSERT INTO `app_settings` (`setting_key`,`setting_value`,`description`) VALUES ('app_version','1.8.28','Versione applicazione'),('schema_version','1.8.28','Versione schema database'),('release_label','1.8.28','Etichetta release mostrata in footer') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);

