-- v1.8.40 — Commesse/Progetti allineate ai 29 campi standard "Lista commesse"
-- ════════════════════════════════════════════════════════════════
-- La scheda "Commesse / Progetti" adotta come standard i 29 header dell'export
-- ufficiale (export_lista_commesse.xlsx). Nessuna colonna nuova e' realmente
-- necessaria: sono tutte gia' presenti in cm_projects dalla serie 1.7.x. Qui si
-- recuperano in modo idempotente eventuali installazioni parziali e si creano
-- gli indici a supporto dei nuovi filtri di elenco.
-- ════════════════════════════════════════════════════════════════
ALTER TABLE `cm_projects`
    ADD COLUMN IF NOT EXISTS `abbr`                    varchar(20)  DEFAULT NULL AFTER `name`,
    ADD COLUMN IF NOT EXISTS `commercial_ref`          varchar(120) DEFAULT NULL AFTER `project_type`,
    ADD COLUMN IF NOT EXISTS `external_link`           varchar(500) DEFAULT NULL AFTER `commercial_ref`,
    ADD COLUMN IF NOT EXISTS `economic_status`         varchar(20)  DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `economic_status_todate`  varchar(20)  DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `description`             text         DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `internal_description`    text         DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `compliance_to_verify`    tinyint(1)   NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS `compliance_preauth`      tinyint(1)   NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS `anomalies_open`          int(11)      NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS `anomalies_blocking`      int(11)      NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS `first_billing_date`      date         DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `billing_freq_months`     int(11)      DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `value_todate`            decimal(14,2) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `actual_cost`             decimal(14,2) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `margin_todate`           decimal(14,2) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `residual_total`          decimal(14,2) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `residual_todate`         decimal(14,2) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `credit_on_value`         decimal(14,2) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `credit_on_costs`         decimal(14,2) DEFAULT NULL;
ALTER TABLE `cm_projects`
    ADD INDEX IF NOT EXISTS `idx_proj_abbr`          (`abbr`),
    ADD INDEX IF NOT EXISTS `idx_proj_econstatus`    (`economic_status`),
    ADD INDEX IF NOT EXISTS `idx_proj_econtoday`     (`economic_status_todate`),
    ADD INDEX IF NOT EXISTS `idx_proj_commref`       (`commercial_ref`),
    ADD INDEX IF NOT EXISTS `idx_proj_compl_verify`  (`compliance_to_verify`),
    ADD INDEX IF NOT EXISTS `idx_proj_compl_preauth` (`compliance_preauth`),
    ADD INDEX IF NOT EXISTS `idx_proj_anom_open`     (`anomalies_open`),
    ADD INDEX IF NOT EXISTS `idx_proj_anom_block`    (`anomalies_blocking`);
INSERT INTO `app_settings` (`setting_key`,`setting_value`,`description`) VALUES ('app_version','1.8.40','Versione applicazione'),('schema_version','1.8.40','Versione schema database'),('release_label','1.8.40','Etichetta release mostrata in footer') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);

