-- -----------------------------------------------------------------------------
-- 4. Riconciliazione dei segnaposto DGB con le commesse reali.
--    Ogni riferimento viene spostato dal segnaposto alla commessa reale che
--    condivide lo stesso dgb_contract_id. La tabella ponte e' temporanea e
--    viene ricostruita a ogni esecuzione, cosi' lo script resta idempotente.
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_dgb_remap`;
CREATE TABLE `tmp_dgb_remap` (
  `old_id` INT NOT NULL,
  `new_id` INT NOT NULL,
  PRIMARY KEY (`old_id`),
  KEY `idx_remap_new` (`new_id`)
) ENGINE=InnoDB;
INSERT INTO `tmp_dgb_remap` (`old_id`,`new_id`)
SELECT ph.`id`, re.`id`
  FROM `cm_projects` ph
  JOIN `cm_projects` re
    ON re.`dgb_contract_id` = ph.`dgb_contract_id`
   AND re.`project_code` NOT LIKE 'DGB-%'
 WHERE ph.`project_code` LIKE 'DGB-%'
   AND ph.`dgb_contract_id` IS NOT NULL;

-- rapporti di intervento
UPDATE `cm_intervention_reports` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- team di commessa
UPDATE `cm_team` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- righe di timesheet
UPDATE `cm_timesheet_entries` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- effort di presales
UPDATE `cm_presales_effort` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- step di workflow
UPDATE `cm_workflow_steps` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- tariffe di banda
UPDATE `cm_project_band_rates` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- aggiornamenti di commessa
UPDATE `cm_project_updates` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- allegati agli aggiornamenti
UPDATE `cm_project_update_files` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- fasi di Gantt
UPDATE `cm_project_phases` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- alias di codice commessa
UPDATE `cm_alias_project` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;
-- alias di fascia
UPDATE `cm_alias_band` t JOIN `tmp_dgb_remap` m ON m.`old_id` = t.`project_id`
   SET t.`project_id` = m.`new_id`;

-- -----------------------------------------------------------------------------
-- 5. Rimozione dei soli segnaposto riconciliati. Quelli senza commessa reale
--    corrispondente restano in elenco: rappresentano contratti DGB piu' recenti
--    del file commesse e vanno importati alla prossima estrazione.
-- -----------------------------------------------------------------------------
DELETE p FROM `cm_projects` p JOIN `tmp_dgb_remap` m ON m.`old_id` = p.`id`;
DROP TABLE IF EXISTS `tmp_dgb_remap`;

