-- ════════════════════════════════════════════════════════════════
-- v1.8.45 — Sincronizzazione commesse dal database gestionale
-- ════════════════════════════════════════════════════════════════
-- Parametri di connessione alla sorgente esterna, con password cifrata
-- AES-256-GCM tramite APP_SECRET (che risiede in .env.php, fuori dal database).
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `cm_source_db` (
    `id` int(11) NOT NULL AUTO_INCREMENT,
    `label` varchar(100) NOT NULL DEFAULT 'Gestionale',
    `driver` varchar(20) NOT NULL DEFAULT 'mysql',
    `host` varchar(255) NOT NULL,
    `port` int(11) NOT NULL DEFAULT 3306,
    `dbname` varchar(128) NOT NULL,
    `username` varchar(128) NOT NULL,
    `password_enc` text DEFAULT NULL,
    `source_schema` varchar(64) DEFAULT NULL,
    `source_table` varchar(64) NOT NULL DEFAULT 'contract',
    `timeout` int(11) NOT NULL DEFAULT 10,
    `include_deleted` tinyint(1) NOT NULL DEFAULT 0,
    `is_active` tinyint(1) NOT NULL DEFAULT 1,
    `last_sync_at` datetime DEFAULT NULL,
    `last_sync_note` varchar(255) DEFAULT NULL,
    `created_by` int(11) DEFAULT NULL,
    `created_at` datetime NOT NULL DEFAULT current_timestamp(),
    `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    KEY `idx_srcdb_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE `cm_source_db`
    ADD COLUMN IF NOT EXISTS `source_schema` varchar(64) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `include_deleted` tinyint(1) NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS `last_sync_at` datetime DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `last_sync_note` varchar(255) DEFAULT NULL;
ALTER TABLE `cm_import_batches` ADD COLUMN IF NOT EXISTS `kind` varchar(30) DEFAULT NULL;
INSERT INTO `app_settings` (`setting_key`,`setting_value`,`description`) VALUES ('app_version','1.8.45','Versione applicazione'),('schema_version','1.8.45','Versione schema database'),('release_label','1.8.45','Etichetta release mostrata in footer') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);

