-- ════════════════════════════════════════════════════════════════
-- v1.8.48 — Anagrafica Tecnica, Unita Organizzative, legame rapporti/DGB
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Unita organizzative tecniche
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_tech_units` (
    `id`          int(11)      NOT NULL AUTO_INCREMENT,
    `code`        varchar(40)  NOT NULL,
    `name`        varchar(120) NOT NULL,
    `description` varchar(255) DEFAULT NULL,
    `color`       varchar(9)   DEFAULT NULL,
    `is_oncall`   tinyint(1)   NOT NULL DEFAULT 0,
    `sort_order`  int(11)      NOT NULL DEFAULT 0,
    `is_active`   tinyint(1)   NOT NULL DEFAULT 1,
    `created_by`  int(11)      DEFAULT NULL,
    `created_at`  datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`  datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_tech_unit_code` (`code`),
    KEY `idx_tech_unit_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. Sotto-unita. Il vincolo di unicita e' sulla coppia, cosi' due unita
--    diverse possono avere una sotto-unita con lo stesso nome.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_tech_subunits` (
    `id`          int(11)      NOT NULL AUTO_INCREMENT,
    `unit_id`     int(11)      NOT NULL,
    `name`        varchar(120) NOT NULL,
    `description` varchar(255) DEFAULT NULL,
    `sort_order`  int(11)      NOT NULL DEFAULT 0,
    `is_active`   tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`  datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`  datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_tech_subunit` (`unit_id`, `name`),
    KEY `idx_tech_subunit_unit` (`unit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. Anagrafica tecnica. employee_id e professional_id sono alternativi: la
--    persona e' interna oppure esterna, mai entrambe.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_tech_profiles` (
    `id`              int(11)     NOT NULL AUTO_INCREMENT,
    `employee_id`     int(11)     DEFAULT NULL,
    `professional_id` int(11)     DEFAULT NULL,
    `unit_id`         int(11)     DEFAULT NULL,
    `subunit_id`      int(11)     DEFAULT NULL,
    `seniority`       varchar(30) DEFAULT NULL,
    `on_call`         tinyint(1)  NOT NULL DEFAULT 0,
    `on_call_h24`     tinyint(1)  NOT NULL DEFAULT 0,
    `shift_pattern`   varchar(60) DEFAULT NULL,
    `main_skill`      varchar(120) DEFAULT NULL,
    `certifications`  text        DEFAULT NULL,
    `notes`           text        DEFAULT NULL,
    `valid_from`      date        DEFAULT NULL,
    `is_active`       tinyint(1)  NOT NULL DEFAULT 1,
    `created_by`      int(11)     DEFAULT NULL,
    `created_at`      datetime    NOT NULL DEFAULT current_timestamp(),
    `updated_at`      datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_tech_emp`  (`employee_id`),
    UNIQUE KEY `uq_tech_prof` (`professional_id`),
    KEY `idx_tech_unit`    (`unit_id`),
    KEY `idx_tech_subunit` (`subunit_id`),
    KEY `idx_tech_oncall`  (`on_call`, `on_call_h24`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 4. Storicizzazione. Le righe sono scritte solo quando l'operatore chiede di
--    registrare la variazione, per non generare rumore a ogni salvataggio.
--    valid_to NULL indica l'assegnazione corrente.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_tech_history` (
    `id`              int(11)      NOT NULL AUTO_INCREMENT,
    `profile_id`      int(11)      NOT NULL,
    `unit_id`         int(11)      DEFAULT NULL,
    `subunit_id`      int(11)      DEFAULT NULL,
    `unit_label`      varchar(120) DEFAULT NULL,
    `subunit_label`   varchar(120) DEFAULT NULL,
    `seniority`       varchar(30)  DEFAULT NULL,
    `on_call`         tinyint(1)   NOT NULL DEFAULT 0,
    `on_call_h24`     tinyint(1)   NOT NULL DEFAULT 0,
    `valid_from`      date         NOT NULL,
    `valid_to`        date         DEFAULT NULL,
    `change_reason`   varchar(255) DEFAULT NULL,
    `changed_by`      int(11)      DEFAULT NULL,
    `created_at`      datetime     NOT NULL DEFAULT current_timestamp(),
    PRIMARY KEY (`id`),
    KEY `idx_tech_hist_profile` (`profile_id`, `valid_from`),
    KEY `idx_tech_hist_open`    (`profile_id`, `valid_to`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

