-- -----------------------------------------------------------------------------
-- 6. Legame fra i rapporti di intervento e le attivita DGB.
--
--    Il codice rapporto e il codice attivita coincidono, quindi la
--    riconciliazione e' diretta. Due accortezze pero' sono necessarie.
--
--    Non si riusa `dgb_source_id`: quella colonna ha un vincolo UNIQUE ed e'
--    riservata alla sincronizzazione DGB, che vi scrive l'identificativo
--    dell'allocazione. Un intervento svolto da piu' tecnici produce piu'
--    rapporti che puntano alla stessa attivita, e il vincolo li rifiuterebbe.
--    Si usa quindi una colonna dedicata, senza vincolo di unicita.
--
--    L'indice su dgb_forms_activity.code e' indispensabile: senza, la UPDATE
--    esegue una scansione completa per ogni rapporto e su decine di migliaia
--    di righe finisce in lock wait timeout.
-- -----------------------------------------------------------------------------
ALTER TABLE `dgb_forms_activity`
    ADD INDEX IF NOT EXISTS `idx_dfa_code` (`code`);

ALTER TABLE `cm_intervention_reports`
    ADD COLUMN IF NOT EXISTS `dgb_activity_id` int(11) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `dgb_activity_code` varchar(80) DEFAULT NULL;

ALTER TABLE `cm_intervention_reports`
    ADD INDEX IF NOT EXISTS `idx_ir_dgb_activity` (`dgb_activity_id`);

UPDATE `cm_intervention_reports` r
  JOIN `dgb_forms_activity` a
    ON a.`code` = SUBSTRING_INDEX(r.`report_code`, '/', 1)
   SET r.`dgb_activity_id` = a.`id`,
       r.`dgb_activity_code` = a.`code`
 WHERE r.`dgb_activity_id` IS NULL;

