-- ════════════════════════════════════════════════════════════════
-- v1.8.50 — Grana canonica dei rapporti, deduplica unica, viste analitiche
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Chiave di grana
--
--    Le due colonne dgb_activity_* sono introdotte dalla v1.8.48 e servono alla
--    vista analitica: vengono ridichiarate qui perche' la migration sia
--    auto-consistente e non dipenda dall'ordine con cui sono state applicate le
--    release precedenti.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports`
    ADD COLUMN IF NOT EXISTS `dgb_activity_id` int(11) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `dgb_activity_code` varchar(80) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `source_uid` varchar(120) DEFAULT NULL COMMENT 'Chiave di grana: <codice attivita>#<id operatore>',
    ADD COLUMN IF NOT EXISTS `source_system` varchar(20) DEFAULT NULL COMMENT 'Canale di provenienza: dgb, xlsx, manuale';

-- -----------------------------------------------------------------------------
-- 2. Ripristino dei codici di riferimento.
--    Il suffisso viene rimosso da report_code e conservato dentro source_uid.
--    L'ordine conta: prima si valorizza source_uid usando il suffisso, poi si
--    ripulisce report_code, altrimenti l'informazione andrebbe persa.
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports`
   SET `source_uid` = CONCAT(SUBSTRING_INDEX(`report_code`, '/', 1), '#',
                             SUBSTRING_INDEX(`report_code`, '/', -1))
 WHERE `source_uid` IS NULL AND `report_code` LIKE '%/%';

UPDATE `cm_intervention_reports`
   SET `source_uid` = CONCAT(`report_code`, '#',
                             COALESCE(CAST(`technician_id` AS CHAR), CAST(`technician_professional_id` AS CHAR), '0'))
 WHERE `source_uid` IS NULL;

-- -----------------------------------------------------------------------------
-- 2-bis. Rimozione dei vincoli obsoleti.
--
--    Deve precedere la pulizia di report_code: togliendo il suffisso, due
--    tecnici sulla stessa attivita' tornano a condividere il codice, e con
--    uq_report_code ancora attivo l'UPDATE fallirebbe per violazione di
--    integrita'. E' il primo errore incontrato in collaudo, ed e' anche la
--    prova che il vecchio vincolo era incompatibile con la grana corretta.
--
--    Stesso ragionamento per dgb_source_id: identifica l'attivita', non la
--    prestazione, quindi non puo' essere unico per riga.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports` DROP INDEX IF EXISTS `uq_report_code`;
ALTER TABLE `cm_intervention_reports` DROP INDEX IF EXISTS `uq_cir_dgb_source`;
ALTER TABLE `cm_intervention_reports` ADD INDEX IF NOT EXISTS `idx_ir_dgb_source` (`dgb_source_id`);

UPDATE `cm_intervention_reports`
   SET `report_code` = SUBSTRING_INDEX(`report_code`, '/', 1)
 WHERE `report_code` LIKE '%/%';

UPDATE `cm_intervention_reports`
   SET `source_system` = CASE WHEN `dgb_source_id` IS NOT NULL THEN 'dgb' ELSE 'xlsx' END
 WHERE `source_system` IS NULL;

-- -----------------------------------------------------------------------------
-- 3. Rimozione dei duplicati gia' presenti.
--    Si conserva la riga con id piu' basso per ogni source_uid: e' la prima
--    registrata, quindi quella a cui possono essere agganciati riferimenti.
--    La tabella d'appoggio evita il limite di MariaDB sulla DELETE che legge
--    la stessa tabella in sottoquery.
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_ir_dupes`;
-- v1.8.66: CREATE ... AS SELECT eredita la collation dalla colonna sorgente.
-- La forma precedente dichiarava la tabella con la collation di DEFAULT del
-- database, e su installazioni in cui cm_intervention_reports ha una collation
-- diversa il JOIN falliva con "Illegal mix of collations".
CREATE TABLE `tmp_ir_dupes` AS
SELECT MIN(`id`) AS `keep_id`, `source_uid`
  FROM `cm_intervention_reports`
 WHERE `source_uid` IS NOT NULL AND `source_uid` <> ''
 GROUP BY `source_uid`;

ALTER TABLE `tmp_ir_dupes`
    ADD INDEX `idx_uid`  (`source_uid`),
    ADD INDEX `idx_keep` (`keep_id`);

DELETE r FROM `cm_intervention_reports` r
  JOIN `tmp_ir_dupes` d ON d.`source_uid` = r.`source_uid`
 WHERE r.`id` <> d.`keep_id`;

DROP TABLE IF EXISTS `tmp_ir_dupes`;

-- -----------------------------------------------------------------------------
-- 4. Vincolo unico sulla grana. Da qui in avanti nessun canale puo' inserire
--    due volte la stessa prestazione: e' il vincolo, non la disciplina del
--    codice applicativo, a garantirlo.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports`
    ADD UNIQUE KEY IF NOT EXISTS `uq_ir_source_uid` (`source_uid`);

ALTER TABLE `cm_intervention_reports`
    ADD INDEX IF NOT EXISTS `idx_ir_source_system` (`source_system`),
    ADD INDEX IF NOT EXISTS `idx_ir_report_code` (`report_code`);

-- -----------------------------------------------------------------------------
-- 6. Vista di rendicontazione analitica.
--
--    Espone i fatti alla grana dichiarata con le dimensioni conformi
--    (commessa, cliente, tecnico, unita organizzativa, tempo). Serve a due
--    scopi: dare un punto unico da cui leggere i consuntivi, e rendere
--    evidente in un solo posto quali sono le misure additive.
--
--    Le misure additive sono le ore e gli importi. Le percentuali e i rapporti
--    NON sono additivi e vanno ricalcolati a ogni livello di aggregazione:
--    per questo la vista non li espone.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_rendicontazione` AS
SELECT
    r.`id`                                        AS fact_id,
    r.`source_uid`                                AS grana_uid,
    r.`source_system`                             AS canale,
    r.`report_code`                               AS codice_rapporto,
    r.`dgb_activity_code`                         AS codice_attivita_dgb,
    r.`report_date`                               AS data_rapporto,
    YEAR(r.`report_date`)                         AS anno,
    QUARTER(r.`report_date`)                      AS trimestre,
    MONTH(r.`report_date`)                        AS mese,
    DATE_FORMAT(r.`report_date`, '%Y-%m')         AS anno_mese,
    p.`id`                                        AS commessa_id,
    p.`project_code`                              AS commessa_codice,
    p.`name`                                      AS commessa_nome,
    p.`service_line`                              AS linea_servizio,
    p.`operational_status`                        AS commessa_stato,
    COALESCE(cl.`name`, r.`client_raw`)           AS cliente,
    co.`name`                                     AS azienda_esecutrice,
    r.`technician_raw`                            AS tecnico,
    tu.`name`                                     AS unita_organizzativa,
    ts.`name`                                     AS sotto_unita,
    tp.`seniority`                                AS seniority,
    COALESCE(tp.`on_call_h24`, 0)                 AS reperibile_h24,
    r.`service_type`                              AS tipo_servizio,
    COALESCE(r.`remote`, 0)                       AS da_remoto,
    COALESCE(r.`on_call`, 0)                      AS in_reperibilita,
    COALESCE(r.`approved`, 0)                     AS approvato,
    COALESCE(r.`planned_hours`, 0)                AS ore_pianificate,
    COALESCE(r.`quantity_hours`, 0)               AS ore_consuntivate,
    COALESCE(r.`extra_hours`, 0)                  AS ore_extra,
    COALESCE(r.`quantity_hours`, 0) - COALESCE(r.`planned_hours`, 0) AS ore_scostamento,
    COALESCE(r.`client_revenue_import`, 0)        AS ricavo,
    COALESCE(r.`company_cost_import`, 0)          AS costo,
    COALESCE(r.`client_revenue_import`, 0) - COALESCE(r.`company_cost_import`, 0) AS margine
FROM `cm_intervention_reports` r
LEFT JOIN `cm_projects`      p  ON p.`id`  = r.`project_id`
LEFT JOIN `clients`          cl ON cl.`id` = r.`client_id`
LEFT JOIN `companies`        co ON co.`id` = p.`exec_company_id`
LEFT JOIN `cm_tech_profiles` tp ON tp.`employee_id` = r.`technician_id`
                                OR tp.`professional_id` = r.`technician_professional_id`
LEFT JOIN `cm_tech_units`    tu ON tu.`id` = tp.`unit_id`
LEFT JOIN `cm_tech_subunits` ts ON ts.`id` = tp.`subunit_id`;

-- -----------------------------------------------------------------------------
-- 7. Controllo di integrita' della grana, consultabile dalla pagina di
--    riconciliazione. Un valore diverso da zero in `duplicati` significa che
--    un canale ha aggirato il vincolo e va corretto prima di fidarsi dei totali.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_grana_check` AS
SELECT
    (SELECT COUNT(*) FROM `cm_intervention_reports`)                                AS righe_totali,
    (SELECT COUNT(DISTINCT `source_uid`) FROM `cm_intervention_reports`)            AS grane_distinte,
    (SELECT COUNT(*) FROM `cm_intervention_reports` WHERE `source_uid` IS NULL)     AS senza_grana,
    (SELECT COUNT(*) FROM (SELECT `source_uid` FROM `cm_intervention_reports`
                            WHERE `source_uid` IS NOT NULL
                            GROUP BY `source_uid` HAVING COUNT(*) > 1) x)           AS duplicati,
    (SELECT COUNT(*) FROM `cm_intervention_reports` WHERE `report_code` LIKE '%/%') AS codici_con_suffisso,
    (SELECT ROUND(COALESCE(SUM(`quantity_hours`), 0), 2) FROM `cm_intervention_reports`) AS ore_consuntivate;

INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('app_version',    '1.8.50', 'Versione applicazione'),
    ('schema_version', '1.8.50', 'Versione schema database'),
    ('release_label',  '1.8.50', 'Etichetta release mostrata in footer')
ON DUPLICATE KEY UPDATE
    `setting_value` = VALUES(`setting_value`);

SET FOREIGN_KEY_CHECKS=1;

-- ════════════════════════════════════════════════════════════════
-- v1.8.51 — La grana diventa una garanzia del database (trigger)
-- ════════════════════════════════════════════════════════════════
-- 1. Recupero delle righe rimaste senza grana
--    (inserite da un canale non allineato fra la v1.8.50 e questa release)
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports`
   SET `source_uid` = CONCAT(
           SUBSTRING_INDEX(`report_code`, '/', 1), '#',
           COALESCE(CAST(`technician_id` AS CHAR),
                    CAST(`technician_professional_id` AS CHAR),
                    NULLIF(TRIM(`technician_raw`), ''),
                    '0'))
 WHERE `source_uid` IS NULL AND `report_code` IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 2. Rimozione dei duplicati eventualmente creati dai canali non allineati.
--    Si conserva la riga con id piu' basso, come nella v1.8.50.
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_ir_dupes51`;
-- v1.8.66: CREATE ... AS SELECT eredita la collation dalla colonna sorgente.
-- La forma precedente dichiarava la tabella con la collation di DEFAULT del
-- database, e su installazioni in cui cm_intervention_reports ha una collation
-- diversa il JOIN falliva con "Illegal mix of collations".
CREATE TABLE `tmp_ir_dupes51` AS
SELECT MIN(`id`) AS `keep_id`, `source_uid`
  FROM `cm_intervention_reports`
 WHERE `source_uid` IS NOT NULL AND `source_uid` <> ''
 GROUP BY `source_uid`;

ALTER TABLE `tmp_ir_dupes51`
    ADD INDEX `idx_uid51`  (`source_uid`),
    ADD INDEX `idx_keep51` (`keep_id`);

DELETE r FROM `cm_intervention_reports` r
  JOIN `tmp_ir_dupes51` d ON d.`source_uid` = r.`source_uid`
 WHERE r.`id` <> d.`keep_id`;

DROP TABLE IF EXISTS `tmp_ir_dupes51`;

-- -----------------------------------------------------------------------------
-- 3. Trigger di calcolo della grana.
--
--    DROP e CREATE anziche' CREATE OR REPLACE: quest'ultimo non e' supportato da
--    tutte le versioni di MariaDB in uso, mentre DROP IF EXISTS lo e'.
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS `trg_ir_grana_ins`;
CREATE TRIGGER `trg_ir_grana_ins` BEFORE INSERT ON `cm_intervention_reports`
FOR EACH ROW
    SET NEW.`source_uid` = COALESCE(
        NULLIF(TRIM(NEW.`source_uid`), ''),
        CONCAT(
            SUBSTRING_INDEX(COALESCE(NEW.`report_code`, ''), '/', 1), '#',
            COALESCE(CAST(NEW.`technician_id` AS CHAR),
                     CAST(NEW.`technician_professional_id` AS CHAR),
                     NULLIF(TRIM(NEW.`technician_raw`), ''),
                     '0')));

DROP TRIGGER IF EXISTS `trg_ir_grana_upd`;
CREATE TRIGGER `trg_ir_grana_upd` BEFORE UPDATE ON `cm_intervention_reports`
FOR EACH ROW
    SET NEW.`source_uid` = COALESCE(
        NULLIF(TRIM(NEW.`source_uid`), ''),
        NULLIF(TRIM(OLD.`source_uid`), ''),
        CONCAT(
            SUBSTRING_INDEX(COALESCE(NEW.`report_code`, ''), '/', 1), '#',
            COALESCE(CAST(NEW.`technician_id` AS CHAR),
                     CAST(NEW.`technician_professional_id` AS CHAR),
                     NULLIF(TRIM(NEW.`technician_raw`), ''),
                     '0')));

-- -----------------------------------------------------------------------------
-- 4. Ora che nessuna riga puo' nascere senza grana, la colonna diventa
--    obbligatoria: un UNIQUE su colonna nullable non impedisce i duplicati,
--    perche' NULL non collide con NULL.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports`
    MODIFY COLUMN `source_uid` varchar(120) NOT NULL DEFAULT ''
    COMMENT 'Chiave di grana: <codice rapporto>#<identificativo tecnico>. Calcolata dal trigger se non fornita.';

-- -----------------------------------------------------------------------------
-- 5. Controllo di integrita' esteso: distingue le righe per canale, cosi' un
--    canale che sbaglia si individua senza doverlo cercare.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_grana_check` AS
SELECT
    (SELECT COUNT(*) FROM `cm_intervention_reports`)                                AS righe_totali,
    (SELECT COUNT(DISTINCT `source_uid`) FROM `cm_intervention_reports`)            AS grane_distinte,
    (SELECT COUNT(*) FROM `cm_intervention_reports` WHERE `source_uid` = '')        AS senza_grana,
    (SELECT COUNT(*) FROM (SELECT `source_uid` FROM `cm_intervention_reports`
                            WHERE `source_uid` <> ''
                            GROUP BY `source_uid` HAVING COUNT(*) > 1) x)           AS duplicati,
    (SELECT COUNT(*) FROM `cm_intervention_reports` WHERE `report_code` LIKE '%/%') AS codici_con_suffisso,
    (SELECT COUNT(*) FROM `cm_intervention_reports` WHERE `source_uid` LIKE '%#0')  AS tecnico_non_identificato,
    (SELECT ROUND(COALESCE(SUM(`quantity_hours`), 0), 2) FROM `cm_intervention_reports`) AS ore_consuntivate;

CREATE OR REPLACE VIEW `v_cm_grana_per_canale` AS
SELECT
    COALESCE(`source_system`, 'non indicato') AS canale,
    COUNT(*)                                  AS righe,
    COUNT(DISTINCT `source_uid`)              AS grane_distinte,
    COUNT(*) - COUNT(DISTINCT `source_uid`)   AS eccedenza,
    ROUND(COALESCE(SUM(`quantity_hours`), 0), 2) AS ore
FROM `cm_intervention_reports`
GROUP BY COALESCE(`source_system`, 'non indicato');

