-- ════════════════════════════════════════════════════════════════
-- v1.8.53 — Orario ordinario e reperibilita': regola aziendale sul consuntivo
-- ════════════════════════════════════════════════════════════════
--    In app_settings e non cablati nel codice: un cambio di orario aziendale
--    non deve richiedere una release.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`) VALUES
    ('work_ordinary_start',  '09:00', 'Inizio orario ordinario (HH:MM)'),
    ('work_ordinary_end',    '18:00', 'Fine orario ordinario (HH:MM)'),
    ('work_break_start',     '13:00', 'Inizio pausa pranzo (HH:MM)'),
    ('work_break_end',       '14:00', 'Fine pausa pranzo (HH:MM)'),
    ('work_ordinary_days',   '1,2,3,4,5', 'Giorni feriali (1=lunedi ... 7=domenica)'),
    ('work_ordinary_hours',  '8', 'Ore ordinarie per giornata lavorativa')
ON DUPLICATE KEY UPDATE `setting_value` = `setting_value`;

-- -----------------------------------------------------------------------------
-- 2. Vista di classificazione oraria.
--
--    Per ogni allocazione calcola la quota di ore ordinarie e di reperibilita'.
--    Il calcolo dell'intersezione usa i secondi dall'inizio della giornata:
--
--       sovrapposizione = MAX(0, MIN(fine, limite_alto) - MAX(inizio, limite_basso))
--
--    applicata alle due fasce 09-13 e 14-18, la cui somma da' i secondi
--    ordinari. La frazione ordinaria e' quel valore diviso la durata totale
--    dell'intervallo, e moltiplica le ore consuntivate.
--
--    Interventi che attraversano la mezzanotte (0,58% del totale) sono
--    classificati in base al giorno e all'orario di inizio: spezzarli
--    richiederebbe una tabella calendario e l'approssimazione e' ampiamente
--    entro il margine di altre incertezze del dato.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_ore_classificate` AS
SELECT
    ao.`id`                                   AS allocation_id,
    ao.`id_activity`                          AS activity_id,
    ao.`id_operator`                          AS operator_id,
    a.`code`                                  AS activity_code,
    a.`id_contract`                           AS contract_id,
    COALESCE(a.`report_date`, DATE(a.`date_start`)) AS giorno,
    a.`date_start`                            AS inizio,
    a.`date_dead_line`                        AS fine,
    DAYOFWEEK(a.`date_start`)                 AS dow_sql,
    COALESCE(pr.`schedule_type`, 'ordinario') AS tipo_orario,
    ao.`hours`                                AS ore_consuntivate,
    ao.`extra_hours`                          AS ore_extra_dichiarate,

    -- frazione dell'intervallo che cade nella finestra ordinaria
    CASE
        -- i turnisti non sono soggetti alla regola
        WHEN COALESCE(pr.`schedule_type`, 'ordinario') = 'turni' THEN 1.0
        -- sabato (7) e domenica (1) secondo la numerazione di DAYOFWEEK
        WHEN DAYOFWEEK(a.`date_start`) IN (1, 7) THEN 0.0
        WHEN a.`date_start` IS NULL OR a.`date_dead_line` IS NULL THEN 1.0
        -- intervallo nullo o negativo: si classifica sull'istante di inizio
        WHEN TIMESTAMPDIFF(SECOND, a.`date_start`, a.`date_dead_line`) <= 0 THEN
            CASE WHEN (TIME(a.`date_start`) >= '09:00:00' AND TIME(a.`date_start`) < '13:00:00')
                   OR (TIME(a.`date_start`) >= '14:00:00' AND TIME(a.`date_start`) < '18:00:00')
                 THEN 1.0 ELSE 0.0 END
        ELSE LEAST(1.0, GREATEST(0.0,
              ( GREATEST(0, LEAST(TIME_TO_SEC(TIME(a.`date_dead_line`)), 46800)
                          - GREATEST(TIME_TO_SEC(TIME(a.`date_start`)), 32400))
              + GREATEST(0, LEAST(TIME_TO_SEC(TIME(a.`date_dead_line`)), 64800)
                          - GREATEST(TIME_TO_SEC(TIME(a.`date_start`)), 50400))
              ) / NULLIF(TIMESTAMPDIFF(SECOND, a.`date_start`, a.`date_dead_line`), 0)))
    END AS frazione_ordinaria
FROM `dgb_forms_activity_operator` ao
JOIN `dgb_forms_activity` a ON a.`id` = ao.`id_activity`
LEFT JOIN `dgb_operator_profile` pr ON pr.`dgb_operator_id` = ao.`id_operator`
WHERE COALESCE(a.`deleted`, 0) = 0;

-- -----------------------------------------------------------------------------
-- 3. Vista di consuntivo con le ore gia' ripartite.
--
--    Solo la quota ordinaria e' calcolata come prodotto, mentre la reperibilita' si
--    ricava per DIFFERENZA. Calcolando entrambe come prodotto, gli
--    arrotondamenti al centesimo su decine di migliaia di righe producevano uno
--    scarto di alcune ore fra la somma delle componenti e il totale
--    consuntivato: piccolo, ma sufficiente a far dubitare di una quadratura.
--    Derivando la seconda componente, la somma e' esatta per costruzione.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_ore_ripartite` AS
SELECT
    c.*,
    ROUND(c.`ore_consuntivate` * c.`frazione_ordinaria`, 2) AS ore_ordinarie,
    ROUND(c.`ore_consuntivate`, 2)
      - ROUND(c.`ore_consuntivate` * c.`frazione_ordinaria`, 2) AS ore_reperibilita,
    CASE
        WHEN c.`tipo_orario` = 'turni'        THEN 'turni'
        WHEN c.`dow_sql` IN (1, 7)            THEN 'weekend'
        WHEN c.`frazione_ordinaria` >= 0.999  THEN 'ordinario'
        WHEN c.`frazione_ordinaria` <= 0.001  THEN 'fuori orario'
        ELSE 'misto'
    END AS classificazione
FROM `v_dgb_ore_classificate` c;

-- -----------------------------------------------------------------------------
-- 4. Controllo di quadratura. `scarto` deve essere zero: se non lo e', la
--    ripartizione sta perdendo o creando ore e i totali non sono affidabili.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_ore_check` AS
SELECT
    COUNT(*)                                              AS allocazioni,
    ROUND(SUM(`ore_consuntivate`), 2)                     AS ore_consuntivate,
    ROUND(SUM(`ore_ordinarie`), 2)                        AS ore_ordinarie,
    ROUND(SUM(`ore_reperibilita`), 2)                     AS ore_reperibilita,
    ROUND(SUM(`ore_ordinarie`) + SUM(`ore_reperibilita`)
          - SUM(`ore_consuntivate`), 2)                   AS scarto,
    ROUND(100 * SUM(`ore_reperibilita`)
          / NULLIF(SUM(`ore_consuntivate`), 0), 2)        AS pct_reperibilita
FROM `v_dgb_ore_ripartite`;

