-- ════════════════════════════════════════════════════════════════
-- v1.8.54 — Segnalazione delle anomalie di imputazione oraria
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
-- 1. Soglie configurabili
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`) VALUES
    ('anomaly_hours_day_max',   '24', 'Ore giornaliere oltre le quali l anomalia e certa'),
    ('anomaly_hours_day_warn',  '12', 'Ore giornaliere oltre le quali segnalare per verifica'),
    ('anomaly_min_projects',     '2', 'Numero minimo di commesse con ore identiche per segnalare')
ON DUPLICATE KEY UPDATE `setting_value` = `setting_value`;

-- -----------------------------------------------------------------------------
-- 2. Ore identiche imputate a piu' commesse.
--
--    Il raggruppamento e' su operatore, giorno, quantita' di ore e fascia
--    oraria di inizio. La fascia entra nella chiave perche' due interventi da
--    due ore svolti uno al mattino e uno al pomeriggio sono plausibili, mentre
--    due interventi da due ore che iniziano alla stessa ora su commesse diverse
--    non lo sono.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_anomalia_ore_duplicate` AS
SELECT
    ao.`id_operator`                                  AS operator_id,
    TRIM(CONCAT(COALESCE(op.`first_name`,''), ' ',
                COALESCE(op.`second_name`,'')))       AS tecnico,
    DATE(a.`date_start`)                              AS giorno,
    TIME(a.`date_start`)                              AS ora_inizio,
    ao.`hours`                                        AS ore_per_riga,
    COUNT(DISTINCT a.`id_contract`)                   AS commesse_distinte,
    COUNT(*)                                          AS righe,
    ROUND(SUM(ao.`hours`), 2)                         AS ore_totali,
    -- il codice commessa si prende da cm_projects, riconciliata su
    -- dgb_contract_id: dgb_forms_contract e' vuota su questa installazione e
    -- avrebbe prodotto un dettaglio sempre nullo
    GROUP_CONCAT(DISTINCT COALESCE(c.`project_code`, CONCAT('contratto #', a.`id_contract`))
                 ORDER BY 1 SEPARATOR ', ') AS commesse,
    GROUP_CONCAT(DISTINCT a.`code` ORDER BY a.`code` SEPARATOR ', ') AS attivita
FROM `dgb_forms_activity_operator` ao
JOIN `dgb_forms_activity` a  ON a.`id` = ao.`id_activity`
LEFT JOIN `dgb_operator` op  ON op.`id` = ao.`id_operator`
LEFT JOIN `cm_projects` c    ON c.`dgb_contract_id` = a.`id_contract`
WHERE COALESCE(a.`deleted`, 0) = 0
  AND a.`date_start` IS NOT NULL
  AND ao.`hours` > 0
GROUP BY ao.`id_operator`, tecnico, DATE(a.`date_start`), TIME(a.`date_start`), ao.`hours`
HAVING COUNT(DISTINCT a.`id_contract`) > 1;

-- -----------------------------------------------------------------------------
-- 3. Ore giornaliere fuori scala
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_anomalia_ore_giorno` AS
SELECT
    ao.`id_operator`                                  AS operator_id,
    TRIM(CONCAT(COALESCE(op.`first_name`,''), ' ',
                COALESCE(op.`second_name`,'')))       AS tecnico,
    DATE(a.`date_start`)                              AS giorno,
    ROUND(SUM(ao.`hours`), 2)                         AS ore_giorno,
    COUNT(*)                                          AS righe,
    COUNT(DISTINCT a.`id_contract`)                   AS commesse_distinte,
    CASE WHEN SUM(ao.`hours`) > 24 THEN 'alta' ELSE 'media' END AS severita
FROM `dgb_forms_activity_operator` ao
JOIN `dgb_forms_activity` a ON a.`id` = ao.`id_activity`
LEFT JOIN `dgb_operator` op ON op.`id` = ao.`id_operator`
WHERE COALESCE(a.`deleted`, 0) = 0 AND a.`date_start` IS NOT NULL
GROUP BY ao.`id_operator`, tecnico, DATE(a.`date_start`)
HAVING SUM(ao.`hours`) > 12;

-- -----------------------------------------------------------------------------
-- 4. Elenco unificato delle anomalie, con severita'.
--
--    Le due famiglie sono unite in una sola vista perche' chi controlla vuole
--    un elenco unico ordinato per gravita', non tre elenchi da confrontare.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_anomalie_orario` AS
SELECT
    'ore_duplicate'    AS tipo,
    'alta'             AS severita,
    d.`operator_id`, d.`tecnico`, d.`giorno`,
    d.`ore_totali`     AS ore,
    d.`commesse_distinte`, d.`righe`,
    CONCAT('Stesse ', d.`ore_per_riga`, ' h imputate a ', d.`commesse_distinte`,
           ' commesse con inizio alle ', d.`ora_inizio`) AS descrizione,
    d.`commesse`       AS dettaglio
FROM `v_dgb_anomalia_ore_duplicate` d
UNION ALL
SELECT
    'ore_giornaliere'  AS tipo,
    g.`severita`,
    g.`operator_id`, g.`tecnico`, g.`giorno`,
    g.`ore_giorno`     AS ore,
    g.`commesse_distinte`, g.`righe`,
    CONCAT(g.`ore_giorno`, ' h imputate in una sola giornata su ',
           g.`commesse_distinte`, ' commesse') AS descrizione,
    NULL               AS dettaglio
FROM `v_dgb_anomalia_ore_giorno` g;

-- -----------------------------------------------------------------------------
-- 5. Riepilogo per la pagina
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_anomalie_riepilogo` AS
SELECT
    `tipo`, `severita`,
    COUNT(*)                        AS segnalazioni,
    COUNT(DISTINCT `operator_id`)   AS tecnici_coinvolti,
    ROUND(SUM(`ore`), 2)            AS ore_coinvolte,
    MIN(`giorno`)                   AS dal,
    MAX(`giorno`)                   AS al
FROM `v_dgb_anomalie_orario`
GROUP BY `tipo`, `severita`;

