-- ════════════════════════════════════════════════════════════════
-- v1.8.55 — Flag di reperibilita' proposto dai consuntivi
-- ════════════════════════════════════════════════════════════════
-- reperibilita' senza aver ricevuto chiamate, e non comparirebbe mai.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Soglie configurabili
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`) VALUES
    ('oncall_min_days',      '5',  'Giornate distinte in reperibilita per proporre il flag'),
    ('oncall_window_months', '12', 'Mesi di osservazione dei consuntivi'),
    ('oncall_h24_min_days',  '5',  'Giornate notturne o festive per proporre il flag H24'),
    ('oncall_night_from',    '22', 'Ora dalla quale un intervento e considerato notturno'),
    ('oncall_night_to',      '6',  'Ora fino alla quale un intervento e considerato notturno')
ON DUPLICATE KEY UPDATE `setting_value` = `setting_value`;

-- -----------------------------------------------------------------------------
-- 2. Evidenze di reperibilita' per operatore del gestionale.
--
--    Il collegamento verso l'anagrafica del portale avviene per due strade
--    alternative, entrambe gia' presenti:
--      dgb_operator_map.employee_id          -> tecnico interno
--      cm_professionals.source_operator_id   -> professionista esterno
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_tech_oncall_evidenze` AS
SELECT
    r.`operator_id`,
    TRIM(CONCAT(COALESCE(op.`first_name`,''), ' ',
                COALESCE(op.`second_name`,'')))          AS tecnico,
    map.`employee_id`                                    AS employee_id,
    pf.`id`                                              AS professional_id,
    COUNT(DISTINCT r.`giorno`)                           AS giornate_reperibilita,
    ROUND(SUM(r.`ore_reperibilita`), 2)                  AS ore_reperibilita,
    COUNT(DISTINCT CASE WHEN HOUR(r.`inizio`) >= 22 OR HOUR(r.`inizio`) < 6
                        THEN r.`giorno` END)             AS giornate_notturne,
    COUNT(DISTINCT CASE WHEN r.`dow_sql` IN (1,7)
                        THEN r.`giorno` END)             AS giornate_festive,
    MIN(r.`giorno`)                                      AS dal,
    MAX(r.`giorno`)                                      AS al
FROM `v_dgb_ore_ripartite` r
LEFT JOIN `dgb_operator`      op  ON op.`id`  = r.`operator_id`
LEFT JOIN `dgb_operator_map`  map ON map.`dgb_operator_id` = r.`operator_id`
LEFT JOIN `cm_professionals`  pf  ON pf.`source_operator_id` = r.`operator_id`
WHERE r.`ore_reperibilita` > 0
  AND r.`giorno` >= DATE_SUB(CURDATE(), INTERVAL 12 MONTH)
GROUP BY r.`operator_id`, tecnico, map.`employee_id`, pf.`id`;

-- -----------------------------------------------------------------------------
-- 3. Proposta di flag, confrontata con lo stato attuale del profilo.
--
--    `azione` distingue i tre casi che interessano a chi decide: da attivare,
--    gia' corretto, oppure attivo nel profilo ma senza evidenze recenti — che
--    non e' un errore, perche' un turno di reperibilita' senza chiamate non
--    lascia traccia nei consuntivi.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_tech_oncall_proposta` AS
SELECT
    e.`operator_id`, e.`tecnico`, e.`employee_id`, e.`professional_id`,
    tp.`id`                                   AS profile_id,
    COALESCE(tp.`on_call`, 0)                 AS on_call_attuale,
    COALESCE(tp.`on_call_h24`, 0)             AS on_call_h24_attuale,
    e.`giornate_reperibilita`, e.`ore_reperibilita`,
    e.`giornate_notturne`, e.`giornate_festive`, e.`dal`, e.`al`,
    CASE WHEN e.`giornate_reperibilita` >= 5 THEN 1 ELSE 0 END AS on_call_proposto,
    CASE WHEN e.`giornate_notturne` >= 5
           OR e.`giornate_festive`  >= 5 THEN 1 ELSE 0 END      AS on_call_h24_proposto,
    CASE
        WHEN tp.`id` IS NULL THEN 'profilo assente'
        WHEN e.`giornate_reperibilita` >= 5 AND COALESCE(tp.`on_call`,0) = 0 THEN 'da attivare'
        WHEN e.`giornate_reperibilita` >= 5 AND COALESCE(tp.`on_call`,0) = 1 THEN 'gia corretto'
        ELSE 'sotto soglia'
    END AS azione
FROM `v_tech_oncall_evidenze` e
LEFT JOIN `cm_tech_profiles` tp
       ON (e.`employee_id`     IS NOT NULL AND tp.`employee_id`     = e.`employee_id`)
       OR (e.`professional_id` IS NOT NULL AND tp.`professional_id` = e.`professional_id`);

-- -----------------------------------------------------------------------------
-- 4. Riepilogo per la pagina
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_tech_oncall_riepilogo` AS
SELECT
    `azione`,
    COUNT(*)                                      AS tecnici,
    SUM(`on_call_proposto`)                       AS proposti_reperibili,
    SUM(`on_call_h24_proposto`)                   AS proposti_h24,
    ROUND(SUM(`ore_reperibilita`), 2)             AS ore
FROM `v_tech_oncall_proposta`
GROUP BY `azione`;

