-- ════════════════════════════════════════════════════════════════
-- v1.8.57 — Base dati economica: tariffe, allocazioni, costi fascia
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Tariffe di contratto
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_contract_rates` (
    `id`              int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`       int(11)       DEFAULT NULL COMMENT 'id nella sorgente',
    `project_id`      int(11)       DEFAULT NULL,
    `project_code`    varchar(50)   DEFAULT NULL,
    `activity_type`   varchar(80)   DEFAULT NULL,
    `rate_nature`     varchar(4)    DEFAULT NULL COMMENT 'R ricavo, C costo',
    `rate_unit`       varchar(8)    DEFAULT NULL COMMENT 'H ora, D giorno, HD mezza, EH extra',
    `rate_value`      decimal(12,4) DEFAULT NULL,
    `import_batch_id` int(11)       DEFAULT NULL,
    `created_at`      datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`      datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_rate_source` (`source_id`),
    KEY `idx_rate_project` (`project_id`),
    KEY `idx_rate_code`    (`project_code`),
    KEY `idx_rate_lookup`  (`project_code`, `rate_nature`, `rate_unit`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. Allocazioni pianificate operatore/commessa
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_project_allocations` (
    `id`              int(11)     NOT NULL AUTO_INCREMENT,
    `source_id`       int(11)     DEFAULT NULL,
    `operator_id`     int(11)     DEFAULT NULL COMMENT 'id operatore nella sorgente',
    `operator_name`   varchar(150) DEFAULT NULL,
    `project_id`      int(11)     DEFAULT NULL,
    `project_code`    varchar(50) DEFAULT NULL,
    `activity_type`   varchar(80) DEFAULT NULL,
    `alloc_type`      varchar(20) DEFAULT NULL,
    `start_date`      date        DEFAULT NULL,
    `end_date`        date        DEFAULT NULL,
    `import_batch_id` int(11)     DEFAULT NULL,
    `created_at`      datetime    NOT NULL DEFAULT current_timestamp(),
    `updated_at`      datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_alloc_source` (`source_id`),
    KEY `idx_alloc_op`      (`operator_id`),
    KEY `idx_alloc_project` (`project_id`),
    KEY `idx_alloc_code`    (`project_code`),
    KEY `idx_alloc_period`  (`start_date`, `end_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. Costi orari delle fasce.
--    Le fasce esistono gia' in cm_rate_bands ma senza importi: il costo reale
--    stava solo nel gestionale, ed e' il dato che mancava per calcolare un
--    margine per persona.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_band_costs` (
    `id`            int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`     int(11)       DEFAULT NULL,
    `band_name`     varchar(150)  NOT NULL,
    `hourly_cost`   decimal(12,4) DEFAULT NULL,
    `daily_cost`    decimal(12,4) DEFAULT NULL,
    `full_cost_from` decimal(12,4) DEFAULT NULL,
    `full_cost_to`   decimal(12,4) DEFAULT NULL,
    `is_active`     tinyint(1)    NOT NULL DEFAULT 1,
    `created_at`    datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`    datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_band_cost_name` (`band_name`),
    KEY `idx_band_cost_source` (`source_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 4. Marginalita' per prestazione.
--
--    Il ricavo dichiarato nel consuntivo resta la fonte primaria: la tariffa di
--    contratto serve al CONFRONTO, non a sostituirlo. Dove il ricavo dichiarato
--    manca, la tariffa fornisce una stima, marcata come tale — un valore stimato
--    non deve essere indistinguibile da uno rilevato.
--
--    Il costo segue la stessa logica: costo dichiarato se presente, altrimenti
--    fascia oraria x ore.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_marginalita` AS
SELECT
    r.`id`                                    AS fact_id,
    r.`source_uid`                            AS grana_uid,
    r.`report_code`                           AS codice_rapporto,
    r.`report_date`                           AS data_rapporto,
    DATE_FORMAT(r.`report_date`, '%Y-%m')     AS anno_mese,
    p.`project_code`                          AS commessa,
    p.`name`                                  AS commessa_nome,
    p.`service_line`                          AS linea_servizio,
    COALESCE(cl.`name`, r.`client_raw`)       AS cliente,
    r.`technician_raw`                        AS tecnico,
    r.`band_raw`                              AS fascia,
    tu.`name`                                 AS unita_organizzativa,
    COALESCE(r.`quantity_hours`, 0)           AS ore,
    COALESCE(r.`extra_hours`, 0)              AS ore_extra,

    -- ricavo: dichiarato se presente, altrimenti stimato dalla tariffa oraria
    COALESCE(NULLIF(r.`client_revenue_import`, 0),
             ROUND(COALESCE(r.`quantity_hours`,0) * rt.`rate_value`, 2)) AS ricavo,
    CASE WHEN COALESCE(r.`client_revenue_import`,0) <> 0 THEN 'rilevato'
         WHEN rt.`rate_value` IS NOT NULL              THEN 'stimato da tariffa'
         ELSE 'non disponibile' END                                      AS ricavo_origine,
    rt.`rate_value`                           AS tariffa_oraria_contratto,
    COALESCE(rt.`n_rates`, 0)                 AS tariffe_disponibili,

    -- costo: dichiarato se presente, altrimenti stimato dalla fascia
    COALESCE(NULLIF(r.`company_cost_import`, 0),
             ROUND(COALESCE(r.`quantity_hours`,0) * bc.`hourly_cost`, 2)) AS costo,
    CASE WHEN COALESCE(r.`company_cost_import`,0) <> 0 THEN 'rilevato'
         WHEN bc.`hourly_cost` IS NOT NULL             THEN 'stimato da fascia'
         ELSE 'non disponibile' END                                       AS costo_origine,
    bc.`hourly_cost`                          AS costo_orario_fascia,

    COALESCE(NULLIF(r.`client_revenue_import`, 0),
             ROUND(COALESCE(r.`quantity_hours`,0) * rt.`rate_value`, 2))
    - COALESCE(NULLIF(r.`company_cost_import`, 0),
             ROUND(COALESCE(r.`quantity_hours`,0) * bc.`hourly_cost`, 2)) AS margine
FROM `cm_intervention_reports` r
LEFT JOIN `cm_projects`      p  ON p.`id` = r.`project_id`
LEFT JOIN `clients`          cl ON cl.`id` = r.`client_id`
LEFT JOIN `cm_tech_profiles` tp ON tp.`employee_id` = r.`technician_id`
                                OR tp.`professional_id` = r.`technician_professional_id`
LEFT JOIN `cm_tech_units`    tu ON tu.`id` = tp.`unit_id`
LEFT JOIN `cm_band_costs`    bc ON bc.`band_name` = r.`band_raw`
-- La tariffa e' AGGREGATA per commessa prima del join.
--
-- Il collaudo ha mostrato che una commessa ha in media SEI tariffe orarie di
-- ricavo, una per tipo di attivita': un join diretto moltiplicava le righe da
-- 67.723 a 379.247, gonfiando ogni somma di cinque volte. E' il fan-out
-- classico di un join verso una tabella a cardinalita' maggiore di uno.
--
-- Si usa la MEDIA delle tariffe orarie della commessa, non il minimo ne' il
-- massimo: la media e' la stima meno distorta quando non si sa a quale tipo di
-- attivita' l'intervento appartenga. La colonna `tariffe_disponibili` dice su
-- quante tariffe la media e' calcolata, cosi' chi legge sa quanto e' grossolana
-- la stima: con una sola tariffa e' esatta, con sei e' una media.
LEFT JOIN (
    SELECT `project_code`,
           ROUND(AVG(`rate_value`), 4) AS `rate_value`,
           COUNT(*)                    AS `n_rates`
      FROM `cm_contract_rates`
     WHERE `rate_nature` = 'R' AND `rate_unit` = 'H' AND `rate_value` > 0
     GROUP BY `project_code`
) rt ON rt.`project_code` = r.`project_code`;

-- -----------------------------------------------------------------------------
-- 5. Confronto fra effort pianificato e consuntivato per operatore e commessa.
--    Le allocazioni indicano un periodo di assegnazione, non un monte ore: il
--    confronto e' quindi sulla PRESENZA dell'assegnazione, non su una quantita'
--    che la sorgente non fornisce. Dichiararlo evita di leggere la vista come
--    uno scostamento orario, che non e'.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_effort_confronto` AS
SELECT
    a.`project_code`                                   AS commessa,
    a.`operator_name`                                  AS tecnico,
    a.`alloc_type`                                     AS tipo_allocazione,
    MIN(a.`start_date`)                                AS allocato_dal,
    MAX(a.`end_date`)                                  AS allocato_al,
    COUNT(DISTINCT a.`id`)                             AS allocazioni,
    COALESCE(c.`ore_consuntivate`, 0)                  AS ore_consuntivate,
    COALESCE(c.`interventi`, 0)                        AS interventi,
    CASE WHEN COALESCE(c.`interventi`, 0) = 0 THEN 'allocato senza consuntivo'
         ELSE 'allocato con consuntivo' END            AS stato
FROM `cm_project_allocations` a
LEFT JOIN (
    SELECT `project_code`, `technician_raw`,
           ROUND(SUM(COALESCE(`quantity_hours`,0)), 2) AS ore_consuntivate,
           COUNT(*)                                    AS interventi
      FROM `cm_intervention_reports`
     GROUP BY `project_code`, `technician_raw`
) c ON c.`project_code` = a.`project_code` AND c.`technician_raw` = a.`operator_name`
GROUP BY a.`project_code`, a.`operator_name`, a.`alloc_type`, c.`ore_consuntivate`, c.`interventi`;

