-- ════════════════════════════════════════════════════════════════
-- v1.8.58 — Modelli contrattuali e marginalita' differenziata
-- ════════════════════════════════════════════════════════════════
-- dichiararne l'assenza.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Registro dei modelli contrattuali.
--    In tabella e non cablato: le linee di servizio cambiano nel tempo e la
--    classificazione deve poter essere aggiornata senza una release.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_contract_models` (
    `id`               int(11)      NOT NULL AUTO_INCREMENT,
    `service_line`     varchar(60)  NOT NULL,
    `model`            varchar(20)  NOT NULL COMMENT 'interno, canone, presidio, chiavi_mano, a_scalare, a_chiamata, assistenza',
    `label`            varchar(120) DEFAULT NULL,
    `has_revenue`      tinyint(1)   NOT NULL DEFAULT 1 COMMENT '0 = attivita interna, nessun ricavo',
    `revenue_basis`    varchar(20)  DEFAULT NULL COMMENT 'ore, canone, valore_commessa, monte_ore, misto',
    `hours_consume`    tinyint(1)   NOT NULL DEFAULT 0 COMMENT '1 = le ore consumano un budget prepagato',
    `budget_overrun`   tinyint(1)   NOT NULL DEFAULT 0 COMMENT '1 = sforare il valore porta il margine in negativo',
    `notes`            varchar(400) DEFAULT NULL,
    `sort_order`       int(11)      NOT NULL DEFAULT 0,
    `is_active`        tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`       datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`       datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_model_line` (`service_line`),
    KEY `idx_model` (`model`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

