-- -----------------------------------------------------------------------------
-- 2. Marginalita' con la logica corretta per ciascun modello.
--
--    La differenza sostanziale rispetto alla v1.8.57 e' che il ricavo NON viene
--    piu' stimato dalle ore per i modelli in cui non dipende dalle ore. Dove il
--    ricavo non e' attribuibile alla singola prestazione, la colonna e' NULL e
--    `ricavo_origine` lo dichiara: un NULL onesto e' preferibile a un numero
--    inventato che poi qualcuno somma.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_marginalita_modello` AS
SELECT
    r.`id`                                     AS fact_id,
    r.`report_code`                            AS codice_rapporto,
    r.`report_date`                            AS data_rapporto,
    DATE_FORMAT(r.`report_date`, '%Y-%m')      AS anno_mese,
    p.`project_code`                           AS commessa,
    p.`service_line`                           AS linea_servizio,
    COALESCE(m.`model`, 'da_classificare')     AS modello,
    COALESCE(m.`label`, p.`service_line`)      AS modello_label,
    COALESCE(m.`has_revenue`, 1)               AS ha_ricavo,
    COALESCE(cl.`name`, r.`client_raw`)        AS cliente,
    r.`technician_raw`                         AS tecnico,
    tu.`name`                                  AS unita_organizzativa,
    COALESCE(r.`quantity_hours`, 0)            AS ore,

    -- COSTO: sempre calcolabile, ed e' la grandezza che non dipende dal modello
    COALESCE(NULLIF(r.`company_cost_import`, 0),
             ROUND(COALESCE(r.`quantity_hours`,0) * bc.`hourly_cost`, 2)) AS costo,
    CASE WHEN COALESCE(r.`company_cost_import`,0) <> 0 THEN 'rilevato'
         WHEN bc.`hourly_cost` IS NOT NULL             THEN 'stimato da fascia'
         ELSE 'non disponibile' END                                       AS costo_origine,

    -- RICAVO: attribuibile alla prestazione solo per i modelli a consumo
    CASE
        WHEN COALESCE(m.`has_revenue`, 1) = 0 THEN NULL
        WHEN COALESCE(r.`client_revenue_import`, 0) <> 0 THEN r.`client_revenue_import`
        WHEN COALESCE(m.`revenue_basis`, 'ore') IN ('ore') AND rt.`rate_value` IS NOT NULL
             THEN ROUND(COALESCE(r.`quantity_hours`,0) * rt.`rate_value`, 2)
        ELSE NULL
    END                                                                   AS ricavo,
    CASE
        WHEN COALESCE(m.`has_revenue`, 1) = 0 THEN 'attivita interna: nessun ricavo'
        WHEN COALESCE(r.`client_revenue_import`, 0) <> 0 THEN 'rilevato'
        WHEN COALESCE(m.`revenue_basis`, 'ore') IN ('ore') AND rt.`rate_value` IS NOT NULL
             THEN 'stimato da tariffa'
        WHEN m.`revenue_basis` = 'canone'          THEN 'a canone: ricavo non per prestazione'
        WHEN m.`revenue_basis` = 'valore_commessa' THEN 'da valore commessa: non per prestazione'
        WHEN m.`revenue_basis` = 'monte_ore'       THEN 'a scalare: consuma il monte ore prepagato'
        WHEN m.`revenue_basis` = 'misto'           THEN 'misto materiale e ore: non per prestazione'
        ELSE 'non disponibile'
    END                                                                   AS ricavo_origine
FROM `cm_intervention_reports` r
LEFT JOIN `cm_projects`         p  ON p.`id` = r.`project_id`
LEFT JOIN `cm_contract_models`  m  ON m.`service_line` = p.`service_line`
LEFT JOIN `clients`             cl ON cl.`id` = r.`client_id`
LEFT JOIN `cm_tech_profiles`    tp ON tp.`employee_id` = r.`technician_id`
                                   OR tp.`professional_id` = r.`technician_professional_id`
LEFT JOIN `cm_tech_units`       tu ON tu.`id` = tp.`unit_id`
LEFT JOIN `cm_band_costs`       bc ON bc.`band_name` = r.`band_raw`
LEFT JOIN (
    SELECT `project_code`, ROUND(AVG(`rate_value`), 4) AS `rate_value`
      FROM `cm_contract_rates`
     WHERE `rate_nature` = 'R' AND `rate_unit` = 'H' AND `rate_value` > 0
     GROUP BY `project_code`
) rt ON rt.`project_code` = r.`project_code`;

-- -----------------------------------------------------------------------------
-- 3. Redditivita' a livello di COMMESSA.
--
--    Per canone, chiavi in mano, presidio e a scalare la marginalita' si legge
--    solo qui: il ricavo sta sulla commessa, il costo si accumula sugli
--    interventi. Confrontarli alla grana dell'intervento non ha senso.
--
--    `consumo_valore_pct` e' l'indicatore chiave dei contratti chiavi in mano e
--    a scalare: quanta parte del valore pattuito e' gia' stata consumata dal
--    costo. Sopra il 100% la commessa e' in perdita.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_redditivita_commessa` AS
SELECT
    p.`id`                                   AS commessa_id,
    p.`project_code`                         AS commessa,
    p.`name`                                 AS denominazione,
    p.`service_line`                         AS linea_servizio,
    COALESCE(m.`model`, 'da_classificare')   AS modello,
    COALESCE(m.`label`, p.`service_line`)    AS modello_label,
    COALESCE(m.`has_revenue`, 1)             AS ha_ricavo,
    COALESCE(m.`budget_overrun`, 0)          AS sforamento_critico,
    COALESCE(cl.`name`, p.`client_raw`)      AS cliente,
    p.`operational_status`                   AS stato,
    p.`start_date`, p.`end_date`,
    COALESCE(p.`value_total`, 0)             AS valore_commessa,
    COALESCE(c.`ore`, 0)                     AS ore_consuntivate,
    COALESCE(c.`interventi`, 0)              AS interventi,
    COALESCE(c.`costo`, 0)                   AS costo_consuntivato,
    -- margine assoluto: ha senso solo dove c'e' un ricavo
    CASE WHEN COALESCE(m.`has_revenue`, 1) = 0 THEN NULL
         ELSE ROUND(COALESCE(p.`value_total`,0) - COALESCE(c.`costo`,0), 2) END AS margine,
    CASE WHEN COALESCE(m.`has_revenue`, 1) = 0 OR COALESCE(p.`value_total`,0) = 0 THEN NULL
         ELSE ROUND(100 * (COALESCE(p.`value_total`,0) - COALESCE(c.`costo`,0))
                    / p.`value_total`, 1) END                                   AS margine_pct,
    CASE WHEN COALESCE(p.`value_total`,0) = 0 THEN NULL
         ELSE ROUND(100 * COALESCE(c.`costo`,0) / p.`value_total`, 1) END       AS consumo_valore_pct,
    CASE WHEN COALESCE(c.`ore`,0) = 0 THEN NULL
         ELSE ROUND(COALESCE(c.`costo`,0) / c.`ore`, 2) END                     AS costo_medio_orario,
    CASE
        WHEN COALESCE(m.`has_revenue`, 1) = 0                             THEN 'attivita interna'
        WHEN COALESCE(p.`value_total`, 0) = 0                             THEN 'valore non impostato'
        WHEN COALESCE(m.`budget_overrun`,0) = 1
             AND COALESCE(c.`costo`,0) > p.`value_total`                  THEN 'SFORATA'
        WHEN COALESCE(m.`budget_overrun`,0) = 1
             AND COALESCE(c.`costo`,0) > p.`value_total` * 0.85           THEN 'prossima al limite'
        WHEN COALESCE(c.`costo`,0) > p.`value_total`                      THEN 'costo oltre il valore'
        ELSE 'nei limiti'
    END                                                                         AS allerta
FROM `cm_projects` p
LEFT JOIN `cm_contract_models` m ON m.`service_line` = p.`service_line`
LEFT JOIN `clients`            cl ON cl.`id` = p.`client_id`
LEFT JOIN (
    SELECT `project_id`,
           COUNT(*)                                   AS interventi,
           ROUND(SUM(COALESCE(`quantity_hours`,0)),2) AS ore,
           ROUND(SUM(COALESCE(`company_cost_import`,0)),2) AS costo
      FROM `cm_intervention_reports`
     WHERE `project_id` IS NOT NULL
     GROUP BY `project_id`
) c ON c.`project_id` = p.`id`;

-- -----------------------------------------------------------------------------
-- 4. Costo delle attivita' interne.
--    Sono l'unico gruppo per cui la domanda non e' "quanto rende" ma "quanto
--    pesa": e' costo di struttura, e va misurato come tale.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_costo_interno` AS
SELECT
    p.`service_line`                            AS linea,
    m.`label`                                   AS descrizione,
    DATE_FORMAT(r.`report_date`, '%Y-%m')       AS anno_mese,
    COUNT(*)                                    AS interventi,
    ROUND(SUM(COALESCE(r.`quantity_hours`,0)),2) AS ore,
    ROUND(SUM(COALESCE(r.`company_cost_import`,0)),2) AS costo,
    COUNT(DISTINCT r.`technician_raw`)          AS tecnici
FROM `cm_intervention_reports` r
JOIN `cm_projects`        p ON p.`id` = r.`project_id`
JOIN `cm_contract_models` m ON m.`service_line` = p.`service_line` AND m.`has_revenue` = 0
GROUP BY p.`service_line`, m.`label`, DATE_FORMAT(r.`report_date`, '%Y-%m');

-- -----------------------------------------------------------------------------
-- 5. Quadro per modello contrattuale
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_quadro_modelli` AS
SELECT
    `modello`,
    -- si aggrega per MODELLO e non per etichetta: le nove linee interne hanno
    -- nove etichette diverse e comparivano come nove righe, rendendo illeggibile
    -- proprio il totale che interessa, cioe' quanto pesa l'attivita interna
    GROUP_CONCAT(DISTINCT `linea_servizio` ORDER BY `linea_servizio` SEPARATOR ', ') AS linee,
    MAX(`ha_ricavo`) AS `ha_ricavo`,
    COUNT(*)                                        AS commesse,
    SUM(`interventi`)                               AS interventi,
    ROUND(SUM(`ore_consuntivate`), 2)               AS ore,
    ROUND(SUM(`valore_commessa`), 2)                AS valore,
    ROUND(SUM(`costo_consuntivato`), 2)             AS costo,
    ROUND(SUM(COALESCE(`margine`, 0)), 2)           AS margine,
    ROUND(100 * SUM(COALESCE(`margine`,0))
          / NULLIF(SUM(`valore_commessa`), 0), 1)   AS margine_pct,
    SUM(CASE WHEN `allerta` = 'SFORATA' THEN 1 ELSE 0 END)             AS sforate,
    SUM(CASE WHEN `allerta` = 'prossima al limite' THEN 1 ELSE 0 END)  AS prossime_al_limite
FROM `v_cm_redditivita_commessa`
GROUP BY `modello`;

