-- ════════════════════════════════════════════════════════════════
-- v1.8.59 — Contratti di sola disponibilita': interventi mal imputati
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Attributo di modello: il contratto ammette moduli di intervento?
--
--    In tabella e non cablato su WTS-REP: se domani un altro tipo di canone
--    seguisse la stessa regola, si imposta il flag senza una release.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_contract_models`
    ADD COLUMN IF NOT EXISTS `allows_reports` tinyint(1) NOT NULL DEFAULT 1
        COMMENT '0 = non deve ricevere moduli di intervento: vanno sul contratto operativo collegato',
    ADD COLUMN IF NOT EXISTS `operative_lines` varchar(200) DEFAULT NULL
        COMMENT 'Linee su cui vanno imputati gli interventi, separate da virgola';

UPDATE `cm_contract_models`
   SET `allows_reports` = 0,
       `operative_lines` = 'WTS-CC,WTS-CSS',
       `notes` = CONCAT(COALESCE(`notes`,''),
                 ' Canone di disponibilita: gli interventi vanno imputati al contratto WTS-CC o WTS-CSS collegato.')
 WHERE `service_line` = 'WTS-REP' AND `allows_reports` <> 0;

-- -----------------------------------------------------------------------------
-- 2. Segnalazione degli interventi mal imputati, con la commessa suggerita.
--
--    Il suggerimento e' costruito cercando fra le commesse dello STESSO CLIENTE
--    con linea operativa ammessa, attive alla data dell'intervento. La
--    contiguita' dei codici — sui dati, WTS_3092 (REP) e WTS_3093 (CC) sono
--    consecutivi — non e' usata come criterio: e' una coincidenza di
--    numerazione, non una relazione dichiarata, e fondarci un suggerimento
--    automatico sarebbe fragile.
--
--    `commesse_candidate` dice quante alternative esistono: con una sola il
--    suggerimento e' quasi certo, con molte serve una scelta umana.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_anomalia_imputazione` AS
SELECT
    r.`id`                                   AS report_id,
    r.`report_code`                          AS codice_rapporto,
    r.`report_date`                          AS data_rapporto,
    r.`technician_raw`                       AS tecnico,
    COALESCE(r.`quantity_hours`, 0)          AS ore,
    p.`project_code`                         AS commessa_errata,
    p.`service_line`                         AS linea_errata,
    m.`label`                                AS modello_errato,
    COALESCE(cl.`name`, r.`client_raw`)      AS cliente,
    r.`client_id`,
    m.`operative_lines`                      AS linee_ammesse,
    (SELECT COUNT(*) FROM `cm_projects` q
      WHERE q.`client_id` = p.`client_id`
        AND FIND_IN_SET(q.`service_line`, m.`operative_lines`)
        AND (q.`start_date` IS NULL OR q.`start_date` <= r.`report_date`)
        AND (q.`end_date`   IS NULL OR q.`end_date`   >= r.`report_date`)
    )                                        AS commesse_candidate,
    (SELECT q.`project_code` FROM `cm_projects` q
      WHERE q.`client_id` = p.`client_id`
        AND FIND_IN_SET(q.`service_line`, m.`operative_lines`)
        AND (q.`start_date` IS NULL OR q.`start_date` <= r.`report_date`)
        AND (q.`end_date`   IS NULL OR q.`end_date`   >= r.`report_date`)
      ORDER BY CASE WHEN q.`operational_status` = 'Aperta' THEN 0 ELSE 1 END,
               q.`start_date` DESC
      LIMIT 1)                               AS commessa_suggerita,
    CONCAT('Modulo di intervento su contratto ', p.`service_line`,
           ', che remunera la disponibilita e non l''intervento. ',
           'Va spostato sulla commessa ', m.`operative_lines`, ' collegata.') AS rilievo
FROM `cm_intervention_reports` r
JOIN `cm_projects`        p  ON p.`id` = r.`project_id`
JOIN `cm_contract_models` m  ON m.`service_line` = p.`service_line`
                            AND m.`allows_reports` = 0
LEFT JOIN `clients`       cl ON cl.`id` = r.`client_id`;

-- -----------------------------------------------------------------------------
-- 3. Riepilogo, per la scheda delle anomalie
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_anomalia_imputazione_riepilogo` AS
SELECT
    `linea_errata`,
    COUNT(*)                                                   AS segnalazioni,
    COUNT(DISTINCT `commessa_errata`)                          AS commesse_coinvolte,
    COUNT(DISTINCT `tecnico`)                                  AS tecnici,
    ROUND(SUM(`ore`), 2)                                       AS ore,
    SUM(CASE WHEN `commessa_suggerita` IS NOT NULL THEN 1 ELSE 0 END) AS con_suggerimento,
    SUM(CASE WHEN `commesse_candidate` = 1 THEN 1 ELSE 0 END)  AS suggerimento_univoco,
    MIN(`data_rapporto`)                                       AS dal,
    MAX(`data_rapporto`)                                       AS al
FROM `v_cm_anomalia_imputazione`
GROUP BY `linea_errata`;

-- -----------------------------------------------------------------------------
-- 4. Le commesse che non ammettono interventi escono dalle statistiche di
--    effort, dove comparirebbero come commesse a zero ore falsando le medie.
--    Il loro valore resta invece nei totali di ricavo, perche' il canone e'
--    incassato davvero.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_redditivita_operativa` AS
SELECT c.*
FROM `v_cm_redditivita_commessa` c
LEFT JOIN `cm_contract_models` m ON m.`service_line` = c.`linea_servizio`
WHERE COALESCE(m.`allows_reports`, 1) = 1;

