-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`) VALUES
    ('cost_workable_hours_year', '1760', 'Ore lavorabili annue per convertire il full cost annuo in orario (8 h x 220 gg)'),
    ('cost_workable_days_year',  '220',  'Giorni lavorabili annui al netto di ferie e festivita')
