-- -----------------------------------------------------------------------------
-- 2. Base di costo sul modello contrattuale
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_contract_models`
    ADD COLUMN IF NOT EXISTS `cost_basis` varchar(30) DEFAULT 'fascia'
        COMMENT 'direzionale, full_cost, fascia_o_direzionale, fascia',
    ADD COLUMN IF NOT EXISTS `cost_note` varchar(255) DEFAULT NULL;

UPDATE `cm_contract_models` SET `cost_basis` = 'direzionale',
       `cost_note` = 'Costo aziendale dato dal costo direzionale.'
 WHERE `service_line` IN ('WTS-GES','WTS-SOC');

UPDATE `cm_contract_models` SET `cost_basis` = 'full_cost',
       `cost_note` = 'Costo aziendale dato dal full cost dell operatore.'
 WHERE `service_line` IN ('NV_AI','NV_DT','NV_EVENTI','NV_FI','NV_GC','NV_GS','NV_TI',
                          'WTS-AM','WTS-HD','WTS-PRES');

UPDATE `cm_contract_models` SET `cost_basis` = 'fascia_o_direzionale',
       `cost_note` = 'Costo aziendale da fascia di costo interna oppure costo direzionale.'
 WHERE `service_line` IN ('NV_SC','WTS-ACM','WTS-CC','WTS-CSS','WTS-MEG',
                          'WTS-MON','WTS-REP','WTS-SD');

-- Le due linee non classificate nella v1.8.58 compaiono in questo elenco: si
