-- ancora da definire. Le due informazioni sono indipendenti.
INSERT IGNORE INTO `cm_contract_models`
    (`service_line`,`model`,`label`,`has_revenue`,`revenue_basis`,`cost_basis`,`cost_note`,`sort_order`) VALUES
    ('WTS-SOC','da_classificare','Security Operations Center',1,NULL,'direzionale',
     'Costo direzionale. Modello contrattuale ancora da definire.',80),
    ('WTS-AM', 'da_classificare','WTS-AM',1,NULL,'full_cost',
     'Full cost dell operatore. Modello contrattuale ancora da definire.',81);

-- -----------------------------------------------------------------------------
-- 3. Full cost per operatore.
--    Tabella dedicata e non colonna su cm_professionals: il full cost e' un
--    dato economico con una sua validita' temporale, e tenerlo separato
--    permettera' di storicizzarlo senza toccare l'anagrafica.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_operator_costs` (
    `id`             int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`      int(11)       DEFAULT NULL COMMENT 'dgb_operator.id',
    `operator_name`  varchar(150)  DEFAULT NULL,
    `full_cost_year` decimal(12,2) DEFAULT NULL COMMENT 'Costo annuo pieno',
    `full_cost_hour` decimal(12,4) DEFAULT NULL COMMENT 'Derivato: annuo / ore lavorabili',
    `directional_cost_hour` decimal(12,4) DEFAULT NULL COMMENT 'Costo direzionale orario, se fornito',
    `valid_from`     date          DEFAULT NULL,
    `is_active`      tinyint(1)    NOT NULL DEFAULT 1,
    `created_at`     datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`     datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_opcost_source` (`source_id`),
    KEY `idx_opcost_name` (`operator_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 4. Costo della prestazione secondo la base prevista dalla linea.
--
--    L'ordine di precedenza e' sempre: costo RILEVATO se presente, poi la base
--    prevista dal modello, poi il ripiego. Un costo gia' consuntivato dal
--    gestionale non viene mai sostituito da una stima.
--
--    `costo_origine` dichiara quale base e' stata effettivamente usata, che con
--    tre basi possibili e un dato mancante e' l'informazione senza la quale i
--    numeri non sono interpretabili.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_costo_prestazione` AS
SELECT
    r.`id`                                    AS fact_id,
    r.`report_code`                           AS codice_rapporto,
    r.`report_date`                           AS data_rapporto,
    DATE_FORMAT(r.`report_date`, '%Y-%m')     AS anno_mese,
    p.`project_code`                          AS commessa,
    p.`service_line`                          AS linea_servizio,
    COALESCE(m.`model`, 'da_classificare')    AS modello,
    COALESCE(m.`cost_basis`, 'fascia')        AS base_costo_prevista,
    r.`technician_raw`                        AS tecnico,
    r.`band_raw`                              AS fascia,
    COALESCE(r.`quantity_hours`, 0)           AS ore,
    bc.`hourly_cost`                          AS costo_fascia_ora,
    oc.`full_cost_hour`                       AS full_cost_ora,
    oc.`directional_cost_hour`                AS costo_direzionale_ora,

    CASE
        WHEN COALESCE(r.`company_cost_import`, 0) <> 0 THEN r.`company_cost_import`
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'full_cost' AND oc.`full_cost_hour` IS NOT NULL
             THEN ROUND(COALESCE(r.`quantity_hours`,0) * oc.`full_cost_hour`, 2)
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'direzionale' AND oc.`directional_cost_hour` IS NOT NULL
             THEN ROUND(COALESCE(r.`quantity_hours`,0) * oc.`directional_cost_hour`, 2)
        WHEN bc.`hourly_cost` IS NOT NULL
             THEN ROUND(COALESCE(r.`quantity_hours`,0) * bc.`hourly_cost`, 2)
        ELSE NULL
    END                                                                    AS costo,

    CASE
        WHEN COALESCE(r.`company_cost_import`, 0) <> 0 THEN 'rilevato'
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'full_cost' AND oc.`full_cost_hour` IS NOT NULL
             THEN 'full cost operatore'
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'direzionale' AND oc.`directional_cost_hour` IS NOT NULL
             THEN 'costo direzionale'
        -- Il ripiego si dichiara solo se c'e' davvero su cosa ripiegare: dire
        -- "ripiego su fascia" quando anche la fascia manca produrrebbe un costo
        -- nullo con un'etichetta che ne suggerisce uno stimato, cioe' la
        -- diagnosi peggiore possibile.
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'direzionale' AND bc.`hourly_cost` IS NOT NULL
             THEN 'ripiego su fascia: costo direzionale non disponibile'
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'full_cost' AND bc.`hourly_cost` IS NOT NULL
             THEN 'ripiego su fascia: full cost operatore non disponibile'
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'direzionale'
             THEN 'SCOPERTO: ne costo direzionale ne fascia'
        WHEN COALESCE(m.`cost_basis`,'fascia') = 'full_cost'
             THEN 'SCOPERTO: ne full cost ne fascia'
        WHEN bc.`hourly_cost` IS NOT NULL THEN 'fascia interna'
        ELSE 'SCOPERTO: nessuna base di costo'
    END                                                                    AS costo_origine
FROM `cm_intervention_reports` r
LEFT JOIN `cm_projects`         p  ON p.`id` = r.`project_id`
LEFT JOIN `cm_contract_models`  m  ON m.`service_line` = p.`service_line`
LEFT JOIN `cm_band_costs`       bc ON bc.`band_name` = r.`band_raw`
LEFT JOIN `cm_operator_costs`   oc ON oc.`operator_name` = r.`technician_raw` AND oc.`is_active` = 1;

-- -----------------------------------------------------------------------------
-- 5. Copertura delle basi di costo: quanto del consuntivo e' valorizzato con la
--    base corretta e quanto ricade sul ripiego. E' la misura che dice se i
--    margini per linea sono utilizzabili.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_copertura_costi` AS
SELECT
    `linea_servizio`,
    `base_costo_prevista`,
    `costo_origine`,
    COUNT(*)                        AS prestazioni,
    ROUND(SUM(`ore`), 2)            AS ore,
    ROUND(SUM(COALESCE(`costo`,0)), 2) AS costo
FROM `v_cm_costo_prestazione`
GROUP BY `linea_servizio`, `base_costo_prevista`, `costo_origine`;

