-- ════════════════════════════════════════════════════════════════
-- v1.8.61 — Operazioni economiche di commessa e saldo completo
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Tipi di operazione
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_operation_types` (
    `id`          int(11)      NOT NULL AUTO_INCREMENT,
    `source_id`   int(11)      DEFAULT NULL,
    `code`        varchar(20)  NOT NULL,
    `name`        varchar(255) DEFAULT NULL,
    `type_group`  varchar(10)  DEFAULT NULL COMMENT 'REC alimenta, FVC addebita, REP rettifica, INV promemoria',
    `sign`        tinyint(4)   NOT NULL DEFAULT 0 COMMENT '+1 alimenta, -1 addebita, 0 neutro',
    `amount_field` varchar(20) DEFAULT NULL COMMENT 'campo che porta l importo: revenue, cost, final_value',
    `sort_order`  int(11)      NOT NULL DEFAULT 0,
    `is_active`   tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`  datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`  datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_optype_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `cm_operation_types`
    (`source_id`,`code`,`name`,`type_group`,`sign`,`amount_field`,`sort_order`) VALUES
    (1,'COV',    'Riporto da contratto precedente',          'REC',  1, 'revenue',     10),
    (2,'COR',    'Ordine cliente',                           'REC',  1, 'revenue',     20),
    (3,'REP',    'Storno',                                   'REP',  1, 'final_value', 30),
    (4,'FVCCD',  'Consuntivo / Costo Direzione Commerciale', 'FVC', -1, 'cost',        40),
    (5,'FVCBGS', 'Consuntivo / Costo Acquisto Beni e Servizi','FVC', -1, 'cost',       50),
    (6,'INVMEMO','Promemoria di fatturazione',               'INV',  0, NULL,          60)
ON DUPLICATE KEY UPDATE
    `name` = VALUES(`name`), `type_group` = VALUES(`type_group`),
    `sign` = VALUES(`sign`), `amount_field` = VALUES(`amount_field`);

-- -----------------------------------------------------------------------------
-- 2. Operazioni di commessa.
--    `amount` e' l'importo GIA' normalizzato: il campo di origine dipende dal
--    tipo, e risolverlo in fase di import evita che ogni query debba conoscere
--    la semantica dei tre campi. `signed_amount` porta il segno.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_project_operations` (
    `id`             int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`      int(11)       DEFAULT NULL,
    `project_id`     int(11)       DEFAULT NULL,
    `project_code`   varchar(50)   DEFAULT NULL,
    `op_code`        varchar(20)   DEFAULT NULL,
    `op_type_code`   varchar(20)   DEFAULT NULL,
    `op_name`        varchar(255)  DEFAULT NULL,
    `op_date`        date          DEFAULT NULL,
    `description`    text          DEFAULT NULL,
    `order_code`     varchar(255)  DEFAULT NULL,
    `cost`           decimal(12,2) DEFAULT NULL,
    `revenue`        decimal(12,2) DEFAULT NULL,
    `final_value`    decimal(12,2) DEFAULT NULL,
    `invoice_amount` decimal(12,2) DEFAULT NULL,
    `is_invoiced`    tinyint(1)    NOT NULL DEFAULT 0,
    `amount`         decimal(12,2) DEFAULT NULL COMMENT 'Importo normalizzato secondo il tipo',
    `signed_amount`  decimal(12,2) DEFAULT NULL COMMENT 'Importo con segno: + alimenta, - addebita',
    `operator_id`    int(11)       DEFAULT NULL,
    `import_batch_id` int(11)      DEFAULT NULL,
    `created_at`     datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`     datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_projop_source` (`source_id`),
    KEY `idx_projop_project` (`project_id`),
    KEY `idx_projop_code`    (`project_code`),
    KEY `idx_projop_type`    (`op_type_code`),
    KEY `idx_projop_date`    (`op_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. Saldo economico della commessa.
--
--    E' il quadro che finora mancava: quanto la commessa e' stata alimentata,
--    quanto le e' stato addebitato, e quanto resta.
--
--    Il consuntivo delle ore e' tenuto SEPARATO dagli addebiti: sono due
--    grandezze di natura diversa — uno e' costo del lavoro svolto, l'altro sono
--    acquisti e costi direzionali imputati — e sommarle in un unico totale
--    renderebbe impossibile capire quale delle due erode il margine.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_saldo_commessa` AS
SELECT
    p.`id`                                   AS commessa_id,
    p.`project_code`                         AS commessa,
    p.`name`                                 AS denominazione,
    p.`service_line`                         AS linea_servizio,
    COALESCE(m.`model`, 'da_classificare')   AS modello,
    COALESCE(cl.`name`, p.`client_raw`)      AS cliente,
    p.`operational_status`                   AS stato,
    COALESCE(p.`value_total`, 0)             AS valore_commessa,

    -- alimentazioni
    COALESCE(o.`ordini_cliente`, 0)          AS ordini_cliente,
    COALESCE(o.`riporti`, 0)                 AS riporto_precedente,
    COALESCE(o.`storni`, 0)                  AS storni,
    COALESCE(o.`ordini_cliente`,0) + COALESCE(o.`riporti`,0) + COALESCE(o.`storni`,0) AS totale_alimentazioni,

    -- addebiti
    COALESCE(o.`costo_direzionale`, 0)       AS costo_direzionale,
    COALESCE(o.`acquisto_beni_servizi`, 0)   AS acquisto_beni_servizi,
    COALESCE(o.`costo_direzionale`,0) + COALESCE(o.`acquisto_beni_servizi`,0) AS totale_addebiti,

    -- consuntivo del lavoro, tenuto distinto
    COALESCE(r.`ore`, 0)                     AS ore_consuntivate,
    COALESCE(r.`costo_ore`, 0)               AS costo_ore,

    -- saldi
    ROUND(COALESCE(o.`ordini_cliente`,0) + COALESCE(o.`riporti`,0) + COALESCE(o.`storni`,0)
        - COALESCE(o.`costo_direzionale`,0) - COALESCE(o.`acquisto_beni_servizi`,0), 2) AS saldo_operazioni,
    ROUND(COALESCE(o.`ordini_cliente`,0) + COALESCE(o.`riporti`,0) + COALESCE(o.`storni`,0)
        - COALESCE(o.`costo_direzionale`,0) - COALESCE(o.`acquisto_beni_servizi`,0)
        - COALESCE(r.`costo_ore`,0), 2)                                                 AS saldo_finale,
    COALESCE(o.`operazioni`, 0)              AS n_operazioni,
    COALESCE(o.`fatturato`, 0)               AS importo_fatturato
FROM `cm_projects` p
LEFT JOIN `cm_contract_models` m  ON m.`service_line` = p.`service_line`
LEFT JOIN `clients`            cl ON cl.`id` = p.`client_id`
LEFT JOIN (
    SELECT `project_id`,
           COUNT(*)                                                                 AS operazioni,
           ROUND(SUM(CASE WHEN `op_type_code` = 'COR'    THEN COALESCE(`amount`,0) ELSE 0 END), 2) AS ordini_cliente,
           ROUND(SUM(CASE WHEN `op_type_code` = 'COV'    THEN COALESCE(`amount`,0) ELSE 0 END), 2) AS riporti,
           ROUND(SUM(CASE WHEN `op_type_code` = 'REP'    THEN COALESCE(`amount`,0) ELSE 0 END), 2) AS storni,
           ROUND(SUM(CASE WHEN `op_type_code` = 'FVCCD'  THEN COALESCE(`amount`,0) ELSE 0 END), 2) AS costo_direzionale,
           ROUND(SUM(CASE WHEN `op_type_code` = 'FVCBGS' THEN COALESCE(`amount`,0) ELSE 0 END), 2) AS acquisto_beni_servizi,
           ROUND(SUM(COALESCE(`invoice_amount`,0)), 2)                              AS fatturato
      FROM `cm_project_operations`
     WHERE `project_id` IS NOT NULL
     GROUP BY `project_id`
) o ON o.`project_id` = p.`id`
LEFT JOIN (
    SELECT `project_id`,
           ROUND(SUM(COALESCE(`quantity_hours`,0)), 2)      AS ore,
           ROUND(SUM(COALESCE(`company_cost_import`,0)), 2) AS costo_ore
      FROM `cm_intervention_reports`
     WHERE `project_id` IS NOT NULL
     GROUP BY `project_id`
) r ON r.`project_id` = p.`id`;

-- -----------------------------------------------------------------------------
-- 4. Quadro delle operazioni per tipo
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_operazioni_quadro` AS
SELECT
    t.`code`, t.`name`, t.`type_group`, t.`sign`,
    COUNT(o.`id`)                                    AS operazioni,
    COUNT(DISTINCT o.`project_id`)                   AS commesse,
    ROUND(SUM(COALESCE(o.`amount`, 0)), 2)           AS importo,
    ROUND(SUM(COALESCE(o.`signed_amount`, 0)), 2)    AS importo_con_segno,
    SUM(CASE WHEN COALESCE(o.`amount`,0) < 0 THEN 1 ELSE 0 END) AS con_importo_negativo,
    MIN(o.`op_date`)                                 AS dal,
    MAX(o.`op_date`)                                 AS al
FROM `cm_operation_types` t
LEFT JOIN `cm_project_operations` o ON o.`op_type_code` = t.`code`
GROUP BY t.`code`, t.`name`, t.`type_group`, t.`sign`, t.`sort_order`
ORDER BY t.`sort_order`;

