-- ════════════════════════════════════════════════════════════════
-- v1.8.63 — Divisioni, anomalie del gestionale, dismissione vecchio import
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- Divisioni aziendali
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_divisions` (
    `id`        int(11)      NOT NULL AUTO_INCREMENT,
    `source_id` int(11)      DEFAULT NULL,
    `code`      varchar(60)  NOT NULL,
    `name`      varchar(150) DEFAULT NULL,
    `is_active` tinyint(1)   NOT NULL DEFAULT 1,
    `created_at` datetime    NOT NULL DEFAULT current_timestamp(),
    `updated_at` datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_div_source` (`source_id`),
    KEY `idx_div_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Tipi di anomalia contrattuale
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_anomaly_types` (
    `id`          int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`   int(11)       DEFAULT NULL,
    `code`        varchar(40)   NOT NULL,
    `family`      varchar(20)   DEFAULT NULL COMMENT 'MUT margine, RUT residuo, RNS tariffa, INV fatturazione',
    `threshold`   decimal(12,2) DEFAULT NULL,
    `severity`    varchar(20)   DEFAULT NULL COMMENT 'BLOCK bloccante, ALARM da verificare',
    `description` varchar(500)  DEFAULT NULL,
    `check_order` int(11)       NOT NULL DEFAULT 0,
    `created_at`  datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`  datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_anomtype_source` (`source_id`),
    KEY `idx_anomtype_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Anomalie rilevate sulle commesse
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_contract_anomalies` (
    `id`           int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`    int(11)       DEFAULT NULL,
    `project_id`   int(11)       DEFAULT NULL,
    `project_code` varchar(50)   DEFAULT NULL,
    `anomaly_code` varchar(40)   DEFAULT NULL,
    `family`       varchar(20)   DEFAULT NULL,
    `threshold`    decimal(12,2) DEFAULT NULL,
    `severity`     varchar(20)   DEFAULT NULL,
    `description`  varchar(500)  DEFAULT NULL,
    `status`       varchar(30)   DEFAULT NULL,
    `detected_at`  date          DEFAULT NULL,
    `resolved_at`  date          DEFAULT NULL,
    `import_batch_id` int(11)    DEFAULT NULL,
    `created_at`   datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`   datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_anom_source` (`source_id`),
    KEY `idx_anom_project`  (`project_id`),
    KEY `idx_anom_code`     (`project_code`),
    KEY `idx_anom_severity` (`severity`),
    KEY `idx_anom_family`   (`family`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Quadro delle anomalie del gestionale.
--    `aperta` distingue le segnalazioni ancora attive da quelle risolte: senza,
--    un conteggio storico verrebbe scambiato per una situazione corrente.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_anomalie_gestionale` AS
SELECT
    a.`anomaly_code`                         AS codice,
    a.`family`                               AS famiglia,
    CASE a.`family`
        WHEN 'MUT' THEN 'Margine sotto soglia'
        WHEN 'RUT' THEN 'Residuo in esaurimento'
        WHEN 'RNS' THEN 'Tariffa fuori standard'
        WHEN 'INV' THEN 'Fatturazione in ritardo'
        ELSE a.`family` END                  AS famiglia_descrizione,
    a.`severity`                             AS gravita,
    a.`threshold`                            AS soglia,
    COUNT(*)                                 AS segnalazioni,
    COUNT(DISTINCT a.`project_code`)         AS commesse,
    SUM(CASE WHEN a.`resolved_at` IS NULL THEN 1 ELSE 0 END) AS aperte,
    MIN(a.`detected_at`)                     AS dal,
    MAX(a.`detected_at`)                     AS al
FROM `cm_contract_anomalies` a
GROUP BY a.`anomaly_code`, a.`family`, a.`severity`, a.`threshold`;

-- -----------------------------------------------------------------------------
-- Commesse con anomalie, confrontate con le allerte calcolate dal portale.
--    Il confronto e' il punto: due sistemi indipendenti che segnalano la stessa
--    commessa danno molta piu' confidenza di uno solo, e una commessa segnalata
--    da uno e non dall'altro merita di essere capita.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_commesse_allerta` AS
SELECT
    p.`project_code`                          AS commessa,
    p.`name`                                  AS denominazione,
    p.`service_line`                          AS linea_servizio,
    COALESCE(cl.`name`, p.`client_raw`)       AS cliente,
    COALESCE(a.`bloccanti`, 0)                AS anomalie_bloccanti,
    COALESCE(a.`allarmi`, 0)                  AS anomalie_allarme,
    COALESCE(a.`aperte`, 0)                   AS anomalie_aperte,
    a.`famiglie`                              AS famiglie_anomalia,
    r.`allerta`                               AS allerta_portale,
    r.`consumo_valore_pct`                    AS consumo_valore_pct,
    -- il saldo viene da v_cm_saldo_commessa (v1.8.61), che e' la vista del
    -- mastrino: v_cm_redditivita_commessa non lo espone
    sa.`saldo_finale`                         AS saldo_finale,
    CASE
        WHEN COALESCE(a.`bloccanti`,0) > 0 AND r.`allerta` IN ('SFORATA','prossima al limite')
             THEN 'confermata da entrambi'
        WHEN COALESCE(a.`bloccanti`,0) > 0 THEN 'solo gestionale'
        WHEN r.`allerta` IN ('SFORATA','prossima al limite') THEN 'solo portale'
        ELSE 'nessuna allerta'
    END                                       AS convergenza
FROM `cm_projects` p
LEFT JOIN `clients` cl ON cl.`id` = p.`client_id`
LEFT JOIN (
    SELECT `project_code`,
           SUM(CASE WHEN `severity` = 'BLOCK' THEN 1 ELSE 0 END) AS bloccanti,
           SUM(CASE WHEN `severity` = 'ALARM' THEN 1 ELSE 0 END) AS allarmi,
           SUM(CASE WHEN `resolved_at` IS NULL THEN 1 ELSE 0 END) AS aperte,
           GROUP_CONCAT(DISTINCT `family` ORDER BY `family` SEPARATOR ', ') AS famiglie
      FROM `cm_contract_anomalies`
     GROUP BY `project_code`
) a ON a.`project_code` = p.`project_code`
LEFT JOIN `v_cm_redditivita_commessa` r  ON r.`commessa` = p.`project_code`
LEFT JOIN `v_cm_saldo_commessa`       sa ON sa.`commessa` = p.`project_code`
WHERE COALESCE(a.`bloccanti`,0) > 0
   OR COALESCE(a.`allarmi`,0) > 0
   OR r.`allerta` IN ('SFORATA','prossima al limite');

