-- ════════════════════════════════════════════════════════════════
-- v1.8.64 — Colonna import_batch_id mancante e controllo di schema
-- ════════════════════════════════════════════════════════════════
-- =============================================================================


-- -----------------------------------------------------------------------------
-- Colonna di tracciamento del batch su tutte le destinazioni dei dataset.
--
-- `ADD COLUMN IF NOT EXISTS` su tutte e nove, comprese le quattro che gia' la
-- hanno: l'alternativa sarebbe elencare solo le mancanti, ma un elenco
-- selettivo va aggiornato a mano ogni volta che nasce una tabella, ed e'
-- esattamente il modo in cui questo difetto si e' prodotto.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_divisions`           ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_anomaly_types`       ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_operator_costs`      ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_band_costs`          ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_operation_types`     ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_contract_rates`      ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_project_allocations` ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_project_operations`  ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `cm_contract_anomalies`  ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;

-- Indice sul batch: serve a ritrovare cosa ha scritto una singola esecuzione,
-- che e' la prima cosa che si cerca quando una sincronizzazione va storta.
ALTER TABLE `cm_divisions`           ADD INDEX IF NOT EXISTS `idx_div_batch`      (`import_batch_id`);
ALTER TABLE `cm_anomaly_types`       ADD INDEX IF NOT EXISTS `idx_anomtype_batch` (`import_batch_id`);
ALTER TABLE `cm_operator_costs`      ADD INDEX IF NOT EXISTS `idx_opcost_batch`   (`import_batch_id`);
ALTER TABLE `cm_band_costs`          ADD INDEX IF NOT EXISTS `idx_bandcost_batch` (`import_batch_id`);
ALTER TABLE `cm_operation_types`     ADD INDEX IF NOT EXISTS `idx_optype_batch`   (`import_batch_id`);

-- -----------------------------------------------------------------------------
-- Controllo permanente: elenca le destinazioni dei dataset prive della colonna.
-- Deve restituire zero righe. Se ne restituisce, una nuova tabella e' stata
-- introdotta senza allinearla e la sincronizzazione fallira' su quel dataset.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sync_schema_check` AS
SELECT t.`TABLE_NAME` AS tabella,
       'manca import_batch_id' AS problema
FROM `information_schema`.`TABLES` t
WHERE t.`TABLE_SCHEMA` = DATABASE()
  AND t.`TABLE_TYPE` = 'BASE TABLE'
  AND t.`TABLE_NAME` IN ('cm_projects','cm_intervention_reports','cm_professionals',
                         'cm_contract_rates','cm_project_allocations','cm_band_costs',
                         'cm_operator_costs','cm_project_operations','cm_operation_types',
                         'cm_divisions','cm_anomaly_types','cm_contract_anomalies')
  AND NOT EXISTS (
      SELECT 1 FROM `information_schema`.`COLUMNS` c
       WHERE c.`TABLE_SCHEMA` = t.`TABLE_SCHEMA`
         AND c.`TABLE_NAME` = t.`TABLE_NAME`
         AND c.`COLUMN_NAME` = 'import_batch_id');

