-- ════════════════════════════════════════════════════════════════
-- v1.8.66 — Correzione del conflitto di collation nella deduplica
-- ════════════════════════════════════════════════════════════════
ALTER TABLE `cm_intervention_reports` CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 1. Recupero delle righe eventualmente rimaste senza grana
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports`
   SET `source_uid` = CONCAT(
           SUBSTRING_INDEX(`report_code`, '/', 1), '#',
           COALESCE(CAST(`technician_id` AS CHAR),
                    CAST(`technician_professional_id` AS CHAR),
                    NULLIF(TRIM(`technician_raw`), ''),
                    '0'))
 WHERE (`source_uid` IS NULL OR `source_uid` = '') AND `report_code` IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 2. Deduplica con tabella d'appoggio a collation EREDITATA.
--
--    CREATE TABLE ... AS SELECT prende tipo e collation dalla colonna sorgente:
--    nessuna collation viene dichiarata, quindi nessun conflitto e' possibile
--    su qualunque installazione.
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_ir_dupes66`;

CREATE TABLE `tmp_ir_dupes66` AS
SELECT MIN(`id`) AS `keep_id`, `source_uid`
  FROM `cm_intervention_reports`
 WHERE `source_uid` IS NOT NULL AND `source_uid` <> ''
 GROUP BY `source_uid`;

ALTER TABLE `tmp_ir_dupes66`
    ADD INDEX `idx_dupes66_uid`  (`source_uid`),
    ADD INDEX `idx_dupes66_keep` (`keep_id`);

DELETE r FROM `cm_intervention_reports` r
  JOIN `tmp_ir_dupes66` d ON d.`source_uid` = r.`source_uid`
 WHERE r.`id` <> d.`keep_id`;

DROP TABLE IF EXISTS `tmp_ir_dupes66`;

-- Residui delle esecuzioni fallite: le due tabelle precedenti possono essere
-- rimaste sul database, perche' la migration si interrompeva prima del DROP.
DROP TABLE IF EXISTS `tmp_ir_dupes`;
DROP TABLE IF EXISTS `tmp_ir_dupes51`;

-- -----------------------------------------------------------------------------
-- 3. Il vincolo di unicita' sulla grana, che le migration precedenti non
--    avevano potuto applicare perche' si interrompevano prima.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports`
    ADD UNIQUE KEY IF NOT EXISTS `uq_ir_source_uid` (`source_uid`);

-- -----------------------------------------------------------------------------
-- 4. Controllo permanente delle collation.
--
--    Elenca le colonne di collegamento la cui collation differisce da quella
--    di default del database. Non e' di per se' un errore, ma e' la condizione
--    che rende possibile il conflitto: sapere quali sono evita di scoprirlo
--    quando una migration si interrompe.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_collation_check` AS
SELECT c.`TABLE_NAME`   AS tabella,
       c.`COLUMN_NAME`  AS colonna,
       c.`COLLATION_NAME` AS collation_colonna,
       (SELECT s.`DEFAULT_COLLATION_NAME` FROM `information_schema`.`SCHEMATA` s
         WHERE s.`SCHEMA_NAME` = DATABASE()) AS collation_database
FROM `information_schema`.`COLUMNS` c
WHERE c.`TABLE_SCHEMA` = DATABASE()
  AND c.`COLLATION_NAME` IS NOT NULL
  AND c.`COLUMN_NAME` IN ('source_uid','report_code','project_code','band_raw',
                          'technician_raw','operator_name','service_line')
  AND c.`COLLATION_NAME` <> (SELECT s.`DEFAULT_COLLATION_NAME`
                               FROM `information_schema`.`SCHEMATA` s
                              WHERE s.`SCHEMA_NAME` = DATABASE());

