-- ════════════════════════════════════════════════════════════════
-- v1.8.69 — Assenze e matrice arricchita a quattro nature
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Impegni di calendario del personale
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_operator_commitments` (
    `id`              int(11)      NOT NULL AUTO_INCREMENT,
    `source_id`       int(11)      DEFAULT NULL,
    `commitment_type` varchar(30)  DEFAULT NULL COMMENT 'HOLIDAY, LEAVE, RECOVERY, SICK_LEAVE, ...',
    `operator_id`     int(11)      DEFAULT NULL,
    `operator_name`   varchar(150) DEFAULT NULL,
    `hours`           decimal(10,2) DEFAULT NULL COMMENT 'Durata in ORE, non giorni',
    `start_date`      date         DEFAULT NULL,
    `end_date`        date         DEFAULT NULL,
    `start_time`      varchar(10)  DEFAULT NULL,
    `end_time`        varchar(10)  DEFAULT NULL,
    `description`     varchar(500) DEFAULT NULL,
    `import_batch_id` int(11)      DEFAULT NULL,
    `created_at`      datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`      datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_commit_source` (`source_id`),
    KEY `idx_commit_type`  (`commitment_type`),
    KEY `idx_commit_op`    (`operator_id`),
    KEY `idx_commit_date`  (`start_date`),
    KEY `idx_commit_batch` (`import_batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. Classificazione dei tipi di impegno.
--
--    `is_absence` distingue le assenze vere dagli impegni di agenda: un
--    promemoria o una riunione occupano il calendario ma non sono ore non
--    lavorate, e sommarli alle ferie gonfierebbe l'assenteismo.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_commitment_types` (
    `code`        varchar(30)  NOT NULL,
    `label`       varchar(80)  NOT NULL,
    `is_absence`  tinyint(1)   NOT NULL DEFAULT 1,
    `color`       varchar(9)   DEFAULT NULL,
    `sort_order`  int(11)      NOT NULL DEFAULT 0,
    PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `cm_commitment_types` (`code`,`label`,`is_absence`,`color`,`sort_order`) VALUES
    ('HOLIDAY',      'Ferie',            1, '#8b5cf6', 10),
    ('LEAVE',        'Permesso',         1, '#a78bfa', 20),
    ('RECOVERY',     'Recupero ore',     1, '#c4b5fd', 30),
    ('SICK_LEAVE',   'Malattia',         1, '#7c3aed', 40),
    ('SAINT_PATRON', 'Patrono',          1, '#ddd6fe', 50),
    ('MEETING',      'Riunione',         0, '#64748b', 60),
    ('REMINDER',     'Promemoria',       0, '#94a3b8', 70)
ON DUPLICATE KEY UPDATE
    `label` = VALUES(`label`), `is_absence` = VALUES(`is_absence`), `color` = VALUES(`color`);

-- -----------------------------------------------------------------------------
-- 3. Assenze per giorno e operatore, pronte per la matrice.
--    Solo i tipi che sono davvero assenze.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_assenze_giorno` AS
SELECT
    c.`start_date`                       AS giorno,
    DATE_FORMAT(c.`start_date`, '%Y-%m') AS anno_mese,
    c.`commitment_type`                  AS tipo,
    t.`label`                            AS tipo_label,
    t.`color`                            AS colore,
    COUNT(*)                             AS impegni,
    COUNT(DISTINCT c.`operator_id`)      AS operatori,
    ROUND(SUM(COALESCE(c.`hours`, 0)), 2) AS ore
FROM `cm_operator_commitments` c
JOIN `cm_commitment_types` t ON t.`code` = c.`commitment_type` AND t.`is_absence` = 1
WHERE c.`start_date` IS NOT NULL
GROUP BY c.`start_date`, c.`commitment_type`, t.`label`, t.`color`;

-- -----------------------------------------------------------------------------
-- 4. Riepilogo delle assenze per operatore e mese
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_assenze_riepilogo` AS
SELECT
    DATE_FORMAT(c.`start_date`, '%Y-%m') AS anno_mese,
    c.`operator_name`                    AS operatore,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'HOLIDAY'    THEN c.`hours` ELSE 0 END), 2) AS ferie,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'LEAVE'      THEN c.`hours` ELSE 0 END), 2) AS permessi,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'RECOVERY'   THEN c.`hours` ELSE 0 END), 2) AS recuperi,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'SICK_LEAVE' THEN c.`hours` ELSE 0 END), 2) AS malattia,
    ROUND(SUM(CASE WHEN t.`is_absence` = 1 THEN c.`hours` ELSE 0 END), 2)                 AS totale_assenze
FROM `cm_operator_commitments` c
JOIN `cm_commitment_types` t ON t.`code` = c.`commitment_type`
WHERE c.`start_date` IS NOT NULL
GROUP BY anno_mese, c.`operator_name`;

