-- ════════════════════════════════════════════════════════════════
-- v1.8.70 — Rimozione dei residui del vecchio import DGB
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_cleanup_log` (
    `id`          int(11)      NOT NULL AUTO_INCREMENT,
    `run_at`      datetime     NOT NULL DEFAULT current_timestamp(),
    `scope`       varchar(60)  NOT NULL,
    `rows_before` int(11)      DEFAULT NULL,
    `rows_removed` int(11)     DEFAULT NULL,
    `hours_before` decimal(14,2) DEFAULT NULL,
    `hours_removed` decimal(14,2) DEFAULT NULL,
    `note`        varchar(400) DEFAULT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_cleanup_scope` (`scope`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `cm_cleanup_log` (`scope`, `rows_before`, `rows_removed`, `hours_before`, `hours_removed`, `note`)
SELECT
    'v1.8.70 residui DGB-',
    (SELECT COUNT(*) FROM `cm_intervention_reports`),
    (SELECT COUNT(*) FROM `cm_intervention_reports`
      WHERE `report_code` LIKE 'DGB-%' AND `dgb_activity_id` IS NULL),
    (SELECT ROUND(SUM(`quantity_hours`), 2) FROM `cm_intervention_reports`),
    (SELECT ROUND(SUM(`quantity_hours`), 2) FROM `cm_intervention_reports`
      WHERE `report_code` LIKE 'DGB-%' AND `dgb_activity_id` IS NULL),
    'Import DgbSync precedente alla v1.8.51: report_code inventato come DGB-<id>'
FROM DUAL
WHERE (SELECT COUNT(*) FROM `cm_intervention_reports`
        WHERE `report_code` LIKE 'DGB-%' AND `dgb_activity_id` IS NULL) > 0;

-- -----------------------------------------------------------------------------
-- 2. Eliminazione dei rapporti residui
-- -----------------------------------------------------------------------------
DELETE FROM `cm_intervention_reports`
 WHERE `report_code` LIKE 'DGB-%' AND `dgb_activity_id` IS NULL;

-- -----------------------------------------------------------------------------
-- 3. Le commesse fittizie create dallo stesso import.
--    `DatasetSync` gia' le rimuove durante la sincronizzazione, ma solo quelle
--    che trovano una corrispondenza reale: quelle rimaste orfane vanno tolte
--    qui, e solo se non hanno piu' rapporti collegati.
-- -----------------------------------------------------------------------------
DELETE FROM `cm_projects`
 WHERE `project_code` LIKE 'DGB-%'
   AND NOT EXISTS (SELECT 1 FROM `cm_intervention_reports` r
                    WHERE r.`project_id` = `cm_projects`.`id`);

-- -----------------------------------------------------------------------------
-- 4. Controllo permanente: residui del vecchio formato.
--    Deve restituire zero righe. Se ne restituisce, un import con il vecchio
--    formato e' tornato: va verificata la versione di DgbSync sul server.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_residui_import` AS
SELECT 'rapporti con codice DGB-<id>' AS problema,
       COUNT(*)                       AS righe,
       ROUND(SUM(`quantity_hours`), 2) AS ore,
       MIN(`report_date`)             AS dal,
       MAX(`report_date`)             AS al
  FROM `cm_intervention_reports`
 WHERE `report_code` LIKE 'DGB-%' AND `dgb_activity_id` IS NULL
HAVING COUNT(*) > 0
UNION ALL
SELECT 'commesse con codice DGB-<id>', COUNT(*), NULL, NULL, NULL
  FROM `cm_projects`
 WHERE `project_code` LIKE 'DGB-%'
HAVING COUNT(*) > 0;

