-- v1.8.72 — Fix $NAT e divisione aziendale sulla commessa
-- ════════════════════════════════════════════════════════════════
ALTER TABLE `cm_projects`
    ADD COLUMN IF NOT EXISTS `division_code` varchar(60) DEFAULT NULL
        COMMENT 'Divisione aziendale della commessa (forms_contract.id_division)';

ALTER TABLE `cm_projects`
    ADD INDEX IF NOT EXISTS `idx_proj_division` (`division_code`);

-- -----------------------------------------------------------------------------
-- Effort e redditivita' per divisione aziendale.
--
-- Le ore arrivano dai rapporti, il valore dalla commessa: sono grandezze di
-- provenienza diversa e vanno tenute distinte anche nella lettura.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_divisione_analisi` AS
SELECT
    COALESCE(p.`division_code`, '(non assegnata)') AS divisione,
    COALESCE(d.`name`, p.`division_code`)          AS divisione_nome,
    COUNT(DISTINCT p.`id`)                         AS commesse,
    SUM(CASE WHEN COALESCE(m.`has_revenue`, 1) = 0 THEN 1 ELSE 0 END) AS commesse_interne,
    ROUND(SUM(COALESCE(p.`value_total`, 0)), 2)    AS valore,
    COALESCE(r.`interventi`, 0)                    AS interventi,
    ROUND(COALESCE(r.`ore`, 0), 2)                 AS ore,
    ROUND(COALESCE(r.`costo`, 0), 2)               AS costo,
    ROUND(SUM(COALESCE(p.`value_total`, 0)) - COALESCE(r.`costo`, 0), 2) AS margine,
    CASE WHEN SUM(COALESCE(p.`value_total`, 0)) > 0
         THEN ROUND(100 * (SUM(COALESCE(p.`value_total`,0)) - COALESCE(r.`costo`,0))
                    / SUM(p.`value_total`), 1) END AS margine_pct,
    CASE WHEN COALESCE(r.`ore`, 0) > 0
         THEN ROUND(COALESCE(r.`costo`,0) / r.`ore`, 2) END AS costo_medio_orario
FROM `cm_projects` p
LEFT JOIN `cm_divisions`       d ON d.`code` = p.`division_code`
LEFT JOIN `cm_contract_models` m ON m.`service_line` = p.`service_line`
LEFT JOIN (
    SELECT pr.`division_code` AS dc,
           COUNT(*)                                        AS interventi,
           SUM(COALESCE(ir.`quantity_hours`, 0))           AS ore,
           SUM(COALESCE(ir.`company_cost_import`, 0))      AS costo
      FROM `cm_intervention_reports` ir
      JOIN `cm_projects` pr ON pr.`id` = ir.`project_id`
     GROUP BY pr.`division_code`
) r ON r.`dc` <=> p.`division_code`
GROUP BY COALESCE(p.`division_code`, '(non assegnata)'),
         COALESCE(d.`name`, p.`division_code`),
         r.`interventi`, r.`ore`, r.`costo`;

