    ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;
ALTER TABLE `dgb_forms_activity_operator`
    ADD COLUMN IF NOT EXISTS `import_batch_id` int(11) DEFAULT NULL;

