    ADD INDEX IF NOT EXISTS `idx_dfa_batch` (`import_batch_id`);
ALTER TABLE `dgb_forms_activity_operator`
    ADD INDEX IF NOT EXISTS `idx_dfao_batch` (`import_batch_id`);

-- -----------------------------------------------------------------------------
-- Controllo di allineamento fra le due basi.
--
-- Confronta mese per mese le attivita' DGB con i rapporti di intervento: uno
-- scostamento forte segnala che una delle due fonti e' rimasta indietro, che e'
-- esattamente il difetto corretto da questa release.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_allineamento_dgb` AS
SELECT
    m.`mese`,
    COALESCE(a.`attivita`, 0)  AS attivita_dgb,
    COALESCE(r.`rapporti`, 0)  AS rapporti_intervento,
    COALESCE(a.`attivita`, 0) - COALESCE(r.`rapporti`, 0) AS scarto,
    CASE WHEN COALESCE(r.`rapporti`, 0) > 0
         THEN ROUND(100 * COALESCE(a.`attivita`,0) / r.`rapporti`, 1) END AS pct_copertura
FROM (
    SELECT DATE_FORMAT(`date_start`, '%Y-%m') AS `mese`
      FROM `dgb_forms_activity` WHERE `date_start` IS NOT NULL
     UNION
    SELECT DATE_FORMAT(`report_date`, '%Y-%m')
      FROM `cm_intervention_reports` WHERE `report_date` IS NOT NULL
) m
LEFT JOIN (
    SELECT DATE_FORMAT(`date_start`, '%Y-%m') AS `ms`, COUNT(*) AS `attivita`
      FROM `dgb_forms_activity`
     WHERE `date_start` IS NOT NULL AND COALESCE(`deleted`, 0) = 0
     GROUP BY `ms`
) a ON a.`ms` = m.`mese`
LEFT JOIN (
    SELECT DATE_FORMAT(`report_date`, '%Y-%m') AS `ms`, COUNT(*) AS `rapporti`
      FROM `cm_intervention_reports`
     WHERE `report_date` IS NOT NULL
     GROUP BY `ms`
) r ON r.`ms` = m.`mese`;

