-- ════════════════════════════════════════════════════════════════
-- v1.8.75 — Sincronizzazione giornaliera pianificata
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Configurazione della pianificazione.
--    Riga unica (id fisso a 1): non ha senso avere due pianificazioni
--    concorrenti sulla stessa sorgente.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_sync_schedule` (
    `id`             tinyint(4)   NOT NULL DEFAULT 1,
    `is_enabled`     tinyint(1)   NOT NULL DEFAULT 0,
    `run_at`         time         NOT NULL DEFAULT '02:00:00' COMMENT 'Ora prevista di esecuzione',
    `window_minutes` int(11)      NOT NULL DEFAULT 120
        COMMENT 'Finestra entro cui recuperare una esecuzione mancata',
    `days_mask`      varchar(20)  NOT NULL DEFAULT '1,2,3,4,5,6,7'
        COMMENT 'Giorni attivi: 1=lunedi ... 7=domenica',
    `reconcile`      tinyint(1)   NOT NULL DEFAULT 0
        COMMENT '1 = esegue anche la riconciliazione (rimuove le righe orfane)',
    `last_run_at`    datetime     DEFAULT NULL,
    `last_status`    varchar(20)  DEFAULT NULL COMMENT 'ok, parziale, errore',
    `last_note`      varchar(500) DEFAULT NULL,
    `last_seconds`   decimal(10,1) DEFAULT NULL,
    `lock_owner`     varchar(80)  DEFAULT NULL,
    `lock_expires`   datetime     DEFAULT NULL,
    `updated_at`     datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `cm_sync_schedule` (`id`, `is_enabled`, `run_at`) VALUES (1, 0, '02:00:00');

-- -----------------------------------------------------------------------------
-- 2. Storico delle esecuzioni pianificate.
--
--    Tenuto separato da `cm_import_batches`, che registra il singolo dataset:
--    qui interessa l'esecuzione nel suo insieme, con l'esito complessivo. Senza
--    uno storico, una pianificazione che smette di funzionare se ne accorge solo
--    quando qualcuno nota che i dati sono vecchi.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_sync_schedule_log` (
    `id`            int(11)      NOT NULL AUTO_INCREMENT,
    `started_at`    datetime     NOT NULL DEFAULT current_timestamp(),
    `finished_at`   datetime     DEFAULT NULL,
    `trigger_type`  varchar(20)  NOT NULL DEFAULT 'pianificata' COMMENT 'pianificata, manuale',
    `status`        varchar(20)  DEFAULT NULL COMMENT 'ok, parziale, errore, saltata',
    `datasets_ok`   int(11)      NOT NULL DEFAULT 0,
    `datasets_err`  int(11)      NOT NULL DEFAULT 0,
    `rows_read`     int(11)      NOT NULL DEFAULT 0,
    `rows_new`      int(11)      NOT NULL DEFAULT 0,
    `rows_updated`  int(11)      NOT NULL DEFAULT 0,
    `rows_removed`  int(11)      NOT NULL DEFAULT 0,
    `seconds`       decimal(10,1) DEFAULT NULL,
    `note`          varchar(1000) DEFAULT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_sched_log_start` (`started_at`),
    KEY `idx_sched_log_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. Stato della pianificazione, per il riquadro di controllo.
--
--    `in_ritardo` e' l'informazione che conta: una pianificazione attiva che non
--    gira da piu' di un giorno e mezzo e' rotta, e va segnalata invece di essere
--    scoperta guardando dati vecchi.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sync_schedule_stato` AS
SELECT
    s.`is_enabled`                                  AS attiva,
    s.`run_at`                                      AS ora_prevista,
    s.`days_mask`                                   AS giorni,
    s.`reconcile`                                   AS con_riconciliazione,
    s.`last_run_at`                                 AS ultima_esecuzione,
    s.`last_status`                                 AS ultimo_esito,
    s.`last_seconds`                                AS ultima_durata,
    CASE WHEN s.`lock_expires` IS NOT NULL AND s.`lock_expires` > NOW()
         THEN 1 ELSE 0 END                          AS in_esecuzione,
    TIMESTAMPDIFF(HOUR, s.`last_run_at`, NOW())     AS ore_dall_ultima,
    CASE
        WHEN s.`is_enabled` = 0                     THEN 'disattivata'
        WHEN s.`last_run_at` IS NULL                THEN 'mai eseguita'
        WHEN TIMESTAMPDIFF(HOUR, s.`last_run_at`, NOW()) > 36 THEN 'IN RITARDO'
        WHEN s.`last_status` = 'errore'             THEN 'ultima esecuzione fallita'
        WHEN s.`last_status` = 'parziale'           THEN 'ultima esecuzione parziale'
        ELSE 'regolare'
    END                                             AS diagnosi,
    (SELECT COUNT(*) FROM `cm_sync_schedule_log` l
      WHERE l.`started_at` >= NOW() - INTERVAL 30 DAY) AS esecuzioni_30gg,
    (SELECT COUNT(*) FROM `cm_sync_schedule_log` l
      WHERE l.`started_at` >= NOW() - INTERVAL 30 DAY AND l.`status` = 'errore') AS errori_30gg
FROM `cm_sync_schedule` s
WHERE s.`id` = 1;

