-- ════════════════════════════════════════════════════════════════
-- v1.8.77 — Collegamento dei tecnici all'anagrafica
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
-- 1. Indice sul nome, per rendere praticabili gli UPDATE che seguono.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports`
    ADD INDEX IF NOT EXISTS `idx_ir_tech_raw` (`technician_raw`);

-- -----------------------------------------------------------------------------
-- 2. Collegamento al PROFESSIONISTA — nome nell'ordine diretto
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports` r
  JOIN `cm_professionals` p
    ON TRIM(CONCAT(COALESCE(p.`first_name`,''),' ',COALESCE(p.`last_name`,''))) = TRIM(r.`technician_raw`)
   SET r.`technician_professional_id` = p.`id`
 WHERE r.`technician_professional_id` IS NULL
   AND COALESCE(r.`technician_raw`,'') <> '';

-- -----------------------------------------------------------------------------
-- 3. Collegamento al PROFESSIONISTA — nome e cognome invertiti.
--    E' il caso di Nushi Irni: cm_professionals ha first_name='Nushi',
--    employees ha first_name='Irni'.
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports` r
  JOIN `cm_professionals` p
    ON TRIM(CONCAT(COALESCE(p.`last_name`,''),' ',COALESCE(p.`first_name`,''))) = TRIM(r.`technician_raw`)
   SET r.`technician_professional_id` = p.`id`
 WHERE r.`technician_professional_id` IS NULL
   AND COALESCE(r.`technician_raw`,'') <> '';

-- -----------------------------------------------------------------------------
-- 4. Collegamento al DIPENDENTE tramite il professionista.
--    Il riferimento esiste gia' in anagrafica: si riporta sul fatto invece di
--    ricalcolarlo, cosi' una riconciliazione fatta a mano non viene scavalcata.
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports` r
  JOIN `cm_professionals` p ON p.`id` = r.`technician_professional_id`
   SET r.`technician_id` = COALESCE(p.`employee_id`, p.`matched_employee_id`)
 WHERE r.`technician_id` IS NULL
   AND COALESCE(p.`employee_id`, p.`matched_employee_id`) IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 5. Collegamento diretto al DIPENDENTE, per i tecnici che non sono in
--    cm_professionals. Entrambi gli ordini del nome.
-- -----------------------------------------------------------------------------
UPDATE `cm_intervention_reports` r
  JOIN `employees` e
    ON TRIM(CONCAT(COALESCE(e.`first_name`,''),' ',COALESCE(e.`last_name`,''))) = TRIM(r.`technician_raw`)
   SET r.`technician_id` = e.`id`
 WHERE r.`technician_id` IS NULL
   AND COALESCE(r.`technician_raw`,'') <> '';

UPDATE `cm_intervention_reports` r
  JOIN `employees` e
    ON TRIM(CONCAT(COALESCE(e.`last_name`,''),' ',COALESCE(e.`first_name`,''))) = TRIM(r.`technician_raw`)
   SET r.`technician_id` = e.`id`
 WHERE r.`technician_id` IS NULL
   AND COALESCE(r.`technician_raw`,'') <> '';

-- -----------------------------------------------------------------------------
-- 6. Controllo permanente dei tecnici non riconciliati.
--
--    Elenca i nomi presenti nei rapporti che non trovano corrispondenza in
--    anagrafica, con quante ore pesano. Deve restituire zero righe: se ne
--    restituisce, quelle ore sono invisibili a ogni prospetto per persona.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_tecnici_scollegati` AS
SELECT
    r.`technician_raw`                       AS tecnico,
    COUNT(*)                                 AS moduli,
    ROUND(SUM(COALESCE(r.`quantity_hours`,0)), 2) AS ore,
    COUNT(DISTINCT r.`project_code`)         AS commesse,
    MIN(r.`report_date`)                     AS dal,
    MAX(r.`report_date`)                     AS al
FROM `cm_intervention_reports` r
WHERE COALESCE(r.`technician_raw`,'') <> ''
  AND r.`technician_id` IS NULL
  AND r.`technician_professional_id` IS NULL
GROUP BY r.`technician_raw`;

