-- ════════════════════════════════════════════════════════════════
-- v1.8.78 — Allocazioni duplicate e dettaglio in/fuori orario
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
-- 1. Fotografia prima della pulizia
-- -----------------------------------------------------------------------------
INSERT INTO `cm_cleanup_log` (`scope`, `rows_before`, `rows_removed`, `hours_before`, `hours_removed`, `note`)
SELECT
    'v1.8.78 allocazioni duplicate',
    (SELECT COUNT(*) FROM `dgb_forms_activity_operator`),
    (SELECT COUNT(*) FROM `dgb_forms_activity_operator` x
      WHERE x.`id` NOT IN (SELECT `keep` FROM (
            SELECT MAX(`id`) AS `keep` FROM `dgb_forms_activity_operator`
             GROUP BY `id_activity`, `id_operator`) k)),
    (SELECT ROUND(SUM(`hours`), 2) FROM `dgb_forms_activity_operator`),
    (SELECT ROUND(SUM(`hours`), 2) FROM `dgb_forms_activity_operator` x
      WHERE x.`id` NOT IN (SELECT `keep` FROM (
            SELECT MAX(`id`) AS `keep` FROM `dgb_forms_activity_operator`
             GROUP BY `id_activity`, `id_operator`) k)),
    'Allocazioni ripetute per la stessa attivita e operatore: manca il vincolo di unicita'
FROM DUAL
WHERE (SELECT COUNT(*) FROM `dgb_forms_activity_operator` x
        WHERE x.`id` NOT IN (SELECT `keep` FROM (
              SELECT MAX(`id`) AS `keep` FROM `dgb_forms_activity_operator`
               GROUP BY `id_activity`, `id_operator`) k)) > 0;

-- -----------------------------------------------------------------------------
-- 2. Deduplica.
--
--    Si conserva l'id PIU' ALTO, cioe' la riga scritta per ultima: se un giorno
--    i valori differissero — revisione anziche' copia — l'ultima e' quella che
--    riflette lo stato corrente della sorgente. Sui dati attuali la scelta e'
--    indifferente perche' tutti e 77 i gruppi hanno valori identici, ma la
--    regola deve reggere anche il caso che oggi non si presenta.
--
--    La tabella d'appoggio e' creata con CREATE ... AS SELECT per ereditare i
--    tipi dalla sorgente (lezione della v1.8.66 sulle collation).
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_alloc_keep78`;

CREATE TABLE `tmp_alloc_keep78` AS
SELECT MAX(`id`) AS `keep_id`
  FROM `dgb_forms_activity_operator`
 GROUP BY `id_activity`, `id_operator`;

ALTER TABLE `tmp_alloc_keep78` ADD PRIMARY KEY (`keep_id`);

DELETE ao FROM `dgb_forms_activity_operator` ao
  LEFT JOIN `tmp_alloc_keep78` k ON k.`keep_id` = ao.`id`
 WHERE k.`keep_id` IS NULL;

DROP TABLE IF EXISTS `tmp_alloc_keep78`;

-- -----------------------------------------------------------------------------
-- 3. Il vincolo che impedisce il ripetersi.
--
--    Va aggiunto DOPO la deduplica, altrimenti fallisce sulle righe esistenti.
--    E' la protezione che mancava: senza, ogni sincronizzazione puo' reinserire
--    le stesse allocazioni.
-- -----------------------------------------------------------------------------
ALTER TABLE `dgb_forms_activity_operator`
    ADD UNIQUE KEY IF NOT EXISTS `uq_dfao_activity_operator` (`id_activity`, `id_operator`);

-- -----------------------------------------------------------------------------
-- 4. Ore in orario e fuori orario per allocazione.
--
--    La ripartizione usa la stessa espressione della v1.8.53: sovrapposizione
--    fra l'intervallo dell'intervento e le fasce 09-13 e 14-18, nei giorni
--    feriali. Le ore consuntivate vengono ripartite proporzionalmente, non
--    ricalcolate: la durata cronologica e il consuntivo non coincidono, e il
--    consuntivo e' il dato che conta.
--
--    `ore_extra` resta esposto come dettaglio contrattuale, DENTRO le ore
--    consuntivate e non in aggiunta.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_ore_dettaglio` AS
SELECT
    ao.`id`                                   AS allocazione_id,
    a.`id`                                    AS attivita_id,
    a.`code`                                  AS modulo,
    ao.`id_operator`                          AS operatore_id,
    DATE(a.`date_start`)                      AS giorno,
    a.`date_start`                            AS inizio,
    a.`date_dead_line`                        AS fine,
    a.`id_contract`                           AS contratto_id,
    ROUND(COALESCE(ao.`hours`, 0), 2)         AS ore_consuntivate,
    ROUND(COALESCE(ao.`extra_hours`, 0), 2)   AS ore_extra,
    ROUND(COALESCE(ao.`hours`, 0) - COALESCE(ao.`extra_hours`, 0), 2) AS ore_ordinarie_contratto,

    -- collocazione temporale: quota della durata che cade nelle fasce di orario
    ROUND(COALESCE(ao.`hours`, 0) * (
        CASE
            WHEN DAYOFWEEK(a.`date_start`) IN (1, 7) THEN 0
            WHEN a.`date_dead_line` IS NULL
              OR TIMESTAMPDIFF(SECOND, a.`date_start`, a.`date_dead_line`) <= 0 THEN
                CASE WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
                       OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800
                     THEN 1 ELSE 0 END
            ELSE LEAST(1, GREATEST(0, (
                  GREATEST(0, LEAST(TIME_TO_SEC(TIME(a.`date_dead_line`)), 46800)
                            - GREATEST(TIME_TO_SEC(TIME(a.`date_start`)), 32400))
                + GREATEST(0, LEAST(TIME_TO_SEC(TIME(a.`date_dead_line`)), 64800)
                            - GREATEST(TIME_TO_SEC(TIME(a.`date_start`)), 50400))
            ) / TIMESTAMPDIFF(SECOND, a.`date_start`, a.`date_dead_line`)))
        END), 2)                              AS ore_in_orario,

    -- il fuori orario per DIFFERENZA, cosi' la somma quadra sempre con il
    -- consuntivo: calcolarlo a parte lascerebbe scarti di arrotondamento
    ROUND(COALESCE(ao.`hours`, 0), 2) - ROUND(COALESCE(ao.`hours`, 0) * (
        CASE
            WHEN DAYOFWEEK(a.`date_start`) IN (1, 7) THEN 0
            WHEN a.`date_dead_line` IS NULL
              OR TIMESTAMPDIFF(SECOND, a.`date_start`, a.`date_dead_line`) <= 0 THEN
                CASE WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
                       OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800
                     THEN 1 ELSE 0 END
            ELSE LEAST(1, GREATEST(0, (
                  GREATEST(0, LEAST(TIME_TO_SEC(TIME(a.`date_dead_line`)), 46800)
                            - GREATEST(TIME_TO_SEC(TIME(a.`date_start`)), 32400))
                + GREATEST(0, LEAST(TIME_TO_SEC(TIME(a.`date_dead_line`)), 64800)
                            - GREATEST(TIME_TO_SEC(TIME(a.`date_start`)), 50400))
            ) / TIMESTAMPDIFF(SECOND, a.`date_start`, a.`date_dead_line`)))
        END), 2)                              AS ore_fuori_orario
FROM `dgb_forms_activity_operator` ao
JOIN `dgb_forms_activity` a ON a.`id` = ao.`id_activity`
WHERE COALESCE(a.`deleted`, 0) = 0;

-- -----------------------------------------------------------------------------
-- 5. Riepilogo per tecnico e giorno, con entrambe le letture.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_ore_tecnico_giorno` AS
SELECT
    d.`operatore_id`,
    d.`giorno`,
    COUNT(*)                                  AS moduli,
    ROUND(SUM(d.`ore_consuntivate`), 2)       AS ore_consuntivate,
    ROUND(SUM(d.`ore_ordinarie_contratto`), 2) AS ore_ordinarie,
    ROUND(SUM(d.`ore_extra`), 2)              AS ore_extra,
    ROUND(SUM(d.`ore_in_orario`), 2)          AS ore_in_orario,
    ROUND(SUM(d.`ore_fuori_orario`), 2)       AS ore_fuori_orario
FROM `v_dgb_ore_dettaglio` d
GROUP BY d.`operatore_id`, d.`giorno`;

-- -----------------------------------------------------------------------------
-- 6. Controllo permanente delle allocazioni ripetute.
--    Deve restituire zero righe: il vincolo lo garantisce, ma la vista serve a
--    verificarlo dopo ogni sincronizzazione senza dover ricordare la query.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_dgb_allocazioni_duplicate` AS
SELECT
    ao.`id_activity`                  AS attivita_id,
    a.`code`                          AS modulo,
    ao.`id_operator`                  AS operatore_id,
    COUNT(*)                          AS righe,
    ROUND(SUM(ao.`hours`), 2)         AS ore_totali,
    ROUND(MAX(ao.`hours`), 2)         AS ore_corrette,
    ROUND(SUM(ao.`hours`) - MAX(ao.`hours`), 2) AS ore_in_eccesso
FROM `dgb_forms_activity_operator` ao
JOIN `dgb_forms_activity` a ON a.`id` = ao.`id_activity`
GROUP BY ao.`id_activity`, a.`code`, ao.`id_operator`
HAVING COUNT(*) > 1;

