-- ════════════════════════════════════════════════════════════════
-- v1.8.79 — Deduplica a monte nelle query di sincronizzazione
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Il vincolo va rimosso prima della pulizia.
--
--    Se una sincronizzazione parziale ha lasciato la tabella in uno stato
--    incoerente, la DELETE che segue deve poter agire senza che il vincolo
--    interferisca. Viene riapplicato subito dopo.
-- -----------------------------------------------------------------------------
ALTER TABLE `dgb_forms_activity_operator`
    DROP INDEX IF EXISTS `uq_dfao_activity_operator`;

-- -----------------------------------------------------------------------------
-- 2. Pulizia dei duplicati eventualmente rientrati
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_alloc_keep79`;

CREATE TABLE `tmp_alloc_keep79` AS
SELECT MAX(`id`) AS `keep_id`
  FROM `dgb_forms_activity_operator`
 GROUP BY `id_activity`, `id_operator`;

ALTER TABLE `tmp_alloc_keep79` ADD PRIMARY KEY (`keep_id`);

DELETE ao FROM `dgb_forms_activity_operator` ao
  LEFT JOIN `tmp_alloc_keep79` k ON k.`keep_id` = ao.`id`
 WHERE k.`keep_id` IS NULL;

DROP TABLE IF EXISTS `tmp_alloc_keep79`;

-- -----------------------------------------------------------------------------
-- 3. Vincolo riapplicato
-- -----------------------------------------------------------------------------
ALTER TABLE `dgb_forms_activity_operator`
    ADD UNIQUE KEY IF NOT EXISTS `uq_dfao_activity_operator` (`id_activity`, `id_operator`);

-- -----------------------------------------------------------------------------
-- 4. Controllo dei rapporti generati due volte dallo stesso intervento.
--
--    Il difetto si propagava anche a `cm_intervention_reports`: due allocazioni
--    sorgente per la stessa coppia generavano due rapporti. La grana
--    `source_uid` non li intercettava perche' i codici erano diversi.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_rapporti_doppi_attivita` AS
SELECT
    r.`dgb_activity_id`               AS attivita_id,
    r.`dgb_activity_code`             AS modulo,
    r.`technician_raw`                AS tecnico,
    COUNT(*)                          AS rapporti,
    ROUND(SUM(COALESCE(r.`quantity_hours`,0)), 2) AS ore_totali,
    ROUND(MAX(COALESCE(r.`quantity_hours`,0)), 2) AS ore_corrette,
    ROUND(SUM(COALESCE(r.`quantity_hours`,0)) - MAX(COALESCE(r.`quantity_hours`,0)), 2) AS ore_in_eccesso
FROM `cm_intervention_reports` r
WHERE r.`dgb_activity_id` IS NOT NULL
GROUP BY r.`dgb_activity_id`, r.`dgb_activity_code`, r.`technician_raw`
HAVING COUNT(*) > 1;

