-- ════════════════════════════════════════════════════════════════
-- v1.8.81 — Serie temporali delle assenze e dettaglio per tecnico
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. La categoria trasversale delle visite.
--    In tabella e non cablata: il criterio di riconoscimento e' una convenzione
--    di scrittura, e le convenzioni cambiano.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_commitment_types`
    ADD COLUMN IF NOT EXISTS `is_visit_candidate` tinyint(1) NOT NULL DEFAULT 0
        COMMENT '1 = fra i tipi in cui puo comparire una visita medica';

UPDATE `cm_commitment_types` SET `is_visit_candidate` = 1
 WHERE `code` IN ('LEAVE', 'RECOVERY', 'HOLIDAY', 'SICK_LEAVE');

-- -----------------------------------------------------------------------------
-- 2. Serie temporali delle assenze, per giorno e tipo.
--
--    `visite` e' una colonna a parte e NON si somma alle altre: le sue ore sono
--    gia' dentro ferie, permessi o recuperi. Tenerla come colonna separata
--    invece che come tipo evita che qualcuno la sommi al totale.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_assenze_serie` AS
SELECT
    c.`start_date`                        AS giorno,
    DATE_FORMAT(c.`start_date`, '%Y-%m')  AS anno_mese,
    c.`operator_id`,
    c.`operator_name`                     AS operatore,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'HOLIDAY'    THEN c.`hours` ELSE 0 END), 2) AS ferie,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'LEAVE'      THEN c.`hours` ELSE 0 END), 2) AS permessi,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'RECOVERY'   THEN c.`hours` ELSE 0 END), 2) AS recuperi,
    ROUND(SUM(CASE WHEN c.`commitment_type` = 'SICK_LEAVE' THEN c.`hours` ELSE 0 END), 2) AS malattia,
    -- trasversale: gia' compresa nelle colonne precedenti
    ROUND(SUM(CASE WHEN c.`description` REGEXP '[Vv]isit' THEN c.`hours` ELSE 0 END), 2) AS visite,
    ROUND(SUM(CASE WHEN t.`is_absence` = 1 THEN c.`hours` ELSE 0 END), 2)                AS totale_assenze
FROM `cm_operator_commitments` c
JOIN `cm_commitment_types` t ON t.`code` = c.`commitment_type`
WHERE c.`start_date` IS NOT NULL
GROUP BY c.`start_date`, c.`operator_id`, c.`operator_name`;

-- -----------------------------------------------------------------------------
-- 3. Le stesse serie aggregate per giorno, per il grafico complessivo
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_assenze_serie_giorno` AS
SELECT
    `giorno`,
    `anno_mese`,
    COUNT(DISTINCT `operator_id`)   AS operatori,
    ROUND(SUM(`ferie`), 2)          AS ferie,
    ROUND(SUM(`permessi`), 2)       AS permessi,
    ROUND(SUM(`recuperi`), 2)       AS recuperi,
    ROUND(SUM(`malattia`), 2)       AS malattia,
    ROUND(SUM(`visite`), 2)         AS visite,
    ROUND(SUM(`totale_assenze`), 2) AS totale_assenze
FROM `v_cm_assenze_serie`
GROUP BY `giorno`, `anno_mese`;

