-- ════════════════════════════════════════════════════════════════
-- v1.8.82 — Sezione Service Desk: ticket, livelli L1/L2, statistiche
-- ════════════════════════════════════════════════════════════════
--
-- Sono percio' una classe a se': "presa in carico diretta da specialisti".
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Messaggi dei ticket
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_sd_messages` (
    `id`             int(11)      NOT NULL AUTO_INCREMENT,
    `source_id`      int(11)      DEFAULT NULL,
    `message_code`   varchar(60)  DEFAULT NULL COMMENT 'WTS_000000003_001',
    `ticket_code`    varchar(60)  DEFAULT NULL COMMENT 'WTS_000000003',
    `ticket_id`      int(11)      DEFAULT NULL,
    `msg_type`       varchar(30)  DEFAULT NULL COMMENT 'SUPPORT_MSG, CUSTOMER_MSG, INTERNAL_NOTE',
    `subject`        varchar(400) DEFAULT NULL,
    `status_before`  varchar(40)  DEFAULT NULL,
    `status_after`   varchar(40)  DEFAULT NULL,
    `received_at`    datetime     DEFAULT NULL,
    `duration_min`   decimal(12,2) DEFAULT NULL,
    `author_id`      int(11)      DEFAULT NULL COMMENT 'dgb_operator.id',
    `author_name`    varchar(150) DEFAULT NULL,
    `queue_id`       int(11)      DEFAULT NULL,
    `queue_name`     varchar(120) DEFAULT NULL,
    `from_name`      varchar(150) DEFAULT NULL,
    `import_batch_id` int(11)     DEFAULT NULL,
    `created_at`     datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`     datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_sdmsg_source` (`source_id`),
    KEY `idx_sdmsg_ticket` (`ticket_id`),
    KEY `idx_sdmsg_code`   (`ticket_code`),
    KEY `idx_sdmsg_author` (`author_id`),
    KEY `idx_sdmsg_queue`  (`queue_id`),
    KEY `idx_sdmsg_date`   (`received_at`),
    KEY `idx_sdmsg_type`   (`msg_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. Chi appartiene al primo livello.
--
--    Vista e non tabella: l'appartenenza e' una decisione del portale, presa in
--    "Unita Organizzative Tecniche". Copiarla creerebbe un secondo elenco da
--    tenere allineato, e un tecnico spostato di unita' resterebbe classificato
--    come prima.
--
--    Il legame passa dal NOME perche' `cm_tech_profiles` punta a `employees` o
--    `cm_professionals`, mentre i messaggi portano l'id dell'operatore DGB.
--    Entrambi gli ordini nome/cognome, come nella v1.8.77.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_team` AS
SELECT DISTINCT
    COALESCE(TRIM(CONCAT(COALESCE(e.`first_name`,''),' ',COALESCE(e.`last_name`,''))),
             TRIM(CONCAT(COALESCE(p.`first_name`,''),' ',COALESCE(p.`last_name`,'')))) AS nome,
    COALESCE(TRIM(CONCAT(COALESCE(e.`last_name`,''),' ',COALESCE(e.`first_name`,''))),
             TRIM(CONCAT(COALESCE(p.`last_name`,''),' ',COALESCE(p.`first_name`,'')))) AS nome_invertito,
    tp.`employee_id`,
    tp.`professional_id`,
    su.`name` AS sotto_unita
FROM `cm_tech_profiles` tp
JOIN `cm_tech_units` u ON u.`id` = tp.`unit_id` AND u.`name` = 'Service Desk'
LEFT JOIN `cm_tech_subunits`  su ON su.`id` = tp.`subunit_id`
LEFT JOIN `employees`         e  ON e.`id`  = tp.`employee_id`
LEFT JOIN `cm_professionals`  p  ON p.`id`  = tp.`professional_id`;

-- -----------------------------------------------------------------------------
-- 3. Messaggi classificati per livello
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_messaggi` AS
SELECT
    m.*,
    CASE WHEN t.`nome` IS NOT NULL THEN 'L1' ELSE 'L2' END AS livello,
    t.`sotto_unita`,
    DATE(m.`received_at`)                    AS giorno,
    DATE_FORMAT(m.`received_at`, '%Y-%m')    AS anno_mese
FROM `cm_sd_messages` m
LEFT JOIN `v_cm_sd_team` t
       ON t.`nome` = m.`author_name` OR t.`nome_invertito` = m.`author_name`;

-- -----------------------------------------------------------------------------
-- 4. Il ticket ricostruito dai suoi messaggi.
--
--    Lo stato corrente e' il `status_after` dell'ULTIMO messaggio: e' il motivo
--    per cui serve la sottoquery sul massimo `received_at`, e non basta un
--    MAX() sullo stato che restituirebbe il valore alfabeticamente maggiore.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_ticket` AS
SELECT
    m.`ticket_code`                                   AS ticket,
    MIN(m.`ticket_id`)                                AS ticket_id,
    MIN(m.`subject`)                                  AS oggetto,
    MIN(m.`queue_name`)                               AS coda,
    COUNT(*)                                          AS messaggi,
    SUM(m.`msg_type` = 'SUPPORT_MSG')                 AS messaggi_supporto,
    SUM(m.`msg_type` = 'CUSTOMER_MSG')                AS messaggi_cliente,
    SUM(m.`msg_type` = 'INTERNAL_NOTE')               AS note_interne,
    SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L1') AS msg_l1,
    SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L2') AS msg_l2,
    MIN(m.`received_at`)                              AS aperto_il,
    MAX(m.`received_at`)                              AS ultimo_messaggio,
    TIMESTAMPDIFF(HOUR, MIN(m.`received_at`), MAX(m.`received_at`)) AS durata_ore,
    (SELECT x.`status_after` FROM `cm_sd_messages` x
      WHERE x.`ticket_code` = m.`ticket_code`
      ORDER BY x.`received_at` DESC, x.`source_id` DESC LIMIT 1) AS stato,
    -- TRE classi: i ticket senza alcun messaggio L1 non sono escalation
    -- mancate, nascono presso gli specialisti
    CASE
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG') = 0 THEN 'senza risposta'
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L1') = 0
             THEN 'presa in carico diretta da specialisti'
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L2') > 0
             THEN 'escalation di 2 livello verso specialisti'
        ELSE 'risolto dal Service Desk'
    END                                               AS gestione
FROM `v_cm_sd_messaggi` m
WHERE m.`ticket_code` IS NOT NULL AND m.`ticket_code` <> ''
GROUP BY m.`ticket_code`;

-- -----------------------------------------------------------------------------
-- 5. Quadro per periodo
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_riepilogo` AS
SELECT
    DATE_FORMAT(`aperto_il`, '%Y-%m')                 AS anno_mese,
    COUNT(*)                                          AS ticket,
    SUM(`gestione` = 'risolto dal Service Desk')      AS risolti_l1,
    SUM(`gestione` = 'escalation di 2 livello verso specialisti') AS escalation_l2,
    SUM(`gestione` = 'presa in carico diretta da specialisti')    AS diretti_specialisti,
    SUM(`gestione` = 'senza risposta')                AS senza_risposta,
    SUM(`stato` = 'CLOSED')                           AS chiusi,
    ROUND(100 * SUM(`gestione` = 'escalation di 2 livello verso specialisti')
          / NULLIF(SUM(`gestione` IN ('risolto dal Service Desk',
                    'escalation di 2 livello verso specialisti')), 0), 1) AS tasso_escalation_pct,
    ROUND(AVG(`messaggi`), 1)                         AS messaggi_medi,
    ROUND(AVG(NULLIF(`durata_ore`, 0)), 1)            AS durata_media_ore
FROM `v_cm_sd_ticket`
WHERE `aperto_il` IS NOT NULL
GROUP BY anno_mese;

-- -----------------------------------------------------------------------------
-- 6. Operativita' per tecnico
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_operatori` AS
SELECT
    m.`author_name`                         AS tecnico,
    MAX(m.`livello`)                        AS livello,
    MAX(m.`sotto_unita`)                    AS sotto_unita,
    COUNT(*)                                AS messaggi,
    SUM(m.`msg_type` = 'SUPPORT_MSG')       AS risposte_cliente,
    SUM(m.`msg_type` = 'INTERNAL_NOTE')     AS note_interne,
    COUNT(DISTINCT m.`ticket_code`)         AS ticket_toccati,
    COUNT(DISTINCT m.`queue_name`)          AS code,
    MIN(m.`received_at`)                    AS dal,
    MAX(m.`received_at`)                    AS al
FROM `v_cm_sd_messaggi` m
WHERE m.`author_name` IS NOT NULL AND m.`author_name` <> ''
GROUP BY m.`author_name`;

