-- ════════════════════════════════════════════════════════════════
-- v1.8.83 — Dettaglio dei ticket senza risposta e predisposizione SLA
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- Il ticket, con la classe "senza risposta" scomposta in tre.
--
-- Le altre tre classi restano invariate: la scomposizione riguarda solo i
-- ticket privi di messaggi di supporto.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_ticket` AS
SELECT
    m.`ticket_code`                                   AS ticket,
    MIN(m.`ticket_id`)                                AS ticket_id,
    MIN(m.`subject`)                                  AS oggetto,
    MIN(m.`queue_name`)                               AS coda,
    COUNT(*)                                          AS messaggi,
    SUM(m.`msg_type` = 'SUPPORT_MSG')                 AS messaggi_supporto,
    SUM(m.`msg_type` = 'CUSTOMER_MSG')                AS messaggi_cliente,
    SUM(m.`msg_type` = 'INTERNAL_NOTE')               AS note_interne,
    SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L1') AS msg_l1,
    SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L2') AS msg_l2,
    SUM(m.`msg_type` = 'INTERNAL_NOTE' AND m.`livello` = 'L1') AS note_l1,
    SUM(m.`msg_type` = 'INTERNAL_NOTE' AND m.`livello` = 'L2') AS note_l2,
    MIN(m.`received_at`)                              AS aperto_il,
    MAX(m.`received_at`)                              AS ultimo_messaggio,
    TIMESTAMPDIFF(HOUR, MIN(m.`received_at`), MAX(m.`received_at`)) AS durata_ore,
    (SELECT x.`status_after` FROM `cm_sd_messages` x
      WHERE x.`ticket_code` = m.`ticket_code`
      ORDER BY x.`received_at` DESC, x.`source_id` DESC LIMIT 1) AS stato,
    CASE
        -- ── nessun messaggio di supporto: tre situazioni distinte ──────────
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG') = 0
             AND SUM(m.`msg_type` = 'INTERNAL_NOTE') = 0
             THEN 'mai preso in carico'
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG') = 0
             AND SUM(m.`msg_type` = 'CUSTOMER_MSG') > 0
             THEN 'cliente senza risposta scritta'
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG') = 0
             THEN 'lavorato senza risposta scritta'
        -- ── con messaggi di supporto: la classificazione della v1.8.82 ─────
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L1') = 0
             THEN 'presa in carico diretta da specialisti'
        WHEN SUM(m.`msg_type` = 'SUPPORT_MSG' AND m.`livello` = 'L2') > 0
             THEN 'escalation di 2 livello verso specialisti'
        ELSE 'risolto dal Service Desk'
    END                                               AS gestione,
    -- chi ha toccato il ticket, anche solo con note: risponde alla domanda
    -- "da chi non si e' avuta risposta"
    CASE
        WHEN SUM(m.`livello` = 'L1') > 0 AND SUM(m.`livello` = 'L2') > 0 THEN 'L1 e L2'
        WHEN SUM(m.`livello` = 'L1') > 0 THEN 'solo L1'
        WHEN SUM(m.`livello` = 'L2') > 0 THEN 'solo L2'
        ELSE 'nessuno'
    END                                               AS presidio
FROM `v_cm_sd_messaggi` m
WHERE m.`ticket_code` IS NOT NULL AND m.`ticket_code` <> ''
GROUP BY m.`ticket_code`;

-- -----------------------------------------------------------------------------
-- I ticket scoperti, per l'azione operativa.
--
-- Vista dedicata perche' e' l'unica classe che richiede un intervento: gli altri
-- 559 casi sono lavoro svolto e tracciato diversamente.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_scoperti` AS
SELECT
    `ticket`, `oggetto`, `coda`, `stato`, `messaggi`,
    `aperto_il`,
    TIMESTAMPDIFF(DAY, `aperto_il`, NOW()) AS giorni_aperto,
    `gestione`
FROM `v_cm_sd_ticket`
WHERE `gestione` = 'mai preso in carico'
   OR (`gestione` = 'cliente senza risposta scritta' AND `stato` <> 'CLOSED');

-- -----------------------------------------------------------------------------
-- Riepilogo mensile con le sei classi
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_riepilogo` AS
SELECT
    DATE_FORMAT(`aperto_il`, '%Y-%m')                 AS anno_mese,
    COUNT(*)                                          AS ticket,
    SUM(`gestione` = 'risolto dal Service Desk')      AS risolti_l1,
    SUM(`gestione` = 'escalation di 2 livello verso specialisti') AS escalation_l2,
    SUM(`gestione` = 'presa in carico diretta da specialisti')    AS diretti_specialisti,
    SUM(`gestione` = 'lavorato senza risposta scritta')           AS lavorati_senza_risposta,
    SUM(`gestione` = 'cliente senza risposta scritta')            AS cliente_senza_risposta,
    SUM(`gestione` = 'mai preso in carico')                       AS mai_presi_in_carico,
    SUM(`stato` = 'CLOSED')                           AS chiusi,
    ROUND(100 * SUM(`gestione` = 'escalation di 2 livello verso specialisti')
          / NULLIF(SUM(`gestione` IN ('risolto dal Service Desk',
                    'escalation di 2 livello verso specialisti')), 0), 1) AS tasso_escalation_pct,
    ROUND(AVG(`messaggi`), 1)                         AS messaggi_medi,
    ROUND(AVG(NULLIF(`durata_ore`, 0)), 1)            AS durata_media_ore
FROM `v_cm_sd_ticket`
WHERE `aperto_il` IS NOT NULL
GROUP BY anno_mese;

-- -----------------------------------------------------------------------------
-- Predisposizione SLA.
--
-- Gli SLA sono definiti sulla commessa e possono essere vuoti, oppure ereditati
-- da `tt_sla`, che non e' esportata. La tabella accoglie la definizione quando
-- sara' disponibile: finche' e' vuota, le viste espongono i tempi OSSERVATI
-- senza confrontarli con soglie inesistenti.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_sd_sla` (
    `id`              int(11)      NOT NULL AUTO_INCREMENT,
    `source_id`       int(11)      DEFAULT NULL COMMENT 'tt_sla.id, quando disponibile',
    `project_code`    varchar(50)  DEFAULT NULL COMMENT 'NULL = SLA di default',
    `queue_name`      varchar(120) DEFAULT NULL,
    `label`           varchar(120) DEFAULT NULL,
    `take_charge_min` int(11)      DEFAULT NULL COMMENT 'Minuti per la presa in carico',
    `resolution_min`  int(11)      DEFAULT NULL COMMENT 'Minuti per la risoluzione',
    `is_active`       tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`      datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`      datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    KEY `idx_sdsla_project` (`project_code`),
    KEY `idx_sdsla_queue`   (`queue_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

