-- ════════════════════════════════════════════════════════════════
-- v1.8.86 — Analisi per singolo componente del Service Desk
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
-- 1. Chi ha preso in carico ciascun ticket.
--
--    La prima risposta di supporto, individuata dal minimo `received_at` fra i
--    soli messaggi di tipo SUPPORT_MSG. Il secondo criterio su `source_id`
--    risolve i pari merito: senza, un ticket con due risposte nello stesso
--    istante avrebbe due presa-in-carico e i conteggi si gonfierebbero.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_presa_carico` AS
SELECT
    m.`ticket_code`                          AS ticket,
    m.`author_name`                          AS tecnico,
    m.`author_id`                            AS tecnico_id,
    m.`received_at`                          AS prima_risposta,
    m.`queue_name`                           AS coda
FROM `cm_sd_messages` m
JOIN (
    SELECT `ticket_code`, MIN(`received_at`) AS `primo`
      FROM `cm_sd_messages`
     WHERE `msg_type` = 'SUPPORT_MSG' AND `received_at` IS NOT NULL
     GROUP BY `ticket_code`
) p ON p.`ticket_code` = m.`ticket_code` AND p.`primo` = m.`received_at`
WHERE m.`msg_type` = 'SUPPORT_MSG'
  AND m.`source_id` = (
      SELECT MIN(y.`source_id`) FROM `cm_sd_messages` y
       WHERE y.`ticket_code` = m.`ticket_code`
         AND y.`msg_type` = 'SUPPORT_MSG'
         AND y.`received_at` = m.`received_at`);

-- -----------------------------------------------------------------------------
-- 2. Scheda del singolo componente.
--
--    Due gruppi di misure che non vanno confusi:
--      attivita'  quanto ha scritto e su quanti ticket e' intervenuto
--      esito      che fine hanno fatto i ticket che ha preso in carico
--
--    Il secondo gruppo e' attribuibile, il primo no: intervenire su un ticket
--    non significa esserne responsabile.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_scheda_tecnico` AS
SELECT
    a.`tecnico`,
    a.`livello`,
    a.`sotto_unita`,
    a.`messaggi`,
    a.`risposte`,
    a.`note`,
    CASE WHEN a.`note` > 0 THEN ROUND(a.`risposte` / a.`note`, 1) END AS rapporto_risposte_note,
    a.`ticket_toccati`,
    a.`code`,
    a.`giorni_attivi`,
    CASE WHEN a.`giorni_attivi` > 0
         THEN ROUND(a.`messaggi` / a.`giorni_attivi`, 1) END           AS messaggi_al_giorno,
    a.`dal`, a.`al`,
    COALESCE(e.`presi_in_carico`, 0)                                   AS presi_in_carico,
    COALESCE(e.`risolti`, 0)                                           AS risolti,
    COALESCE(e.`scalati`, 0)                                           AS scalati,
    CASE WHEN COALESCE(e.`presi_in_carico`, 0) > 0
         THEN ROUND(100 * e.`scalati` / e.`presi_in_carico`, 1) END    AS tasso_escalation_pct,
    e.`ore_prima_risposta`
FROM (
    SELECT
        m.`author_name`                       AS tecnico,
        MAX(m.`livello`)                      AS livello,
        MAX(m.`sotto_unita`)                  AS sotto_unita,
        COUNT(*)                              AS messaggi,
        SUM(m.`msg_type` = 'SUPPORT_MSG')     AS risposte,
        SUM(m.`msg_type` = 'INTERNAL_NOTE')   AS note,
        COUNT(DISTINCT m.`ticket_code`)       AS ticket_toccati,
        COUNT(DISTINCT m.`queue_name`)        AS code,
        COUNT(DISTINCT DATE(m.`received_at`)) AS giorni_attivi,
        MIN(m.`received_at`)                  AS dal,
        MAX(m.`received_at`)                  AS al
    FROM `v_cm_sd_messaggi` m
    WHERE m.`author_name` IS NOT NULL AND m.`author_name` <> ''
    GROUP BY m.`author_name`
) a
LEFT JOIN (
    SELECT
        p.`tecnico`,
        COUNT(*)                                                          AS presi_in_carico,
        SUM(t.`gestione` = 'risolto dal Service Desk')                    AS risolti,
        SUM(t.`gestione` = 'escalation di 2 livello verso specialisti')   AS scalati,
        ROUND(AVG(TIMESTAMPDIFF(MINUTE, t.`aperto_il`, p.`prima_risposta`)) / 60, 1)
                                                                          AS ore_prima_risposta
    FROM `v_cm_sd_presa_carico` p
    JOIN `v_cm_sd_ticket` t ON t.`ticket` = p.`ticket`
    GROUP BY p.`tecnico`
) e ON e.`tecnico` = a.`tecnico`;

-- -----------------------------------------------------------------------------
-- 3. Attivita' mensile del singolo, per l'andamento nella scheda
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_tecnico_mese` AS
SELECT
    m.`author_name`                        AS tecnico,
    DATE_FORMAT(m.`received_at`, '%Y-%m')  AS anno_mese,
    COUNT(*)                               AS messaggi,
    SUM(m.`msg_type` = 'SUPPORT_MSG')      AS risposte,
    SUM(m.`msg_type` = 'INTERNAL_NOTE')    AS note,
    COUNT(DISTINCT m.`ticket_code`)        AS ticket
FROM `v_cm_sd_messaggi` m
WHERE m.`author_name` IS NOT NULL AND m.`author_name` <> ''
  AND m.`received_at` IS NOT NULL
GROUP BY m.`author_name`, anno_mese;

-- -----------------------------------------------------------------------------
-- 4. Code presidiate dal singolo, con la quota sul totale della coda
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_tecnico_coda` AS
SELECT
    m.`author_name`                    AS tecnico,
    COALESCE(m.`queue_name`, '(nessuna)') AS coda,
    COUNT(*)                           AS messaggi,
    COUNT(DISTINCT m.`ticket_code`)    AS ticket
FROM `v_cm_sd_messaggi` m
WHERE m.`author_name` IS NOT NULL AND m.`author_name` <> ''
GROUP BY m.`author_name`, coda;

