-- ════════════════════════════════════════════════════════════════
-- v1.8.87 — Code, moduli di intervento e tipologia di contratto
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Il ponte fra il nome nei ticket e quello nei moduli.
--
--    Vista e non colonna: l'inversione e' una caratteristica dei dati sorgente,
--    e materializzarla richiederebbe di mantenerla allineata a ogni
--    sincronizzazione.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_nome_moduli` AS
SELECT DISTINCT
    t.`nome`                                        AS nome_ticket,
    r.`technician_raw`                              AS nome_moduli
FROM `v_cm_sd_team` t
JOIN `cm_intervention_reports` r
  ON r.`technician_raw` = t.`nome` OR r.`technician_raw` = t.`nome_invertito`;

-- -----------------------------------------------------------------------------
-- 2. Ore dei moduli per componente e modello contrattuale.
--
--    `has_revenue` distingue le commesse che producono ricavo da quelle interne:
--    e' la stessa classificazione della v1.8.58, riusata invece di ricostruita.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_moduli_contratto` AS
SELECT
    b.`nome_ticket`                                 AS tecnico,
    COALESCE(cm.`label`, p.`service_line`, '(nessuna linea)') AS contratto,
    COALESCE(cm.`model`, 'da_classificare')         AS modello,
    COALESCE(cm.`has_revenue`, 1)                   AS ha_ricavo,
    p.`service_line`                                AS linea,
    COUNT(*)                                        AS moduli,
    ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2)  AS ore,
    ROUND(SUM(COALESCE(r.`extra_hours`, 0)), 2)     AS ore_extra,
    COUNT(DISTINCT r.`project_code`)                AS commesse,
    MIN(r.`report_date`)                            AS dal,
    MAX(r.`report_date`)                            AS al
FROM `cm_intervention_reports` r
JOIN `v_cm_sd_nome_moduli` b ON b.`nome_moduli` = r.`technician_raw`
LEFT JOIN `cm_projects` p        ON p.`id` = r.`project_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
GROUP BY b.`nome_ticket`, contratto, modello, ha_ricavo, p.`service_line`;

-- -----------------------------------------------------------------------------
-- 3. Riepilogo per componente: ticket e moduli affiancati.
--
--    Le due attivita' NON si sommano: un ticket puo' generare un modulo di
--    intervento, e contarli insieme conterebbe lo stesso lavoro due volte. Sono
--    esposte come colonne distinte.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_operativita` AS
SELECT
    s.`tecnico`,
    s.`livello`,
    s.`sotto_unita`,
    s.`presi_in_carico`,
    s.`risolti`,
    s.`scalati`,
    s.`tasso_escalation_pct`,
    s.`ore_prima_risposta`,
    s.`messaggi`,
    s.`code`                                        AS code_ticket,
    COALESCE(m.`moduli`, 0)                         AS moduli_intervento,
    ROUND(COALESCE(m.`ore`, 0), 2)                  AS ore_moduli,
    ROUND(COALESCE(m.`ore_ricavo`, 0), 2)           AS ore_a_ricavo,
    ROUND(COALESCE(m.`ore`, 0) - COALESCE(m.`ore_ricavo`, 0), 2) AS ore_interne,
    CASE WHEN COALESCE(m.`ore`, 0) > 0
         THEN ROUND(100 * COALESCE(m.`ore_ricavo`, 0) / m.`ore`, 1) END AS pct_a_ricavo,
    COALESCE(m.`commesse`, 0)                       AS commesse,
    COALESCE(m.`modelli`, 0)                        AS modelli_contratto
FROM `v_cm_sd_scheda_tecnico` s
LEFT JOIN (
    SELECT `tecnico`,
           SUM(`moduli`)                                          AS moduli,
           SUM(`ore`)                                             AS ore,
           SUM(CASE WHEN `ha_ricavo` = 1 THEN `ore` ELSE 0 END)   AS ore_ricavo,
           SUM(`commesse`)                                        AS commesse,
           COUNT(DISTINCT `modello`)                              AS modelli
      FROM `v_cm_sd_moduli_contratto`
     GROUP BY `tecnico`
) m ON m.`tecnico` = s.`tecnico`;

-- -----------------------------------------------------------------------------
-- 4. Code seguite, con la quota sul totale della coda.
--
--    La quota dice se il tecnico presidia la coda o vi transita: 5 ticket su 800
--    e 5 su 6 sono numeri uguali con significati opposti.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_coda_dettaglio` AS
SELECT
    tc.`tecnico`,
    tc.`coda`,
    tc.`ticket`,
    tc.`messaggi`,
    tot.`ticket_coda`,
    CASE WHEN tot.`ticket_coda` > 0
         THEN ROUND(100 * tc.`ticket` / tot.`ticket_coda`, 1) END AS quota_coda_pct,
    COALESCE(pc.`presi`, 0)                          AS presi_in_carico
FROM `v_cm_sd_tecnico_coda` tc
LEFT JOIN (
    SELECT COALESCE(`queue_name`, '(nessuna)') AS coda,
           COUNT(DISTINCT `ticket_code`)       AS ticket_coda
      FROM `cm_sd_messages` GROUP BY coda
) tot ON tot.`coda` = tc.`coda`
LEFT JOIN (
    SELECT `tecnico`, COALESCE(`coda`, '(nessuna)') AS coda, COUNT(*) AS presi
      FROM `v_cm_sd_presa_carico` GROUP BY `tecnico`, coda
) pc ON pc.`tecnico` = tc.`tecnico` AND pc.`coda` = tc.`coda`;

