-- ════════════════════════════════════════════════════════════════
-- v1.8.89 — Relazione di Servizio IT: viste e distanze
-- ════════════════════════════════════════════════════════════════
--    Una riga per coppia: la distanza non cambia, e ricalcolarla a ogni
--    intervento sprecherebbe chiamate a un servizio esterno a pagamento.
--
--    `source` distingue come e' stata ottenuta: una distanza inserita a mano ha
--    un'affidabilita' diversa da una geocodificata, e chi legge deve poterlo
--    sapere.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_it_distances` (
    `id`              int(11)      NOT NULL AUTO_INCREMENT,
    `location_id`     int(11)      DEFAULT NULL COMMENT 'company_locations.id: sede di partenza',
    `location_label`  varchar(160) DEFAULT NULL,
    `client_id`       int(11)      DEFAULT NULL COMMENT 'clients.id',
    `client_label`    varchar(160) DEFAULT NULL,
    `origin_address`  varchar(300) DEFAULT NULL,
    `dest_address`    varchar(300) DEFAULT NULL,
    `km_one_way`      decimal(10,2) DEFAULT NULL COMMENT 'Distanza in km, sola andata',
    `minutes_one_way` int(11)      DEFAULT NULL,
    `source`          varchar(20)  NOT NULL DEFAULT 'manuale'
        COMMENT 'manuale, geocodifica, stimata',
    `geocoded_at`     datetime     DEFAULT NULL,
    `note`            varchar(300) DEFAULT NULL,
    `is_active`       tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`      datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`      datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_itdist_pair` (`location_id`, `client_id`),
    KEY `idx_itdist_client` (`client_id`),
    KEY `idx_itdist_source` (`source`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 1-bis. Coordinate sui clienti.
--
--    `company_locations` ha gia' `lat` e `lng` (entrambe vuote su tutte e 169 le
--    sedi). La tabella `clients` non le aveva. La geocodifica popola entrambe, e da li' la
--    distanza si calcola senza ulteriori chiamate esterne.
-- -----------------------------------------------------------------------------
ALTER TABLE `clients`
    ADD COLUMN IF NOT EXISTS `lat` decimal(10,7) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `lng` decimal(10,7) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS `geocoded_at` datetime DEFAULT NULL;

-- -----------------------------------------------------------------------------
-- 2. Coppie da geocodificare.
--
--    Elenca le combinazioni sede-cliente che compaiono nei moduli e non hanno
--    ancora una distanza. E' la lista di lavoro per la geocodifica: senza,
--    bisognerebbe interrogare un servizio esterno per ogni intervento invece che
--    una volta per coppia.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_distanze_mancanti` AS
SELECT
    e.`location_id`,
    l.`location_name`                           AS sede,
    l.`address`                                 AS indirizzo_sede,
    c.`id`                                      AS client_id,
    c.`name`                                    AS cliente,
    c.`address`                                 AS indirizzo_cliente,
    COUNT(*)                                    AS interventi,
    ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2) AS ore
FROM `cm_intervention_reports` r
JOIN `employees` e          ON e.`id` = r.`technician_id`
LEFT JOIN `company_locations` l ON l.`id` = e.`location_id`
LEFT JOIN `cm_projects` p   ON p.`id` = r.`project_id`
LEFT JOIN `clients` c       ON c.`id` = p.`client_id`
WHERE e.`location_id` IS NOT NULL
  AND c.`id` IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `cm_it_distances` d
                   WHERE d.`location_id` = e.`location_id` AND d.`client_id` = c.`id`)
GROUP BY e.`location_id`, l.`location_name`, l.`address`, c.`id`, c.`name`, c.`address`;

-- -----------------------------------------------------------------------------
-- 3. La riga elementare della relazione di servizio.
--
--    Un intervento con tutte le sue dimensioni: chi, quale linea, quale settore,
--    quando, come. E' la base di ogni aggregazione della sezione.
--
--    La FASCIA ORARIA usa la stessa espressione della v1.8.53. La MODALITA' e'
--    esclusiva e valutata in ordine di specificita': la reperibilita' prevale
--    sullo smart working, che prevale sul remoto — un intervento in reperibilita'
--    svolto da casa e' anzitutto reperibilita'.
--
--    La DURATA in mezze giornate usa 4 ore come soglia: e' la convenzione
--    dichiarata, non una proprieta' dei dati.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_servizio` AS
SELECT
    r.`id`                                      AS report_id,
    r.`report_code`                             AS modulo,
    r.`report_date`                             AS giorno,
    DATE_FORMAT(r.`report_date`, '%Y-%m')       AS anno_mese,
    r.`technician_raw`                          AS incaricato,
    r.`technician_id`                           AS employee_id,
    COALESCE(u.`name`, '(non assegnato)')       AS settore,
    COALESCE(su.`name`, '')                     AS sotto_settore,
    COALESCE(p.`service_line`, '(nessuna)')     AS linea_servizio,
    COALESCE(cm.`label`, p.`service_line`)      AS linea_label,
    COALESCE(cm.`model`, 'da_classificare')     AS modello_contratto,
    COALESCE(cm.`has_revenue`, 1)               AS ha_ricavo,
    r.`project_code`                            AS commessa,
    COALESCE(c.`name`, p.`client_raw`)          AS cliente,
    e.`location_id`,
    l.`location_name`                           AS sede_riferimento,
    ROUND(COALESCE(r.`quantity_hours`, 0), 2)   AS ore,
    ROUND(COALESCE(r.`extra_hours`, 0), 2)      AS ore_extra,
    ROUND(COALESCE(ao.`trip_hours`, 0), 2)      AS ore_viaggio,

    -- durata: mezza giornata sotto le 4 ore, giornata da 4 in su
    CASE WHEN COALESCE(r.`quantity_hours`, 0) >= 4 THEN 'giornata'
         WHEN COALESCE(r.`quantity_hours`, 0) > 0  THEN 'mezza giornata'
         ELSE 'non rilevata' END                AS durata,

    -- modalita' esclusiva, dalla piu' specifica alla piu' generica
    CASE
        WHEN COALESCE(ao.`during_availability`, 0) = 1 THEN 'reperibilita'
        WHEN COALESCE(ao.`smart_working`, 0) = 1       THEN 'smart working'
        WHEN COALESCE(ao.`from_remote`, 0) = 1         THEN 'da remoto'
        WHEN COALESCE(ao.`trip_hours`, 0) > 0          THEN 'presso cliente'
        ELSE 'in sede'
    END                                         AS modalita,

    -- fascia oraria, regola v1.8.53
    CASE
        WHEN DAYOFWEEK(r.`report_date`) IN (1, 7) THEN 'fuori orario'
        WHEN a.`date_start` IS NULL               THEN 'non rilevata'
        WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
          OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800
             THEN 'in orario'
        ELSE 'fuori orario'
    END                                         AS fascia_oraria,

    -- km: presenti solo se la coppia sede-cliente e' stata geocodificata.
    -- NULL e non zero: nessun dato e distanza nulla sono cose diverse, e
    -- confonderle produrrebbe medie sbagliate.
    d.`km_one_way`                              AS km_andata,
    CASE WHEN d.`km_one_way` IS NOT NULL THEN ROUND(d.`km_one_way` * 2, 2) END AS km_percorsi,
    d.`source`                                  AS km_origine
FROM `cm_intervention_reports` r
LEFT JOIN `cm_projects` p        ON p.`id` = r.`project_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
LEFT JOIN `employees` e          ON e.`id` = r.`technician_id`
LEFT JOIN `company_locations` l  ON l.`id` = e.`location_id`
LEFT JOIN `cm_tech_profiles` tp  ON tp.`employee_id` = r.`technician_id`
LEFT JOIN `cm_tech_units` u      ON u.`id` = tp.`unit_id`
LEFT JOIN `cm_tech_subunits` su  ON su.`id` = tp.`subunit_id`
LEFT JOIN `dgb_forms_activity` a ON a.`id` = r.`dgb_activity_id`
LEFT JOIN `dgb_forms_activity_operator` ao
       ON ao.`id_activity` = r.`dgb_activity_id` AND ao.`id_operator` = a.`id_operator`
LEFT JOIN `clients` c            ON c.`id` = p.`client_id`
LEFT JOIN `cm_it_distances` d    ON d.`location_id` = e.`location_id` AND d.`client_id` = c.`id`;

-- -----------------------------------------------------------------------------
-- 4. Scheda per incaricato e linea di servizio.
--
--    I GIORNI LAVORATI sono giorni DISTINTI, non la somma degli interventi: chi
--    fa cinque interventi in un giorno ha lavorato un giorno.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_scheda` AS
SELECT
    s.`incaricato`,
    s.`settore`,
    s.`linea_servizio`,
    s.`linea_label`,
    s.`modello_contratto`,
    s.`ha_ricavo`,
    COUNT(*)                                        AS interventi,
    COUNT(DISTINCT s.`giorno`)                      AS giorni_lavorati,
    ROUND(SUM(s.`ore`), 2)                          AS ore,
    ROUND(SUM(s.`ore_extra`), 2)                    AS ore_extra,
    ROUND(SUM(s.`ore_viaggio`), 2)                  AS ore_viaggio,
    ROUND(SUM(COALESCE(s.`km_percorsi`, 0)), 2)     AS km_percorsi,
    SUM(s.`km_percorsi` IS NULL AND s.`modalita` = 'presso cliente') AS trasferte_senza_km,
    SUM(s.`durata` = 'giornata')                    AS giornate,
    SUM(s.`durata` = 'mezza giornata')              AS mezze_giornate,
    SUM(s.`modalita` = 'reperibilita')              AS in_reperibilita,
    SUM(s.`modalita` = 'smart working')             AS in_smart_working,
    SUM(s.`modalita` = 'da remoto')                 AS da_remoto,
    SUM(s.`modalita` = 'presso cliente')            AS presso_cliente,
    SUM(s.`modalita` = 'in sede')                   AS in_sede,
    SUM(s.`fascia_oraria` = 'in orario')            AS in_orario,
    SUM(s.`fascia_oraria` = 'fuori orario')         AS fuori_orario,
    COUNT(DISTINCT s.`commessa`)                    AS commesse,
    COUNT(DISTINCT s.`cliente`)                     AS clienti,
    MIN(s.`giorno`)                                 AS dal,
    MAX(s.`giorno`)                                 AS al
FROM `v_cm_it_servizio` s
WHERE s.`incaricato` IS NOT NULL AND s.`incaricato` <> ''
GROUP BY s.`incaricato`, s.`settore`, s.`linea_servizio`, s.`linea_label`,
         s.`modello_contratto`, s.`ha_ricavo`;

