-- ════════════════════════════════════════════════════════════════
-- v1.8.91 — Ordinamento degli incaricati per cognome e nome
-- ════════════════════════════════════════════════════════════════
-- 1. Le due forme di ogni nome, con la chiave di ordinamento.
--
--    Una riga per FORMA e non per persona: entrambe le scritture devono poter
--    essere risolte, perche' le viste a valle usano l'una o l'altra a seconda
--    della fonte da cui leggono.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_nomi` AS
SELECT DISTINCT
    TRIM(CONCAT(COALESCE(`first_name`,''), ' ', COALESCE(`last_name`,''))) AS forma,
    LOWER(TRIM(CONCAT(COALESCE(`last_name`,''), ' ', COALESCE(`first_name`,'')))) AS ordina,
    TRIM(COALESCE(`last_name`,''))                                         AS cognome,
    TRIM(COALESCE(`first_name`,''))                                        AS nome
FROM `cm_professionals`
WHERE COALESCE(`first_name`,'') <> '' AND COALESCE(`last_name`,'') <> ''
UNION
SELECT DISTINCT
    TRIM(CONCAT(COALESCE(`last_name`,''), ' ', COALESCE(`first_name`,''))),
    LOWER(TRIM(CONCAT(COALESCE(`last_name`,''), ' ', COALESCE(`first_name`,'')))),
    TRIM(COALESCE(`last_name`,'')),
    TRIM(COALESCE(`first_name`,''))
FROM `cm_professionals`
WHERE COALESCE(`first_name`,'') <> '' AND COALESCE(`last_name`,'') <> ''
UNION
SELECT DISTINCT
    TRIM(CONCAT(COALESCE(e.`first_name`,''), ' ', COALESCE(e.`last_name`,''))),
    LOWER(TRIM(CONCAT(COALESCE(e.`last_name`,''), ' ', COALESCE(e.`first_name`,'')))),
    TRIM(COALESCE(e.`last_name`,'')),
    TRIM(COALESCE(e.`first_name`,''))
FROM `employees` e
WHERE COALESCE(e.`first_name`,'') <> '' AND COALESCE(e.`last_name`,'') <> ''
UNION
SELECT DISTINCT
    TRIM(CONCAT(COALESCE(e.`last_name`,''), ' ', COALESCE(e.`first_name`,''))),
    LOWER(TRIM(CONCAT(COALESCE(e.`last_name`,''), ' ', COALESCE(e.`first_name`,'')))),
    TRIM(COALESCE(e.`last_name`,'')),
    TRIM(COALESCE(e.`first_name`,''))
FROM `employees` e
WHERE COALESCE(e.`first_name`,'') <> '' AND COALESCE(e.`last_name`,'') <> '';

-- -----------------------------------------------------------------------------
-- 2. Le viste che elencano persone espongono la chiave di ordinamento.
--
--    `COALESCE(n.ordina, <forma>)`: chi non e' in anagrafica conserva la propria
--    stringa. Un ordinamento imperfetto su pochi casi e' preferibile alla loro
--    scomparsa dall'elenco.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_operatori` AS
SELECT
    m.`author_name`                         AS tecnico,
    COALESCE(n.`ordina`, LOWER(m.`author_name`)) AS ordina,
    COALESCE(n.`cognome`, '')               AS cognome,
    MAX(m.`livello`)                        AS livello,
    MAX(m.`sotto_unita`)                    AS sotto_unita,
    COUNT(*)                                AS messaggi,
    SUM(m.`msg_type` = 'SUPPORT_MSG')       AS risposte_cliente,
    SUM(m.`msg_type` = 'INTERNAL_NOTE')     AS note_interne,
    COUNT(DISTINCT m.`ticket_code`)         AS ticket_toccati,
    COUNT(DISTINCT m.`queue_name`)          AS code,
    MIN(m.`received_at`)                    AS dal,
    MAX(m.`received_at`)                    AS al
FROM `v_cm_sd_messaggi` m
LEFT JOIN `v_cm_nomi` n ON n.`forma` = m.`author_name`
WHERE m.`author_name` IS NOT NULL AND m.`author_name` <> ''
GROUP BY m.`author_name`, n.`ordina`, n.`cognome`;

CREATE OR REPLACE VIEW `v_cm_sd_scheda_tecnico` AS
SELECT
    a.`tecnico`,
    COALESCE(nm.`ordina`, LOWER(a.`tecnico`))                          AS ordina,
    a.`livello`,
    a.`sotto_unita`,
    a.`messaggi`,
    a.`risposte`,
    a.`note`,
    CASE WHEN a.`note` > 0 THEN ROUND(a.`risposte` / a.`note`, 1) END AS rapporto_risposte_note,
    a.`ticket_toccati`,
    a.`code`,
    a.`giorni_attivi`,
    CASE WHEN a.`giorni_attivi` > 0
         THEN ROUND(a.`messaggi` / a.`giorni_attivi`, 1) END           AS messaggi_al_giorno,
    a.`dal`, a.`al`,
    COALESCE(e.`presi_in_carico`, 0)                                   AS presi_in_carico,
    COALESCE(e.`risolti`, 0)                                           AS risolti,
    COALESCE(e.`scalati`, 0)                                           AS scalati,
    CASE WHEN COALESCE(e.`presi_in_carico`, 0) > 0
         THEN ROUND(100 * e.`scalati` / e.`presi_in_carico`, 1) END    AS tasso_escalation_pct,
    e.`ore_prima_risposta`
FROM (
    SELECT
        m.`author_name`                       AS tecnico,
        MAX(m.`livello`)                      AS livello,
        MAX(m.`sotto_unita`)                  AS sotto_unita,
        COUNT(*)                              AS messaggi,
        SUM(m.`msg_type` = 'SUPPORT_MSG')     AS risposte,
        SUM(m.`msg_type` = 'INTERNAL_NOTE')   AS note,
        COUNT(DISTINCT m.`ticket_code`)       AS ticket_toccati,
        COUNT(DISTINCT m.`queue_name`)        AS code,
        COUNT(DISTINCT DATE(m.`received_at`)) AS giorni_attivi,
        MIN(m.`received_at`)                  AS dal,
        MAX(m.`received_at`)                  AS al
    FROM `v_cm_sd_messaggi` m
    WHERE m.`author_name` IS NOT NULL AND m.`author_name` <> ''
    GROUP BY m.`author_name`
) a
LEFT JOIN `v_cm_nomi` nm ON nm.`forma` = a.`tecnico`
LEFT JOIN (
    SELECT
        p.`tecnico`,
        COUNT(*)                                                          AS presi_in_carico,
        SUM(t.`gestione` = 'risolto dal Service Desk')                    AS risolti,
        SUM(t.`gestione` = 'escalation di 2 livello verso specialisti')   AS scalati,
        ROUND(AVG(TIMESTAMPDIFF(MINUTE, t.`aperto_il`, p.`prima_risposta`)) / 60, 1)
                                                                          AS ore_prima_risposta
    FROM `v_cm_sd_presa_carico` p
    JOIN `v_cm_sd_ticket` t ON t.`ticket` = p.`ticket`
    GROUP BY p.`tecnico`
) e ON e.`tecnico` = a.`tecnico`;

-- -----------------------------------------------------------------------------
-- 3. La riga elementare della relazione IT porta la chiave di ordinamento.
--    Qui i nomi sono gia' "Cognome Nome", ma il join li normalizza comunque: se
--    la fonte cambiasse forma, l'ordinamento non ne risentirebbe.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_servizio` AS
SELECT
    s.*,
    COALESCE(n.`ordina`, LOWER(s.`incaricato`)) AS incaricato_ordina
FROM (
    SELECT
        r.`id`                                      AS report_id,
        r.`report_code`                             AS modulo,
        r.`report_date`                             AS giorno,
        DATE_FORMAT(r.`report_date`, '%Y-%m')       AS anno_mese,
        r.`technician_raw`                          AS incaricato,
        r.`technician_id`                           AS employee_id,
        COALESCE(u.`name`, '(non assegnato)')       AS settore,
        COALESCE(su.`name`, '')                     AS sotto_settore,
        COALESCE(p.`service_line`, '(nessuna)')     AS linea_servizio,
        COALESCE(cm.`label`, p.`service_line`)      AS linea_label,
        COALESCE(cm.`model`, 'da_classificare')     AS modello_contratto,
        COALESCE(cm.`has_revenue`, 1)               AS ha_ricavo,
        r.`project_code`                            AS commessa,
        COALESCE(c.`name`, p.`client_raw`)          AS cliente,
        e.`location_id`,
        l.`location_name`                           AS sede_riferimento,
        ROUND(COALESCE(r.`quantity_hours`, 0), 2)   AS ore,
        ROUND(COALESCE(r.`extra_hours`, 0), 2)      AS ore_extra,
        ROUND(COALESCE(ao.`trip_hours`, 0), 2)      AS ore_viaggio,
        CASE WHEN COALESCE(r.`quantity_hours`, 0) >= 4 THEN 'giornata'
             WHEN COALESCE(r.`quantity_hours`, 0) > 0  THEN 'mezza giornata'
             ELSE 'non rilevata' END                AS durata,
        CASE
            WHEN COALESCE(ao.`during_availability`, 0) = 1 THEN 'reperibilita'
            WHEN COALESCE(ao.`smart_working`, 0) = 1       THEN 'smart working'
            WHEN COALESCE(ao.`from_remote`, 0) = 1         THEN 'da remoto'
            WHEN COALESCE(ao.`trip_hours`, 0) > 0          THEN 'presso cliente'
            ELSE 'in sede'
        END                                         AS modalita,
        CASE
            WHEN DAYOFWEEK(r.`report_date`) IN (1, 7) THEN 'fuori orario'
            WHEN a.`date_start` IS NULL               THEN 'non rilevata'
            WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
              OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800
                 THEN 'in orario'
            ELSE 'fuori orario'
        END                                         AS fascia_oraria,
        d.`km_one_way`                              AS km_andata,
        CASE WHEN d.`km_one_way` IS NOT NULL THEN ROUND(d.`km_one_way` * 2, 2) END AS km_percorsi,
        d.`source`                                  AS km_origine
    FROM `cm_intervention_reports` r
    LEFT JOIN `cm_projects` p        ON p.`id` = r.`project_id`
    LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
    LEFT JOIN `employees` e          ON e.`id` = r.`technician_id`
    LEFT JOIN `company_locations` l  ON l.`id` = e.`location_id`
    LEFT JOIN `cm_tech_profiles` tp  ON tp.`employee_id` = r.`technician_id`
    LEFT JOIN `cm_tech_units` u      ON u.`id` = tp.`unit_id`
    LEFT JOIN `cm_tech_subunits` su  ON su.`id` = tp.`subunit_id`
    LEFT JOIN `dgb_forms_activity` a ON a.`id` = r.`dgb_activity_id`
    LEFT JOIN `dgb_forms_activity_operator` ao
           ON ao.`id_activity` = r.`dgb_activity_id` AND ao.`id_operator` = a.`id_operator`
    LEFT JOIN `clients` c            ON c.`id` = p.`client_id`
    LEFT JOIN `cm_it_distances` d    ON d.`location_id` = e.`location_id` AND d.`client_id` = c.`id`
) s
LEFT JOIN `v_cm_nomi` n ON n.`forma` = s.`incaricato`;

