-- ════════════════════════════════════════════════════════════════
-- v1.8.94 — Report direzionale e schede commerciale
-- ════════════════════════════════════════════════════════════════
--
--    `avanzamento_pct` e' calcolato solo se ci sono entrambe le date e la durata
--    e' positiva: una commessa senza date non ha un avanzamento pari a zero, non
--    ne ha affatto, e NULL lo dice mentre zero mentirebbe.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_dir_commessa` AS
SELECT
    r.`commessa_id`,
    r.`commessa`,
    r.`denominazione`,
    r.`cliente`,
    r.`stato`,
    r.`linea_servizio`,
    r.`modello`,
    r.`modello_label`,
    r.`ha_ricavo`,
    COALESCE(p.`commercial_ref`, '(non attribuita)')  AS agente,
    COALESCE(az.`name`, '(non attribuita)')           AS azienda,
    p.`division_code`                                 AS divisione,
    r.`start_date`,
    r.`end_date`,
    ROUND(COALESCE(r.`valore_commessa`, 0), 2)        AS valore,
    ROUND(COALESCE(p.`value_todate`, 0), 2)           AS valore_maturato,
    ROUND(COALESCE(r.`costo_consuntivato`, 0), 2)     AS costo,
    ROUND(COALESCE(r.`margine`, 0), 2)                AS margine,
    r.`margine_pct`,
    ROUND(COALESCE(r.`ore_consuntivate`, 0), 2)       AS ore,
    r.`interventi`,
    r.`costo_medio_orario`,
    r.`consumo_valore_pct`,
    r.`allerta`,
    r.`sforamento_critico`,

    -- avanzamento temporale: NULL se le date mancano o la durata non e' positiva
    CASE
        WHEN r.`start_date` IS NULL OR r.`end_date` IS NULL THEN NULL
        WHEN DATEDIFF(r.`end_date`, r.`start_date`) <= 0    THEN NULL
        ELSE LEAST(100, GREATEST(0, ROUND(
             100 * DATEDIFF(LEAST(CURDATE(), r.`end_date`), r.`start_date`)
             / DATEDIFF(r.`end_date`, r.`start_date`), 1)))
    END                                               AS avanzamento_pct,

    -- divergenza fra consumo e avanzamento: il numero su cui ordinare il rischio
    CASE
        WHEN r.`start_date` IS NULL OR r.`end_date` IS NULL THEN NULL
        WHEN DATEDIFF(r.`end_date`, r.`start_date`) <= 0    THEN NULL
        WHEN r.`consumo_valore_pct` IS NULL                 THEN NULL
        ELSE ROUND(r.`consumo_valore_pct` - LEAST(100, GREATEST(0,
             100 * DATEDIFF(LEAST(CURDATE(), r.`end_date`), r.`start_date`)
             / DATEDIFF(r.`end_date`, r.`start_date`))), 1)
    END                                               AS divergenza_pct,

    CASE WHEN r.`end_date` IS NOT NULL
         THEN DATEDIFF(r.`end_date`, CURDATE()) END   AS giorni_a_scadenza,

    (SELECT MAX(ir.`report_date`) FROM `cm_intervention_reports` ir
      WHERE ir.`project_id` = r.`commessa_id`)        AS ultimo_intervento,
    (SELECT DATEDIFF(CURDATE(), MAX(ir.`report_date`)) FROM `cm_intervention_reports` ir
      WHERE ir.`project_id` = r.`commessa_id`)        AS giorni_senza_movimenti,

    -- una commessa chiusa non ha rischi: ha una storia. Il flag separa cio' su
    -- cui si puo' ancora agire da cio' che e' concluso.
    CASE WHEN COALESCE(r.`stato`, '') IN ('Chiusa', 'Annullata', 'Persa')
         THEN 0 ELSE 1 END                            AS aperta
FROM `v_cm_redditivita_commessa` r
LEFT JOIN `cm_projects` p ON p.`id` = r.`commessa_id`
LEFT JOIN `companies` az  ON az.`id` = p.`exec_company_id`;

-- -----------------------------------------------------------------------------
-- 2. Quadro per agente commerciale.
--
--    GLI INDICATORI DI RISCHIO CONTANO SOLO LE COMMESSE APERTE.
--
--    Sui dati, 274 delle 490 commesse sforate sono CHIUSE, e 337 delle 505
--    "ferme da 90 giorni" sono chiuse — sono ferme perche' concluse.
--
--    Contarle produce un quadro allarmante e inutilizzabile: il 46% del
--    portafoglio in sforamento, di cui piu' della meta' e' storia su cui non si
--    puo' piu' intervenire.
--
--    Il rischio riguarda cio' su cui si puo' ancora agire. I valori economici
--    invece comprendono tutto, perche' il margine di una commessa chiusa e'
--    realizzato e va nel totale.
--
--    Il margine e le percentuali si calcolano SOLO sulle commesse a ricavo. Le
--    ore delle interne restano esposte a parte: sono capacita' impiegata e vanno
--    viste, ma non entrano nel rendimento.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_dir_agente` AS
SELECT
    `agente`,
    COUNT(*)                                                     AS commesse,
    SUM(`ha_ricavo` = 1)                                         AS commesse_a_ricavo,
    SUM(`ha_ricavo` = 0)                                         AS commesse_interne,
    COUNT(DISTINCT `cliente`)                                    AS clienti,
    ROUND(SUM(CASE WHEN `ha_ricavo` = 1 THEN `valore` ELSE 0 END), 2)  AS valore,
    ROUND(SUM(CASE WHEN `ha_ricavo` = 1 THEN `costo`  ELSE 0 END), 2)  AS costo,
    ROUND(SUM(CASE WHEN `ha_ricavo` = 1 THEN `margine` ELSE 0 END), 2) AS margine,
    CASE WHEN SUM(CASE WHEN `ha_ricavo` = 1 THEN `valore` ELSE 0 END) > 0
         THEN ROUND(100 * SUM(CASE WHEN `ha_ricavo` = 1 THEN `margine` ELSE 0 END)
                  / SUM(CASE WHEN `ha_ricavo` = 1 THEN `valore` ELSE 0 END), 1) END AS margine_pct,
    ROUND(SUM(`ore`), 2)                                         AS ore,
    ROUND(SUM(CASE WHEN `ha_ricavo` = 0 THEN `ore` ELSE 0 END), 2) AS ore_interne,
    SUM(`interventi`)                                            AS interventi,
    SUM(`aperta` = 1)                                            AS commesse_aperte,
    SUM(`aperta` = 1 AND `sforamento_critico` = 1)               AS sforate,
    SUM(`aperta` = 1 AND `consumo_valore_pct` >= 75
                     AND `consumo_valore_pct` < 100)             AS prossime_al_limite,
    SUM(`aperta` = 1 AND `divergenza_pct` >= 20)                 AS in_divergenza,
    SUM(`aperta` = 1 AND `giorni_a_scadenza` BETWEEN 0 AND 30)   AS in_scadenza_30gg,
    SUM(`aperta` = 1 AND `giorni_senza_movimenti` > 90)          AS ferme_90gg
FROM `v_cm_dir_commessa`
GROUP BY `agente`;

-- -----------------------------------------------------------------------------
-- 3. Le commesse che richiedono attenzione, con il motivo in chiaro.
--
--    Un elenco senza il motivo costringe chi legge a ricostruirlo confrontando
--    le colonne. `motivo` lo dice, e `priorita` permette di ordinare fra motivi
--    diversi: uno sforamento pesa piu' di una scadenza a trenta giorni.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_dir_attenzione` AS
SELECT `commessa`, `denominazione`, `cliente`, `agente`, `stato`, `valore`,
       `consumo_valore_pct`, `avanzamento_pct`, `divergenza_pct`, `margine_pct`,
       `giorni_a_scadenza`, `giorni_senza_movimenti`,
       'budget sforato' AS motivo, 1 AS priorita
  FROM `v_cm_dir_commessa` WHERE `aperta` = 1 AND `sforamento_critico` = 1
UNION ALL
SELECT `commessa`, `denominazione`, `cliente`, `agente`, `stato`, `valore`,
       `consumo_valore_pct`, `avanzamento_pct`, `divergenza_pct`, `margine_pct`,
       `giorni_a_scadenza`, `giorni_senza_movimenti`,
       'consumo in anticipo sui tempi', 2
  FROM `v_cm_dir_commessa`
 WHERE `aperta` = 1 AND `divergenza_pct` >= 20 AND COALESCE(`sforamento_critico`, 0) = 0
UNION ALL
SELECT `commessa`, `denominazione`, `cliente`, `agente`, `stato`, `valore`,
       `consumo_valore_pct`, `avanzamento_pct`, `divergenza_pct`, `margine_pct`,
       `giorni_a_scadenza`, `giorni_senza_movimenti`,
       'margine sotto il 20%', 3
  FROM `v_cm_dir_commessa`
 WHERE `aperta` = 1 AND `ha_ricavo` = 1 AND `margine_pct` IS NOT NULL AND `margine_pct` < 20
UNION ALL
SELECT `commessa`, `denominazione`, `cliente`, `agente`, `stato`, `valore`,
       `consumo_valore_pct`, `avanzamento_pct`, `divergenza_pct`, `margine_pct`,
       `giorni_a_scadenza`, `giorni_senza_movimenti`,
       'in scadenza entro 30 giorni', 4
  FROM `v_cm_dir_commessa` WHERE `aperta` = 1 AND `giorni_a_scadenza` BETWEEN 0 AND 30
UNION ALL
SELECT `commessa`, `denominazione`, `cliente`, `agente`, `stato`, `valore`,
       `consumo_valore_pct`, `avanzamento_pct`, `divergenza_pct`, `margine_pct`,
       `giorni_a_scadenza`, `giorni_senza_movimenti`,
       'nessun movimento da oltre 90 giorni', 5
  FROM `v_cm_dir_commessa`
 WHERE `aperta` = 1 AND `giorni_senza_movimenti` > 90;

-- -----------------------------------------------------------------------------
-- 4. Andamento mensile del portafoglio
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_dir_andamento` AS
SELECT
    DATE_FORMAT(ir.`report_date`, '%Y-%m')           AS anno_mese,
    COALESCE(p.`commercial_ref`, '(non attribuita)') AS agente,
    COUNT(DISTINCT ir.`project_id`)                  AS commesse_movimentate,
    COUNT(*)                                         AS interventi,
    ROUND(SUM(COALESCE(ir.`quantity_hours`, 0)), 2)  AS ore,
    ROUND(SUM(COALESCE(ir.`company_cost_import`, 0)), 2) AS costo
FROM `cm_intervention_reports` ir
JOIN `cm_projects` p ON p.`id` = ir.`project_id`
WHERE ir.`report_date` IS NOT NULL
GROUP BY anno_mese, agente;

