VALUES
    ('app_version',    '1.8.94', 'Versione applicazione'),
    ('schema_version', '1.8.94', 'Versione schema database'),
    ('release_label',  '1.8.94', 'Etichetta release mostrata in footer')
ON DUPLICATE KEY UPDATE
    `setting_value` = VALUES(`setting_value`);

SET FOREIGN_KEY_CHECKS=1;

-- ════════════════════════════════════════════════════════════════
-- v1.8.95 — Sistema di alerting sulle commesse
-- ════════════════════════════════════════════════════════════════
--
--    `threshold_warn` e `threshold_alarm` separate: la stessa condizione ha due
--    livelli, e trattarli come due regole distinte duplicherebbe il resto della
--    configurazione.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_alert_rules` (
    `id`               int(11)      NOT NULL AUTO_INCREMENT,
    `code`             varchar(40)  NOT NULL,
    `label`            varchar(160) NOT NULL,
    `descrizione`      varchar(400) DEFAULT NULL,
    `kind`             varchar(20)  NOT NULL DEFAULT 'soglia'
        COMMENT 'soglia, anomalia, cadenzato',
    `metric`           varchar(40)  DEFAULT NULL
        COMMENT 'consumo_budget, margine, divergenza, scadenza, fermo',
    `threshold_warn`   decimal(10,2) DEFAULT NULL,
    `threshold_alarm`  decimal(10,2) DEFAULT NULL,
    `direction`        varchar(10)  NOT NULL DEFAULT 'sopra'
        COMMENT 'sopra = scatta superando, sotto = scatta scendendo',
    `to_agent`         tinyint(1)   NOT NULL DEFAULT 1
        COMMENT 'invia allagente della commessa',
    `to_director`      tinyint(1)   NOT NULL DEFAULT 1,
    `cadence`          varchar(20)  NOT NULL DEFAULT 'evento'
        COMMENT 'evento, giornaliero, settimanale, mensile',
    `cadence_day`      tinyint(4)   DEFAULT NULL COMMENT '1-7 settimanale, 1-28 mensile',
    `is_active`        tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`       datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`       datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_alert_rule_code` (`code`),
    KEY `idx_alert_rule_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. I destinatari per agente.
--
--    L'indirizzo dell'agente e la copia sono proprieta' della PERSONA, non della
--    regola: nella regola costringerebbero a duplicarla per ogni agente.
--
--    `agent_name` e non un id perche' `cm_projects.commercial_ref` e' un nome
--    testuale: non esiste un'anagrafica degli agenti a cui agganciarsi.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_alert_recipients` (
    `id`           int(11)      NOT NULL AUTO_INCREMENT,
    `agent_name`   varchar(160) NOT NULL COMMENT 'cm_projects.commercial_ref',
    `email`        varchar(190) DEFAULT NULL COMMENT 'indirizzo dellagente',
    `cc_email`     varchar(190) DEFAULT NULL COMMENT 'copia, configurabile per agente',
    `is_active`    tinyint(1)   NOT NULL DEFAULT 1,
    `note`         varchar(300) DEFAULT NULL,
    `created_at`   datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`   datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_alert_recip_agent` (`agent_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. Gli eventi rilevati.
--
--    `signature` e' l'impronta della condizione. L'unicita' su di essa e' cio'
--    che impedisce la ripetizione: un secondo rilevamento della stessa
--    situazione non crea una riga nuova.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_alert_events` (
    `id`            int(11)      NOT NULL AUTO_INCREMENT,
    `rule_code`     varchar(40)  NOT NULL,
    `project_code`  varchar(50)  DEFAULT NULL,
    `project_id`    int(11)      DEFAULT NULL,
    `agent_name`    varchar(160) DEFAULT NULL,
    `severity`      varchar(20)  NOT NULL DEFAULT 'attenzione'
        COMMENT 'attenzione, allarme, critico',
    `signature`     varchar(190) NOT NULL
        COMMENT 'regola + commessa + fascia: impedisce il reinvio a parita di condizione',
    `metric_value`  decimal(14,2) DEFAULT NULL,
    `threshold`     decimal(14,2) DEFAULT NULL,
    `message`       varchar(500) DEFAULT NULL,
    `detected_at`   datetime     NOT NULL DEFAULT current_timestamp(),
    `resolved_at`   datetime     DEFAULT NULL,
    `sent`          tinyint(1)   NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_alert_event_sig` (`signature`),
    KEY `idx_alert_event_rule` (`rule_code`),
    KEY `idx_alert_event_agent` (`agent_name`),
    KEY `idx_alert_event_sent` (`sent`, `detected_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 4. Gli invii.
--
--    Separati dagli eventi: un errore SMTP lascia l'evento rilevato e il
--    tentativo tracciato, e il reinvio non richiede di ririlevare.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_alert_sent` (
    `id`           int(11)      NOT NULL AUTO_INCREMENT,
    `event_id`     int(11)      DEFAULT NULL,
    `rule_code`    varchar(40)  DEFAULT NULL,
    `kind`         varchar(20)  NOT NULL DEFAULT 'evento'
        COMMENT 'evento oppure riepilogo cadenzato',
    `recipient`    varchar(190) NOT NULL,
    `cc`           varchar(190) DEFAULT NULL,
    `subject`      varchar(300) DEFAULT NULL,
    `events_count` int(11)      NOT NULL DEFAULT 1,
    `status`       varchar(20)  NOT NULL DEFAULT 'inviata'
        COMMENT 'inviata, errore, simulata',
    `error_msg`    varchar(500) DEFAULT NULL,
    `sent_at`      datetime     NOT NULL DEFAULT current_timestamp(),
    PRIMARY KEY (`id`),
    KEY `idx_alert_sent_event` (`event_id`),
    KEY `idx_alert_sent_date` (`sent_at`),
    KEY `idx_alert_sent_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 5. Le regole predefinite, con le soglie concordate.
--
--    `INSERT IGNORE`: una regola gia' presente conserva le soglie che
--    l'amministratore le ha dato, e un aggiornamento non le riporta ai valori di
