-- -----------------------------------------------------------------------------
-- 6. Impostazioni del canale.
--
--    L'ALIAS e' distinto da `mail_from`: le comunicazioni sulle commesse devono
--    essere riconoscibili nell'intestazione e separabili da un filtro sulla
--    casella, senza toccare il mittente delle notifiche di scadenza.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('alert_alias_email', '', 'Alias mittente per gli alert commesse. Vuoto = usa mail_from'),
    ('alert_alias_name',  'PortalManager — Commesse', 'Nome mostrato come mittente degli alert'),
    ('alert_director_email', '', 'Indirizzo del Direttore Commerciale: riceve tutti gli alert'),
    ('alert_enabled', '0', 'Alerting attivo: 0 = solo rilevazione, 1 = rilevazione e invio'),
    ('alert_dry_run', '1', 'Modalita prova: rileva e registra senza inviare'),
