ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;

-- -----------------------------------------------------------------------------
-- 7. Gli eventi da rilevare, come vista.
--
--    La rilevazione e' una query, non codice: le condizioni sono le stesse di
--    `v_cm_dir_attenzione` e devono restare allineate. Se un domani cambia la
--    definizione di "sforata", cambia in un punto e vale per il pannello e per
--    gli alert.
--
--    La FASCIA nella firma e' l'arrotondamento a decine del valore: un consumo
--    che passa da 85 a 86 resta nella fascia 80, da 89 a 91 cambia fascia e
--    genera un nuovo alert.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_alert_da_rilevare` AS
SELECT
    'budget_sforato'                                       AS rule_code,
    c.`commessa`                                           AS project_code,
    c.`commessa_id`                                        AS project_id,
    c.`agente`                                             AS agent_name,
    'critico'                                              AS severity,
    CONCAT('budget_sforato|', c.`commessa`, '|',
           FLOOR(COALESCE(c.`consumo_valore_pct`, 0) / 10) * 10) AS signature,
    ROUND(c.`consumo_valore_pct`, 2)                       AS metric_value,
    100.00                                                 AS threshold,
    CONCAT('Budget sforato: consumo al ',
           FORMAT(COALESCE(c.`consumo_valore_pct`, 0), 1), '% del contrattato') AS message
FROM `v_cm_dir_commessa` c
WHERE c.`aperta` = 1 AND c.`sforamento_critico` = 1

UNION ALL
SELECT 'budget_consumo', c.`commessa`, c.`commessa_id`, c.`agente`,
    CASE WHEN c.`consumo_valore_pct` >= 90 THEN 'allarme' ELSE 'attenzione' END,
    CONCAT('budget_consumo|', c.`commessa`, '|',
           FLOOR(COALESCE(c.`consumo_valore_pct`, 0) / 10) * 10),
    ROUND(c.`consumo_valore_pct`, 2),
    CASE WHEN c.`consumo_valore_pct` >= 90 THEN 90.00 ELSE 75.00 END,
    CONCAT('Consumo del budget al ', FORMAT(COALESCE(c.`consumo_valore_pct`, 0), 1), '%')
FROM `v_cm_dir_commessa` c
WHERE c.`aperta` = 1 AND COALESCE(c.`sforamento_critico`, 0) = 0
  AND c.`consumo_valore_pct` >= 75 AND c.`consumo_valore_pct` < 100

UNION ALL
SELECT 'margine_basso', c.`commessa`, c.`commessa_id`, c.`agente`, 'allarme',
    CONCAT('margine_basso|', c.`commessa`, '|', FLOOR(COALESCE(c.`margine_pct`, 0) / 5) * 5),
    ROUND(c.`margine_pct`, 2), 20.00,
    CONCAT('Margine al ', FORMAT(COALESCE(c.`margine_pct`, 0), 1), '%, sotto il minimo del 20%')
FROM `v_cm_dir_commessa` c
WHERE c.`aperta` = 1 AND c.`ha_ricavo` = 1
  AND c.`margine_pct` IS NOT NULL AND c.`margine_pct` < 20

UNION ALL
SELECT 'divergenza', c.`commessa`, c.`commessa_id`, c.`agente`,
    CASE WHEN c.`divergenza_pct` >= 35 THEN 'allarme' ELSE 'attenzione' END,
    CONCAT('divergenza|', c.`commessa`, '|', FLOOR(COALESCE(c.`divergenza_pct`, 0) / 10) * 10),
    ROUND(c.`divergenza_pct`, 2),
    CASE WHEN c.`divergenza_pct` >= 35 THEN 35.00 ELSE 20.00 END,
    CONCAT('Consumo in anticipo di ', FORMAT(COALESCE(c.`divergenza_pct`, 0), 1),
           ' punti sull avanzamento temporale')
FROM `v_cm_dir_commessa` c
WHERE c.`aperta` = 1 AND c.`divergenza_pct` >= 20

UNION ALL
SELECT 'scadenza', c.`commessa`, c.`commessa_id`, c.`agente`,
    CASE WHEN c.`giorni_a_scadenza` <= 7 THEN 'allarme' ELSE 'attenzione' END,
    CONCAT('scadenza|', c.`commessa`, '|',
           CASE WHEN c.`giorni_a_scadenza` <= 7 THEN '7' ELSE '30' END),
    c.`giorni_a_scadenza`,
    CASE WHEN c.`giorni_a_scadenza` <= 7 THEN 7.00 ELSE 30.00 END,
    CONCAT('Scade fra ', c.`giorni_a_scadenza`, ' giorni')
FROM `v_cm_dir_commessa` c
WHERE c.`aperta` = 1 AND c.`giorni_a_scadenza` BETWEEN 0 AND 30

UNION ALL
SELECT 'fermo', c.`commessa`, c.`commessa_id`, c.`agente`,
    CASE WHEN c.`giorni_senza_movimenti` >= 180 THEN 'allarme' ELSE 'attenzione' END,
    CONCAT('fermo|', c.`commessa`, '|',
           FLOOR(COALESCE(c.`giorni_senza_movimenti`, 0) / 90) * 90),
    c.`giorni_senza_movimenti`,
    CASE WHEN c.`giorni_senza_movimenti` >= 180 THEN 180.00 ELSE 90.00 END,
    CONCAT('Nessun intervento da ', c.`giorni_senza_movimenti`, ' giorni')
FROM `v_cm_dir_commessa` c
WHERE c.`aperta` = 1 AND c.`giorni_senza_movimenti` > 90;

-- -----------------------------------------------------------------------------
-- 8. Stato dell'alerting, per il pannello di controllo.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_alert_stato` AS
SELECT
    (SELECT COUNT(*) FROM `cm_alert_rules` WHERE `is_active` = 1)          AS regole_attive,
    (SELECT COUNT(*) FROM `v_cm_alert_da_rilevare`)                        AS da_rilevare,
    (SELECT COUNT(*) FROM `cm_alert_events` WHERE `resolved_at` IS NULL)   AS eventi_aperti,
    (SELECT COUNT(*) FROM `cm_alert_events`
      WHERE `resolved_at` IS NULL AND `sent` = 0)                          AS in_attesa_invio,
    (SELECT COUNT(*) FROM `cm_alert_sent`
      WHERE `sent_at` >= NOW() - INTERVAL 7 DAY AND `status` = 'inviata')  AS inviate_7gg,
    (SELECT COUNT(*) FROM `cm_alert_sent`
      WHERE `sent_at` >= NOW() - INTERVAL 7 DAY AND `status` = 'errore')   AS errori_7gg,
    (SELECT COUNT(*) FROM `cm_alert_recipients` WHERE `is_active` = 1)     AS destinatari,
    (SELECT COUNT(DISTINCT `agente`) FROM `v_cm_dir_commessa`
      WHERE `agente` <> '(non attribuita)')                                AS agenti_totali;

