-- ════════════════════════════════════════════════════════════════
-- v1.8.96 — Attività di Presidi
-- ════════════════════════════════════════════════════════════════
--   fissa con sostituzioni la principale sta fra il 60% e l'80%
--   rotazione              nessuno arriva al 60%
--
-- Cosi' una commessa con un titolare e qualche giorno di sostituzione resta
-- "fissa", che e' come il responsabile la considera.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Parametri della sezione.
--
--    Soglie in tabella: sono convenzioni aziendali, e cambiarle non deve
--    richiedere una release. Le linee di presidio sono un elenco perche' un
--    domani i body rental potrebbero avere una linea propria.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('presidio_linee', 'WTS-PRES',
     'Linee di servizio considerate presidio, separate da virgola. Accorpa i body rental.'),
    ('presidio_soglia_esclusivita', '80',
     'Quota minima di ore su commesse di presidio per essere classificato personale di presidio'),
    ('presidio_soglia_fissa', '80',
     'Quota della persona principale sopra la quale l allocazione e considerata fissa'),
    ('presidio_soglia_rotazione', '60',
     'Sotto questa quota della persona principale l allocazione e in rotazione'),
    ('presidio_giornata_ore', '8',
     'Ore che compongono una giornata di copertura')
ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;

-- -----------------------------------------------------------------------------
-- 2. Le commesse di presidio.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pres_commesse` AS
SELECT
    p.`id`                                          AS commessa_id,
    p.`project_code`                                AS commessa,
    p.`description`                                 AS denominazione,
    COALESCE(c.`name`, p.`client_raw`)              AS cliente,
    p.`operational_status`                          AS stato,
    p.`service_line`                                AS linea,
    COALESCE(p.`commercial_ref`, '(non attribuita)') AS agente,
    COALESCE(az.`name`, '(non attribuita)')         AS azienda,
    p.`start_date`, p.`end_date`,
    ROUND(COALESCE(p.`value_total`, 0), 2)          AS ricavo,
    ROUND(COALESCE(p.`actual_cost`, 0), 2)          AS costo_interno,
    ROUND(COALESCE(p.`value_total`, 0) - COALESCE(p.`actual_cost`, 0), 2) AS margine,
    CASE WHEN COALESCE(p.`value_total`, 0) > 0
         THEN ROUND(100 * (COALESCE(p.`value_total`, 0) - COALESCE(p.`actual_cost`, 0))
                  / p.`value_total`, 1) END         AS margine_pct,
    CASE WHEN COALESCE(p.`operational_status`,'') IN ('Chiusa','Annullata','Persa')
         THEN 0 ELSE 1 END                           AS aperta
FROM `cm_projects` p
LEFT JOIN `clients` c   ON c.`id` = p.`client_id`
LEFT JOIN `companies` az ON az.`id` = p.`exec_company_id`
WHERE FIND_IN_SET(p.`service_line`,
      (SELECT REPLACE(`setting_value`, ' ', '') FROM `app_settings`
        WHERE `setting_key` = 'presidio_linee')) > 0;

-- -----------------------------------------------------------------------------
-- 3. Le persone, con quota di esclusività e classificazione.
--
--    La quota si calcola su TUTTE le ore della persona, non solo su quelle di
--    presidio: e' il rapporto fra cio' che fa sul presidio e cio' che fa in
--    totale, ed e' quello che misura l'esclusivita'.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pres_persone` AS
SELECT
    x.`incaricato`,
    COALESCE(n.`ordina`, LOWER(x.`incaricato`))     AS ordina,
    x.`employee_id`,
    x.`unita`,
    x.`in_unita_presidio`,
    x.`ore_presidio`,
    x.`ore_totali`,
    x.`quota_pct`,
    x.`commesse_presidio`,
    x.`commesse_totali`,
    x.`giorni_presidio`,
    ROUND(x.`ore_presidio` / NULLIF((SELECT CAST(`setting_value` AS DECIMAL(10,2))
        FROM `app_settings` WHERE `setting_key` = 'presidio_giornata_ore'), 0), 1) AS giornate_presidio,
    x.`dal`, x.`al`,

    -- i due criteri restano distinti: l'unita' e' la classificazione dichiarata,
    -- la quota e' il comportamento osservato
    CASE
        WHEN x.`in_unita_presidio` = 1 AND x.`quota_pct` >= x.`soglia` THEN 'presidio confermato'
        WHEN x.`in_unita_presidio` = 0 AND x.`quota_pct` >= x.`soglia` THEN 'presidio di fatto'
        WHEN x.`in_unita_presidio` = 1 AND x.`quota_pct` <  x.`soglia` THEN 'assegnato non operante'
        ELSE 'copertura'
    END                                             AS classificazione,
    CASE WHEN x.`quota_pct` >= x.`soglia` THEN 1 ELSE 0 END AS e_presidio
FROM (
    SELECT
        r.`technician_raw`                          AS incaricato,
        MAX(r.`technician_id`)                      AS employee_id,
        COALESCE(MAX(u.`name`), '(non assegnato)')  AS unita,
        MAX(CASE WHEN u.`name` = 'Presidio' THEN 1 ELSE 0 END) AS in_unita_presidio,
        ROUND(SUM(CASE WHEN pr.`commessa_id` IS NOT NULL
                  THEN COALESCE(r.`quantity_hours`, 0) ELSE 0 END), 2) AS ore_presidio,
        ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2) AS ore_totali,
        ROUND(100 * SUM(CASE WHEN pr.`commessa_id` IS NOT NULL
                        THEN COALESCE(r.`quantity_hours`, 0) ELSE 0 END)
              / NULLIF(SUM(COALESCE(r.`quantity_hours`, 0)), 0), 1) AS quota_pct,
        COUNT(DISTINCT CASE WHEN pr.`commessa_id` IS NOT NULL THEN r.`project_code` END) AS commesse_presidio,
        COUNT(DISTINCT r.`project_code`)            AS commesse_totali,
        COUNT(DISTINCT CASE WHEN pr.`commessa_id` IS NOT NULL THEN r.`report_date` END) AS giorni_presidio,
        MIN(CASE WHEN pr.`commessa_id` IS NOT NULL THEN r.`report_date` END) AS dal,
        MAX(CASE WHEN pr.`commessa_id` IS NOT NULL THEN r.`report_date` END) AS al,
        (SELECT CAST(`setting_value` AS DECIMAL(10,2)) FROM `app_settings`
          WHERE `setting_key` = 'presidio_soglia_esclusivita') AS soglia
    FROM `cm_intervention_reports` r
    LEFT JOIN `v_cm_pres_commesse` pr ON pr.`commessa_id` = r.`project_id`
    LEFT JOIN `cm_tech_profiles` tp   ON tp.`employee_id` = r.`technician_id`
    LEFT JOIN `cm_tech_units` u       ON u.`id` = tp.`unit_id`
    WHERE r.`technician_raw` IS NOT NULL AND r.`technician_raw` <> ''
    GROUP BY r.`technician_raw`
    HAVING `ore_presidio` > 0
) x
LEFT JOIN `v_cm_nomi` n ON n.`forma` = x.`incaricato`;

-- -----------------------------------------------------------------------------
-- 4. Chi lavora su ciascuna commessa, con la propria quota.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pres_allocazioni` AS
SELECT
    pr.`commessa_id`,
    pr.`commessa`,
    pr.`cliente`,
    r.`technician_raw`                              AS incaricato,
    COALESCE(pp.`classificazione`, 'copertura')     AS classificazione,
    COALESCE(pp.`e_presidio`, 0)                    AS e_presidio,
    ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2)  AS ore,
    COUNT(DISTINCT r.`report_date`)                 AS giorni,
    COUNT(*)                                        AS interventi,
    ROUND(100 * SUM(COALESCE(r.`quantity_hours`, 0)) / NULLIF(
        (SELECT SUM(COALESCE(r2.`quantity_hours`, 0)) FROM `cm_intervention_reports` r2
          WHERE r2.`project_id` = pr.`commessa_id`), 0), 1) AS quota_commessa_pct,
    MIN(r.`report_date`)                            AS dal,
    MAX(r.`report_date`)                            AS al
FROM `cm_intervention_reports` r
JOIN `v_cm_pres_commesse` pr ON pr.`commessa_id` = r.`project_id`
LEFT JOIN `v_cm_pres_persone` pp ON pp.`incaricato` = r.`technician_raw`
WHERE r.`technician_raw` IS NOT NULL AND r.`technician_raw` <> ''
GROUP BY pr.`commessa_id`, pr.`commessa`, pr.`cliente`, r.`technician_raw`,
         pp.`classificazione`, pp.`e_presidio`;

-- -----------------------------------------------------------------------------
-- 5. La scheda della commessa: economia, allocazione e coperture.
--
--    `tipo_allocazione` guarda la quota della persona PRINCIPALE, non il numero
--    di persone: una commessa con un titolare e tre sostituzioni occasionali
--    resta "fissa", che e' come il responsabile la considera.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pres_scheda` AS
SELECT
    pr.*,
    a.`persone`,
    a.`persone_presidio`,
    a.`persone_copertura`,
    a.`ore_totali`,
    a.`ore_presidio`,
    a.`ore_copertura`,
    a.`giorni_copertura`,
    ROUND(a.`ore_copertura` / NULLIF((SELECT CAST(`setting_value` AS DECIMAL(10,2))
        FROM `app_settings` WHERE `setting_key` = 'presidio_giornata_ore'), 0), 1) AS giornate_copertura,
    a.`principale`,
    a.`quota_principale`,
    CASE
        WHEN a.`quota_principale` IS NULL THEN 'non rilevata'
        WHEN a.`quota_principale` >= (SELECT CAST(`setting_value` AS DECIMAL(10,2))
             FROM `app_settings` WHERE `setting_key` = 'presidio_soglia_fissa') THEN 'fissa'
        WHEN a.`quota_principale` >= (SELECT CAST(`setting_value` AS DECIMAL(10,2))
             FROM `app_settings` WHERE `setting_key` = 'presidio_soglia_rotazione')
             THEN 'fissa con sostituzioni'
        ELSE 'rotazione'
    END                                             AS tipo_allocazione
FROM `v_cm_pres_commesse` pr
LEFT JOIN (
    SELECT
        `commessa_id`,
        COUNT(*)                                            AS persone,
        SUM(`e_presidio` = 1)                               AS persone_presidio,
        SUM(`e_presidio` = 0)                               AS persone_copertura,
        ROUND(SUM(`ore`), 2)                                AS ore_totali,
        ROUND(SUM(CASE WHEN `e_presidio` = 1 THEN `ore` ELSE 0 END), 2) AS ore_presidio,
        ROUND(SUM(CASE WHEN `e_presidio` = 0 THEN `ore` ELSE 0 END), 2) AS ore_copertura,
        SUM(CASE WHEN `e_presidio` = 0 THEN `giorni` ELSE 0 END)        AS giorni_copertura,
        SUBSTRING_INDEX(GROUP_CONCAT(`incaricato` ORDER BY `ore` DESC), ',', 1) AS principale,
        MAX(`quota_commessa_pct`)                           AS quota_principale
    FROM `v_cm_pres_allocazioni`
    GROUP BY `commessa_id`
) a ON a.`commessa_id` = pr.`commessa_id`;

-- -----------------------------------------------------------------------------
-- 6. Il quadro complessivo.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pres_quadro` AS
SELECT
    (SELECT COUNT(*) FROM `v_cm_pres_commesse`)                            AS commesse,
    (SELECT COUNT(*) FROM `v_cm_pres_commesse` WHERE `aperta` = 1)         AS commesse_aperte,
    (SELECT ROUND(SUM(`ricavo`), 2) FROM `v_cm_pres_commesse`)             AS valore_totale,
    (SELECT ROUND(SUM(`ricavo`), 2) FROM `v_cm_pres_commesse` WHERE `aperta` = 1) AS valore_aperte,
    (SELECT ROUND(SUM(`costo_interno`), 2) FROM `v_cm_pres_commesse`)      AS costo_totale,
    (SELECT ROUND(SUM(`margine`), 2) FROM `v_cm_pres_commesse`)            AS margine_totale,
    (SELECT COUNT(*) FROM `v_cm_pres_persone` WHERE `e_presidio` = 1)      AS headcount,
    (SELECT COUNT(*) FROM `v_cm_pres_persone` WHERE `classificazione` = 'presidio confermato') AS confermati,
    (SELECT COUNT(*) FROM `v_cm_pres_persone` WHERE `classificazione` = 'presidio di fatto')   AS di_fatto,
    (SELECT COUNT(*) FROM `v_cm_pres_persone` WHERE `classificazione` = 'assegnato non operante') AS non_operanti,
    (SELECT COUNT(*) FROM `v_cm_pres_persone` WHERE `classificazione` = 'copertura')           AS coperture,
    (SELECT ROUND(SUM(`ore_presidio`), 2) FROM `v_cm_pres_persone` WHERE `e_presidio` = 1) AS ore_presidio,
    (SELECT ROUND(SUM(`ore_presidio`), 2) FROM `v_cm_pres_persone` WHERE `e_presidio` = 0) AS ore_copertura,
    (SELECT ROUND(SUM(`giornate_copertura`), 1) FROM `v_cm_pres_scheda`)   AS giornate_copertura,
    (SELECT COUNT(*) FROM `v_cm_pres_scheda` WHERE `tipo_allocazione` = 'fissa')       AS alloc_fissa,
    (SELECT COUNT(*) FROM `v_cm_pres_scheda` WHERE `tipo_allocazione` = 'fissa con sostituzioni') AS alloc_mista,
    (SELECT COUNT(*) FROM `v_cm_pres_scheda` WHERE `tipo_allocazione` = 'rotazione')   AS alloc_rotazione;

