-- ════════════════════════════════════════════════════════════════
-- v1.8.97 — Costo orario del dipendente e redditività a costo reale
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
-- 1. Parametri per esercizio.
--
--    Una riga per anno: i giorni lavorativi convenzionali e le ore per giornata
--    possono cambiare fra esercizi, e un valore unico non permetterebbe di
--    ricostruire un calcolo passato.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_cost_year_params` (
    `year`             smallint(6)   NOT NULL,
    `working_days`     smallint(6)   NOT NULL DEFAULT 220
        COMMENT 'Giorni lavorativi convenzionali dell esercizio',
    `hours_per_day`    decimal(5,2)  NOT NULL DEFAULT 8.00,
    `is_closed`        tinyint(1)    NOT NULL DEFAULT 0
        COMMENT '1 = esercizio chiuso, i costi non vanno piu ricalcolati',
    `note`             varchar(300)  DEFAULT NULL,
    `created_at`       datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`       datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `cm_cost_year_params` (`year`, `working_days`, `hours_per_day`, `note`)
VALUES
    (2023, 220, 8.00, 'Valore convenzionale predefinito'),
    (2024, 220, 8.00, 'Valore convenzionale predefinito'),
    (2025, 220, 8.00, 'Valore convenzionale predefinito'),
    (2026, 220, 8.00, 'Valore convenzionale predefinito');

-- -----------------------------------------------------------------------------
-- 2. Il costo consolidato per dipendente e anno.
--
--    Popolata da `CostModel`, non da una formula riscritta qui: due
--    implementazioni della stessa regola divergono, e il numero nella scheda del
--    dipendente e quello nella redditivita' devono essere lo stesso.
--
--    `computed_at` e `source` dicono quando e come e' stato prodotto: un valore
--    consolidato sei mesi fa e uno di ieri hanno affidabilita' diversa quando i
--    parametri sono cambiati nel frattempo.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_employee_cost_year` (
    `id`               int(11)       NOT NULL AUTO_INCREMENT,
    `employee_id`      int(11)       NOT NULL,
    `year`             smallint(6)   NOT NULL,
    `tot_costo_tab`    decimal(14,2) DEFAULT NULL COMMENT 'Costo aziendale annuo',
    `totale_pre_overhead` decimal(14,2) DEFAULT NULL,
    `valore_fte`       decimal(14,2) DEFAULT NULL,
    `totale_fte_ca`    decimal(14,2) DEFAULT NULL,
    `ral`              decimal(14,2) DEFAULT NULL,
    `part_time_pct`    decimal(6,2)  DEFAULT NULL,
    `working_days`     smallint(6)   DEFAULT NULL COMMENT 'Copiati dai parametri dell anno',
    `hours_per_day`    decimal(5,2)  DEFAULT NULL,
    `costo_giorno`     decimal(14,4) DEFAULT NULL,
    `costo_ora`        decimal(14,4) DEFAULT NULL,
    `source`           varchar(20)   NOT NULL DEFAULT 'CostModel',
    `computed_at`      datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`       datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_emp_cost_year` (`employee_id`, `year`),
    KEY `idx_emp_cost_year` (`year`),
    KEY `idx_emp_cost_ora` (`costo_ora`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. Il costo applicabile a un intervento, con ripiego sull'esercizio
--    precedente.
--
--    `esercizio_usato` e' l'anno da cui viene effettivamente il costo, che puo'
--    essere diverso dall'anno dell'intervento. `costo_origine` lo qualifica:
--    "consolidato" se coincidono, "stimato da <anno>" altrimenti.
--
--    Chi legge un margine deve poter sapere se il costo sottostante e' quello
--    dell'esercizio o una stima riportata.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_costo_dipendente_anno` AS
SELECT
    e.`id`                                          AS employee_id,
    a.`year`                                        AS anno,
    COALESCE(c.`year`, cp.`year`)                   AS esercizio_usato,
    COALESCE(c.`tot_costo_tab`, cp.`tot_costo_tab`) AS tot_costo_tab,
    COALESCE(c.`working_days`, cp.`working_days`,
             (SELECT `working_days` FROM `cm_cost_year_params` p WHERE p.`year` = a.`year`),
             220)                                   AS giorni_lavorativi,
    COALESCE(c.`hours_per_day`, cp.`hours_per_day`, 8) AS ore_giorno,
    COALESCE(c.`costo_ora`, cp.`costo_ora`)         AS costo_ora,
    COALESCE(c.`costo_giorno`, cp.`costo_giorno`)   AS costo_giorno,
    CASE
        WHEN c.`year` IS NOT NULL  THEN 'consolidato'
        WHEN cp.`year` IS NOT NULL THEN CONCAT('stimato da ', cp.`year`)
        ELSE 'non disponibile'
    END                                             AS costo_origine
FROM `employees` e
CROSS JOIN (SELECT `year` FROM `cm_cost_year_params`) a
LEFT JOIN `cm_employee_cost_year` c
       ON c.`employee_id` = e.`id` AND c.`year` = a.`year`
-- ripiego: l'ultimo esercizio consolidato PRECEDENTE a quello richiesto
LEFT JOIN `cm_employee_cost_year` cp
       ON cp.`employee_id` = e.`id`
      AND cp.`year` = (SELECT MAX(x.`year`) FROM `cm_employee_cost_year` x
                        WHERE x.`employee_id` = e.`id` AND x.`year` < a.`year`
                          AND x.`tot_costo_tab` IS NOT NULL)
      AND c.`year` IS NULL;

-- -----------------------------------------------------------------------------
-- 4. Il costo di ogni intervento.
--
--    Il costo si applica per l'ANNO DELL'INTERVENTO, non per l'anno corrente:
--    e' cio' che rende stabili i margini storici.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_costo_intervento` AS
SELECT
    r.`id`                                          AS report_id,
    r.`project_id`,
    r.`project_code`                                AS commessa,
    r.`report_date`                                 AS giorno,
    YEAR(r.`report_date`)                           AS anno,
    r.`technician_id`                               AS employee_id,
    r.`technician_raw`                              AS incaricato,
    ROUND(COALESCE(r.`quantity_hours`, 0), 2)       AS ore,
    cd.`costo_ora`,
    cd.`esercizio_usato`,
    cd.`costo_origine`,
    ROUND(COALESCE(r.`quantity_hours`, 0) * COALESCE(cd.`costo_ora`, 0), 2) AS costo_calcolato,
    ROUND(COALESCE(r.`company_cost_import`, 0), 2)  AS costo_importato
FROM `cm_intervention_reports` r
LEFT JOIN `v_cm_costo_dipendente_anno` cd
       ON cd.`employee_id` = r.`technician_id` AND cd.`anno` = YEAR(r.`report_date`)
WHERE r.`report_date` IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 5. Redditività per commessa sul costo aziendale calcolato.
--
--    Due grandezze distinte, esposte affiancate:
--
--      COSTO AZIENDALE   quanto costa all'azienda erogare il servizio
--      COSTO DI VENDITA  quanto e' stato addebitato al cliente
--
--    Il margine sul costo aziendale e' quello vero. Quello sul costo importato e'
--    la marginalita' come la vede il gestionale. Divergono quando gli addebiti
--    non riflettono il costo reale, ed e' proprio quella divergenza il dato
--    interessante: `scarto_costo_pct` la misura.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_redditivita_costo_reale` AS
SELECT
    p.`id`                                          AS commessa_id,
    p.`project_code`                                AS commessa,
    p.`description`                                 AS denominazione,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS linea,
    COALESCE(cm.`label`, p.`service_line`)          AS linea_label,
    COALESCE(cm.`has_revenue`, 1)                   AS ha_ricavo,
    COALESCE(p.`commercial_ref`, '(non attribuita)') AS agente,
    p.`operational_status`                          AS stato,
    ROUND(COALESCE(p.`value_total`, 0), 2)          AS ricavo,
    ROUND(SUM(ci.`ore`), 2)                         AS ore,
    ROUND(SUM(ci.`costo_calcolato`), 2)             AS costo_aziendale,
    ROUND(SUM(ci.`costo_importato`), 2)             AS costo_vendita,
    ROUND(COALESCE(p.`value_total`, 0) - SUM(ci.`costo_calcolato`), 2) AS margine_aziendale,
    CASE WHEN COALESCE(p.`value_total`, 0) > 0
         THEN ROUND(100 * (COALESCE(p.`value_total`, 0) - SUM(ci.`costo_calcolato`))
                  / p.`value_total`, 1) END         AS margine_aziendale_pct,
    ROUND(COALESCE(p.`value_total`, 0) - SUM(ci.`costo_importato`), 2) AS margine_vendita,
    CASE WHEN COALESCE(p.`value_total`, 0) > 0
         THEN ROUND(100 * (COALESCE(p.`value_total`, 0) - SUM(ci.`costo_importato`))
                  / p.`value_total`, 1) END         AS margine_vendita_pct,
    -- divergenza fra costo reale e addebitato: se e' alta, gli addebiti non
    -- riflettono il costo di erogazione
    CASE WHEN SUM(ci.`costo_calcolato`) > 0
         THEN ROUND(100 * (SUM(ci.`costo_importato`) - SUM(ci.`costo_calcolato`))
                  / SUM(ci.`costo_calcolato`), 1) END AS scarto_costo_pct,
    CASE WHEN SUM(ci.`ore`) > 0
         THEN ROUND(SUM(ci.`costo_calcolato`) / SUM(ci.`ore`), 2) END AS costo_orario_medio,
    COUNT(DISTINCT ci.`employee_id`)                AS persone,
    SUM(ci.`costo_origine` = 'consolidato')         AS righe_consolidate,
    COUNT(*)                                        AS righe,
    ROUND(100 * SUM(ci.`costo_origine` = 'consolidato') / NULLIF(COUNT(*), 0), 1) AS copertura_pct
FROM `cm_projects` p
JOIN `v_cm_costo_intervento` ci ON ci.`project_id` = p.`id`
LEFT JOIN `clients` cl           ON cl.`id` = p.`client_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
GROUP BY p.`id`, p.`project_code`, p.`description`, cliente, p.`service_line`,
         linea_label, ha_ricavo, agente, p.`operational_status`, p.`value_total`;

-- -----------------------------------------------------------------------------
-- 6. Stato del consolidamento, per il pannello.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_costo_stato` AS
SELECT
    (SELECT COUNT(*) FROM `employees`)                                      AS dipendenti,
    (SELECT COUNT(DISTINCT `employee_id`) FROM `cm_employee_cost_year`
      WHERE `tot_costo_tab` IS NOT NULL)                                    AS con_costo,
    (SELECT COUNT(*) FROM `cm_employee_cost_year` WHERE `tot_costo_tab` IS NOT NULL) AS righe_costo,
    (SELECT GROUP_CONCAT(DISTINCT `year` ORDER BY `year`) FROM `cm_employee_cost_year`
      WHERE `tot_costo_tab` IS NOT NULL)                                    AS esercizi,
    (SELECT MAX(`computed_at`) FROM `cm_employee_cost_year`)                AS ultimo_calcolo,
    (SELECT COUNT(*) FROM `v_cm_costo_intervento` WHERE `costo_origine` = 'consolidato') AS interventi_consolidati,
    (SELECT COUNT(*) FROM `v_cm_costo_intervento` WHERE `costo_origine` LIKE 'stimato%')  AS interventi_stimati,
    (SELECT COUNT(*) FROM `v_cm_costo_intervento` WHERE `costo_origine` = 'non disponibile') AS interventi_scoperti;

