-- ════════════════════════════════════════════════════════════════
-- v1.8.99 — Tabella di riferimento del calcolo economico
-- ════════════════════════════════════════════════════════════════
-- -----------------------------------------------------------------------------
-- 1. La tabella di riferimento.
--
--    Riproduce il documento aziendale riga per riga. `formula` e `cost_basis`
--    sono codici, non testo libero: le viste li interpretano, e un refuso in una
--    descrizione non deve cambiare un calcolo.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_calc_reference` (
    `id`             int(11)      NOT NULL AUTO_INCREMENT,
    `descrizione`    varchar(160) NOT NULL COMMENT 'Descrizione tipo contratto, dal documento',
    `code_doc`       varchar(40)  DEFAULT NULL COMMENT 'Codice contratto come nel documento',
    `service_line`   varchar(60)  DEFAULT NULL COMMENT 'Linea di servizio nei dati, se diversa',
    `formula`        varchar(30)  NOT NULL
        COMMENT 'A = valore-consuntivato, B = valore-costi, C = valore+consuntivato-costi',
    `formula_desc`   varchar(200) DEFAULT NULL COMMENT 'Dettaglio calcolo, testo del documento',
    `cost_basis`     varchar(30)  NOT NULL DEFAULT 'fascia'
        COMMENT 'costi_a_zero, fascia, full_cost',
    `cost_desc`      varchar(120) DEFAULT NULL COMMENT 'Base calcolo, testo del documento',
    `is_dynamic`     tinyint(1)   NOT NULL DEFAULT 0
        COMMENT '1 = commessa aperta di volta in volta, senza codice fisso',
    `sort_order`     int(11)      NOT NULL DEFAULT 0,
    `is_active`      tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`     datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`     datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_calcref_desc` (`descrizione`),
    KEY `idx_calcref_line` (`service_line`),
    KEY `idx_calcref_code` (`code_doc`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

