-- -----------------------------------------------------------------------------
-- 4. La vista di risoluzione, allineata.
--
--    Il ripiego sul gruppo dinamico resta come rete per eventuali linee NV_
--    future, ma i sei codici ora hanno una riga propria e non ne hanno bisogno.
--
--    `is_legacy = 0 AND is_active = 1` esclude i tipi in dismissione: una
--    commessa su linea NIS-* ricade sulla predefinita e viene dichiarata come
--    tale, invece di ricevere una regola che l'azienda sta abbandonando.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_calc_regola` AS
SELECT
    p.`id`                                          AS commessa_id,
    p.`project_code`                                AS commessa,
    p.`service_line`                                AS linea,
    COALESCE(r1.`descrizione`, r2.`descrizione`, rd.`descrizione`) AS tipo_contratto,
    COALESCE(r1.`formula`, r2.`formula`, rd.`formula`, 'B')        AS formula,
    COALESCE(r1.`formula_desc`, r2.`formula_desc`, rd.`formula_desc`,
             'Valore a oggi meno costi consuntivati e storni')     AS formula_desc,
    COALESCE(r1.`cost_basis`, r2.`cost_basis`, rd.`cost_basis`, 'fascia') AS cost_basis,
    COALESCE(r1.`cost_desc`, r2.`cost_desc`, rd.`cost_desc`,
             'Fascia di costo interna')             AS cost_desc,
    COALESCE(r1.`margin_type`, r2.`margin_type`, rd.`margin_type`) AS margin_type,
    COALESCE(r1.`tm_cost_type`, r2.`tm_cost_type`, rd.`tm_cost_type`) AS tm_cost_type,
    CASE
        WHEN r1.`id` IS NOT NULL THEN 'linea'
        WHEN r2.`id` IS NOT NULL THEN 'codice documento'
        WHEN rd.`id` IS NOT NULL THEN 'gruppo dinamico'
        ELSE 'predefinita'
    END                                             AS regola_origine
FROM `cm_projects` p
LEFT JOIN `cm_calc_reference` r1
       ON r1.`service_line` = p.`service_line` AND r1.`is_active` = 1 AND r1.`is_legacy` = 0
LEFT JOIN `cm_calc_reference` r2
       ON r2.`code_doc` = p.`service_line` AND r2.`is_active` = 1 AND r2.`is_legacy` = 0
      AND r1.`id` IS NULL
LEFT JOIN `cm_calc_reference` rd
       ON rd.`descrizione` = 'Nval - Attivita Interne'
      AND p.`service_line` LIKE 'NV\_%'
      AND r1.`id` IS NULL AND r2.`id` IS NULL;

-- -----------------------------------------------------------------------------
-- 5. Controllo della mappa fra codici gestionale e formule.
--
--    Se il gestionale introducesse un `margin_type` nuovo, o se una riga avesse
--    formula e codice incoerenti, questa vista lo mostra. Senza, l'incoerenza
--    resterebbe invisibile fino al primo margine sbagliato.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_calc_mappa` AS
SELECT
    `margin_type`,
    `formula`,
    `tm_cost_type`,
    `cost_basis`,
    COUNT(*)                                        AS righe,
    GROUP_CONCAT(`code_doc` ORDER BY `code_doc` SEPARATOR ', ') AS codici,
    CASE
        WHEN `margin_type` = 'F' AND `formula` <> 'A' THEN 'incoerente'
        WHEN `margin_type` = 'V' AND `formula` <> 'B' THEN 'incoerente'
        WHEN `margin_type` = 'D' AND `formula` <> 'C' THEN 'incoerente'
        WHEN `margin_type` = 'T' AND `formula` <> 'D' THEN 'incoerente'
        WHEN `tm_cost_type` = 'ZC' AND `cost_basis` <> 'costi_a_zero' THEN 'incoerente'
        WHEN `tm_cost_type` = 'CR' AND `cost_basis` <> 'fascia' THEN 'incoerente'
        WHEN `tm_cost_type` = 'FC' AND `cost_basis` <> 'full_cost' THEN 'incoerente'
        WHEN `margin_type` IS NULL THEN 'senza codice gestionale'
        ELSE 'coerente'
    END                                             AS esito
FROM `cm_calc_reference`
WHERE `is_active` = 1
GROUP BY `margin_type`, `formula`, `tm_cost_type`, `cost_basis`;

