-- ════════════════════════════════════════════════════════════════
-- v1.9.1 — Applicazione delle formule di calcolo
-- ════════════════════════════════════════════════════════════════
-- decisione da prendere guardando i numeri, non un effetto collaterale di un
-- aggiornamento.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Il margine per commessa secondo la formula di competenza.
--
--    `storni` non ha una colonna dedicata in `cm_projects`: il documento cita
--    "costi consuntivati e storni" come un'unica grandezza, e `actual_cost` e'
--    il consuntivo che il gestionale ha gia' consolidato. Se gli storni fossero
--    esposti separatamente andrebbero sottratti qui.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_margine_formula` AS
SELECT
    p.`id`                                          AS commessa_id,
    p.`project_code`                                AS commessa,
    p.`description`                                 AS denominazione,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS linea,
    r.`tipo_contratto`,
    r.`formula`,
    r.`formula_desc`,
    r.`cost_basis`,
    r.`margin_type`,
    r.`regola_origine`,
    COALESCE(p.`commercial_ref`, '(non attribuita)') AS agente,
    p.`operational_status`                          AS stato,
    ROUND(COALESCE(p.`value_total`, 0), 2)          AS valore_oggi,
    ROUND(COALESCE(p.`value_todate`, 0), 2)         AS valore_consuntivato,
    ROUND(COALESCE(p.`actual_cost`, 0), 2)          AS costi_consuntivati,

    -- il margine secondo la formula di competenza
    ROUND(CASE r.`formula`
        WHEN 'A' THEN COALESCE(p.`value_total`, 0) - COALESCE(p.`value_todate`, 0)
        WHEN 'C' THEN COALESCE(p.`value_total`, 0) + COALESCE(p.`value_todate`, 0)
                    - CASE WHEN r.`cost_basis` = 'costi_a_zero' THEN 0
                           ELSE COALESCE(p.`actual_cost`, 0) END
        WHEN 'D' THEN COALESCE(p.`value_todate`, 0) - COALESCE(p.`actual_cost`, 0)
        ELSE          COALESCE(p.`value_total`, 0)
                    - CASE WHEN r.`cost_basis` = 'costi_a_zero' THEN 0
                           ELSE COALESCE(p.`actual_cost`, 0) END
    END, 2)                                         AS margine,

    -- il calcolo precedente, uguale per tutte le linee
    ROUND(COALESCE(p.`value_total`, 0) - COALESCE(p.`actual_cost`, 0), 2) AS margine_attuale,

    ROUND(CASE r.`formula`
        WHEN 'A' THEN COALESCE(p.`value_total`, 0) - COALESCE(p.`value_todate`, 0)
        WHEN 'C' THEN COALESCE(p.`value_total`, 0) + COALESCE(p.`value_todate`, 0)
                    - CASE WHEN r.`cost_basis` = 'costi_a_zero' THEN 0
                           ELSE COALESCE(p.`actual_cost`, 0) END
        WHEN 'D' THEN COALESCE(p.`value_todate`, 0) - COALESCE(p.`actual_cost`, 0)
        ELSE          COALESCE(p.`value_total`, 0)
                    - CASE WHEN r.`cost_basis` = 'costi_a_zero' THEN 0
                           ELSE COALESCE(p.`actual_cost`, 0) END
    END - (COALESCE(p.`value_total`, 0) - COALESCE(p.`actual_cost`, 0)), 2) AS scarto_formula,

    -- il denominatore della percentuale segue la formula: su un contratto a
    -- scalare il margine si rapporta al consuntivato, non al plafond
    CASE
        WHEN r.`formula` = 'D' AND COALESCE(p.`value_todate`, 0) > 0
             THEN ROUND(100 * (COALESCE(p.`value_todate`, 0) - COALESCE(p.`actual_cost`, 0))
                      / p.`value_todate`, 1)
        WHEN r.`formula` <> 'D' AND COALESCE(p.`value_total`, 0) > 0
             THEN ROUND(100 * (CASE r.`formula`
                      WHEN 'A' THEN COALESCE(p.`value_total`,0) - COALESCE(p.`value_todate`,0)
                      WHEN 'C' THEN COALESCE(p.`value_total`,0) + COALESCE(p.`value_todate`,0)
                                  - CASE WHEN r.`cost_basis`='costi_a_zero' THEN 0
                                         ELSE COALESCE(p.`actual_cost`,0) END
                      ELSE COALESCE(p.`value_total`,0)
                           - CASE WHEN r.`cost_basis`='costi_a_zero' THEN 0
                                  ELSE COALESCE(p.`actual_cost`,0) END END)
                      / p.`value_total`, 1)
    END                                             AS margine_pct,

    CASE WHEN COALESCE(p.`operational_status`,'') IN ('Chiusa','Annullata','Persa')
         THEN 0 ELSE 1 END                          AS aperta
FROM `cm_projects` p
JOIN `v_cm_calc_regola` r ON r.`commessa_id` = p.`id`
LEFT JOIN `clients` cl    ON cl.`id` = p.`client_id`;

-- -----------------------------------------------------------------------------
-- 2. Lo scostamento aggregato, per decidere il passaggio.
--
--    Serve a rispondere a "quanto cambia e dove" prima di sostituire i numeri
--    nei pannelli. Ordinata per valore assoluto dello scarto: le linee che
--    contano stanno in cima.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_margine_scostamento` AS
SELECT
    `tipo_contratto`,
    `linea`,
    `formula`,
    `cost_basis`,
    COUNT(*)                                        AS commesse,
    SUM(`aperta` = 1)                               AS aperte,
    ROUND(SUM(`valore_oggi`), 2)                    AS valore,
    ROUND(SUM(`valore_consuntivato`), 2)            AS consuntivato,
    ROUND(SUM(`costi_consuntivati`), 2)             AS costi,
    ROUND(SUM(`margine_attuale`), 2)                AS margine_attuale,
    ROUND(SUM(`margine`), 2)                        AS margine_formula,
    ROUND(SUM(`scarto_formula`), 2)                 AS scarto,
    CASE WHEN SUM(`margine_attuale`) <> 0
         THEN ROUND(100 * SUM(`scarto_formula`) / ABS(SUM(`margine_attuale`)), 1) END AS scarto_pct
FROM `v_cm_margine_formula`
GROUP BY `tipo_contratto`, `linea`, `formula`, `cost_basis`;

