    ('app_version',    '1.9.1', 'Versione applicazione'),
    ('schema_version', '1.9.1', 'Versione schema database'),
    ('release_label',  '1.9.1', 'Etichetta release mostrata in footer')
ON DUPLICATE KEY UPDATE
    `setting_value` = VALUES(`setting_value`);

