-- ════════════════════════════════════════════════════════════════
-- v1.9.2 — Margine dal gestionale, correzione della formula C
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. Il margine, dal gestionale.
--
--    `margine` e' ora `margin_total`, non una ricostruzione. `margine_ricostruito`
--    resta accanto per misurare quanto la ricostruzione sbagliava.
--
--    Le voci del foglio di esempi trovano corrispondenza cosi':
--      Valore della commessa (A)   -> value_total
--      Costi direzionali (G)       -> actual_cost
--      Margine totale (M)          -> margin_total
--      Ricavi maturati (D)         -> value_todate
--      Margine maturato (P)        -> margin_todate
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_margine_formula` AS
SELECT
    p.`id`                                          AS commessa_id,
    p.`project_code`                                AS commessa,
    p.`description`                                 AS denominazione,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS linea,
    r.`tipo_contratto`,
    r.`formula`,
    r.`formula_desc`,
    r.`cost_basis`,
    r.`margin_type`,
    r.`regola_origine`,
    COALESCE(p.`commercial_ref`, '(non attribuita)') AS agente,
    p.`operational_status`                          AS stato,

    -- le voci, con i nomi del foglio di esempi
    ROUND(COALESCE(p.`value_total`, 0), 2)          AS valore_commessa,
    ROUND(COALESCE(p.`value_todate`, 0), 2)         AS ricavi_maturati,
    ROUND(COALESCE(p.`actual_cost`, 0), 2)          AS costi_consuntivati,

    -- il margine calcolato dal gestionale secondo la formula del tipo
    ROUND(COALESCE(p.`margin_total`, 0), 2)         AS margine,
    ROUND(COALESCE(p.`margin_todate`, 0), 2)        AS margine_maturato,

    -- la ricostruzione ingenua, per misurare la differenza
    ROUND(COALESCE(p.`value_total`, 0) - COALESCE(p.`actual_cost`, 0), 2)
                                                    AS margine_ricostruito,
    ROUND(COALESCE(p.`margin_total`, 0)
        - (COALESCE(p.`value_total`, 0) - COALESCE(p.`actual_cost`, 0)), 2)
                                                    AS scarto_ricostruzione,

    CASE WHEN COALESCE(p.`value_total`, 0) > 0
         THEN ROUND(100 * COALESCE(p.`margin_total`, 0) / p.`value_total`, 1) END AS margine_pct,
    CASE WHEN COALESCE(p.`value_todate`, 0) > 0
         THEN ROUND(100 * COALESCE(p.`margin_todate`, 0) / p.`value_todate`, 1) END AS margine_maturato_pct,

    CASE WHEN COALESCE(p.`operational_status`,'') IN ('Chiusa','Annullata','Persa')
         THEN 0 ELSE 1 END                          AS aperta
FROM `cm_projects` p
JOIN `v_cm_calc_regola` r ON r.`commessa_id` = p.`id`
LEFT JOIN `clients` cl    ON cl.`id` = p.`client_id`;

-- -----------------------------------------------------------------------------
-- 2. Dove la ricostruzione sbagliava.
--
--    Serve a documentare l'errore, non a correggerlo: mostra su quali tipi di
--    contratto un margine ricostruito come "valore meno costi" diverge da quello
--    che il gestionale calcola.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_margine_scostamento` AS
SELECT
    `tipo_contratto`,
    `linea`,
    `formula`,
    `cost_basis`,
    COUNT(*)                                        AS commesse,
    SUM(`aperta` = 1)                               AS aperte,
    SUM(ABS(`scarto_ricostruzione`) > 1)            AS commesse_divergenti,
    ROUND(SUM(`valore_commessa`), 2)                AS valore,
    ROUND(SUM(`ricavi_maturati`), 2)                AS ricavi_maturati,
    ROUND(SUM(`costi_consuntivati`), 2)             AS costi,
    ROUND(SUM(`margine_ricostruito`), 2)            AS margine_ricostruito,
    ROUND(SUM(`margine`), 2)                        AS margine_gestionale,
    ROUND(SUM(`margine_maturato`), 2)               AS margine_maturato,
    ROUND(SUM(`scarto_ricostruzione`), 2)           AS scarto,
    CASE WHEN SUM(`margine_ricostruito`) <> 0
         THEN ROUND(100 * SUM(`scarto_ricostruzione`) / ABS(SUM(`margine_ricostruito`)), 1) END AS scarto_pct
FROM `v_cm_margine_formula`
GROUP BY `tipo_contratto`, `linea`, `formula`, `cost_basis`;

-- -----------------------------------------------------------------------------
-- 3. Le voci di calcolo per tipo, come nel foglio di esempi.
--
--    Documenta la corrispondenza fra i nomi che il responsabile usa e le colonne
--    del portale. Senza, ogni volta che qualcuno chiede "dov'e' il margine
--    maturato" bisogna ricostruire la mappa a memoria.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_voci_calcolo` AS
SELECT 'Valore della commessa (A)' AS voce, 'cm_projects.value_total' AS colonna,
       'tutti i tipi' AS si_applica_a, 10 AS ordine
UNION ALL SELECT 'Ricavi maturati (D)', 'cm_projects.value_todate',
       'a maturazione: GES, SOC, REP, SD, PRES', 20
UNION ALL SELECT 'Costi direzionali / rendicontati (G)', 'cm_projects.actual_cost',
       'tutti i tipi', 30
UNION ALL SELECT 'Margine totale (M)', 'cm_projects.margin_total',
       'tutti i tipi, calcolato dal gestionale', 40
UNION ALL SELECT 'Margine maturato (P)', 'cm_projects.margin_todate',
       'tutti i tipi, calcolato dal gestionale', 50
UNION ALL SELECT 'Servizi eseguiti (B) / Addebiti cliente (B)', 'cm_projects.value_todate',
       'a soglia: ACM, MEG, CSS', 60
UNION ALL SELECT 'Soglia residua (C) / Residuo cliente (C)', 'value_total - value_todate',
       'a soglia: ACM, MEG, CSS', 70
UNION ALL SELECT 'Percentuale margine (G/R)', 'margin_total / value_total',
       'calcolata', 80;

