-- ════════════════════════════════════════════════════════════════
-- v1.9.5 — Analisi del Team Service Desk
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. La riga elementare: un modulo del team, con tutte le sue dimensioni.
--
--    Base comune di tutte le aggregazioni che seguono: costruirle ciascuna sui
--    join significherebbe ripetere sei volte la stessa catena, e cambiarla in sei
--    punti quando cambia.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_moduli` AS
SELECT
    r.`id`                                          AS report_id,
    r.`report_code`                                 AS modulo,
    r.`report_date`                                 AS giorno,
    DATE_FORMAT(r.`report_date`, '%Y-%m')           AS anno_mese,
    b.`nome_ticket`                                 AS tecnico,
    COALESCE(n.`ordina`, LOWER(b.`nome_ticket`))    AS ordina,
    COALESCE(p.`service_line`, '(nessuna)')         AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`, '(nessuna)') AS contratto,
    COALESCE(cm.`model`, 'da_classificare')         AS modello,
    COALESCE(cm.`has_revenue`, 1)                   AS ha_ricavo,
    r.`project_code`                                AS commessa,
    ROUND(COALESCE(r.`quantity_hours`, 0), 2)       AS ore,
    ROUND(COALESCE(r.`extra_hours`, 0), 2)          AS ore_extra,

    -- fascia oraria, regola v1.8.53: sabato e domenica fuori orario per
    -- costruzione, poi le due finestre feriali
    CASE
        WHEN DAYOFWEEK(r.`report_date`) IN (1, 7) THEN 'fuori orario'
        WHEN a.`date_start` IS NULL               THEN 'non rilevata'
        WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
          OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800
             THEN 'in orario'
        ELSE 'fuori orario'
    END                                             AS fascia_oraria,

    CASE
        WHEN COALESCE(ao.`during_availability`, 0) = 1 THEN 'reperibilita'
        WHEN COALESCE(ao.`smart_working`, 0) = 1       THEN 'smart working'
        WHEN COALESCE(ao.`from_remote`, 0) = 1         THEN 'da remoto'
        WHEN COALESCE(ao.`trip_hours`, 0) > 0          THEN 'presso cliente'
        ELSE 'in sede'
    END                                             AS modalita
FROM `cm_intervention_reports` r
JOIN `v_cm_sd_nome_moduli` b      ON b.`nome_moduli` = r.`technician_raw`
LEFT JOIN `v_cm_nomi` n           ON n.`forma` = b.`nome_ticket`
LEFT JOIN `cm_projects` p         ON p.`id` = r.`project_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
LEFT JOIN `dgb_forms_activity` a  ON a.`id` = r.`dgb_activity_id`
LEFT JOIN `dgb_forms_activity_operator` ao
       ON ao.`id_activity` = r.`dgb_activity_id` AND ao.`id_operator` = a.`id_operator`;

-- -----------------------------------------------------------------------------
-- 2. Il quadro di squadra.
--
--    Ticket e moduli su colonne distinte, mai sommati.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_team_quadro` AS
SELECT
    (SELECT COUNT(*) FROM `v_cm_sd_team`)                              AS componenti,
    (SELECT COUNT(DISTINCT `sotto_unita`) FROM `v_cm_sd_team`
      WHERE `sotto_unita` IS NOT NULL AND `sotto_unita` <> '')         AS sotto_unita,
    (SELECT COUNT(*) FROM `v_cm_sd_presa_carico` pc
      JOIN `v_cm_sd_team` t ON t.`nome` = pc.`tecnico`)                AS ticket_presi,
    (SELECT COUNT(*) FROM `v_cm_sd_messaggi` m
      JOIN `v_cm_sd_team` t ON t.`nome` = m.`author_name`)             AS messaggi,
    (SELECT COUNT(*) FROM `v_cm_sd_moduli`)                            AS moduli,
    (SELECT ROUND(SUM(`ore`), 2) FROM `v_cm_sd_moduli`)                AS ore,
    (SELECT ROUND(SUM(CASE WHEN `ha_ricavo` = 1 THEN `ore` ELSE 0 END), 2)
       FROM `v_cm_sd_moduli`)                                          AS ore_a_ricavo,
    (SELECT ROUND(SUM(CASE WHEN `fascia_oraria` = 'fuori orario' THEN `ore` ELSE 0 END), 2)
       FROM `v_cm_sd_moduli`)                                          AS ore_fuori_orario,
    (SELECT COUNT(DISTINCT `commessa`) FROM `v_cm_sd_moduli`)          AS commesse,
    (SELECT COUNT(DISTINCT `codice_linea`) FROM `v_cm_sd_moduli`)      AS linee,
    (SELECT COUNT(DISTINCT CONCAT(`tecnico`, '|', `giorno`)) FROM `v_cm_sd_moduli`) AS giornate_uomo;

-- -----------------------------------------------------------------------------
-- 3. Il dettaglio per componente: ticket e moduli affiancati.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_team_dettaglio` AS
SELECT
    t.`nome`                                        AS tecnico,
    COALESCE(nm.`ordina`, LOWER(t.`nome`))          AS ordina,
    t.`sotto_unita`,
    COALESCE(pc.`presi`, 0)                         AS ticket_presi,
    COALESCE(ms.`messaggi`, 0)                      AS messaggi,
    COALESCE(md.`moduli`, 0)                        AS moduli,
    ROUND(COALESCE(md.`ore`, 0), 2)                 AS ore,
    ROUND(COALESCE(md.`ore_extra`, 0), 2)           AS ore_extra,
    ROUND(COALESCE(md.`ore_in_orario`, 0), 2)       AS ore_in_orario,
    ROUND(COALESCE(md.`ore_fuori_orario`, 0), 2)    AS ore_fuori_orario,
    ROUND(COALESCE(md.`ore_ricavo`, 0), 2)          AS ore_a_ricavo,
    COALESCE(md.`commesse`, 0)                      AS commesse,
    COALESCE(md.`linee`, 0)                         AS linee,
    COALESCE(md.`giornate`, 0)                      AS giornate,
    CASE WHEN COALESCE(md.`giornate`, 0) > 0
         THEN ROUND(md.`ore` / md.`giornate`, 1) END AS ore_per_giornata,
    CASE WHEN COALESCE(md.`ore`, 0) > 0
         THEN ROUND(100 * md.`ore_fuori_orario` / md.`ore`, 1) END AS pct_fuori_orario
FROM `v_cm_sd_team` t
LEFT JOIN `v_cm_nomi` nm ON nm.`forma` = t.`nome`
LEFT JOIN (SELECT `tecnico`, COUNT(*) AS presi
             FROM `v_cm_sd_presa_carico` GROUP BY `tecnico`) pc ON pc.`tecnico` = t.`nome`
LEFT JOIN (SELECT `author_name`, COUNT(*) AS messaggi
             FROM `v_cm_sd_messaggi` GROUP BY `author_name`) ms ON ms.`author_name` = t.`nome`
LEFT JOIN (
    SELECT `tecnico`,
           COUNT(*)                                                    AS moduli,
           SUM(`ore`)                                                  AS ore,
           SUM(`ore_extra`)                                            AS ore_extra,
           SUM(CASE WHEN `fascia_oraria` = 'in orario'    THEN `ore` ELSE 0 END) AS ore_in_orario,
           SUM(CASE WHEN `fascia_oraria` = 'fuori orario' THEN `ore` ELSE 0 END) AS ore_fuori_orario,
           SUM(CASE WHEN `ha_ricavo` = 1 THEN `ore` ELSE 0 END)        AS ore_ricavo,
           COUNT(DISTINCT `commessa`)                                  AS commesse,
           COUNT(DISTINCT `codice_linea`)                              AS linee,
           COUNT(DISTINCT `giorno`)                                    AS giornate
      FROM `v_cm_sd_moduli` GROUP BY `tecnico`
) md ON md.`tecnico` = t.`nome`;

-- -----------------------------------------------------------------------------
-- 4. Interventi e ore per fascia oraria.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_team_fascia` AS
SELECT
    `fascia_oraria`,
    `tecnico`,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`ore_extra`), 2)                      AS ore_extra,
    COUNT(DISTINCT `giorno`)                        AS giornate,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    ROUND(AVG(`ore`), 2)                            AS ore_medie_intervento
FROM `v_cm_sd_moduli`
GROUP BY `fascia_oraria`, `tecnico`;

-- -----------------------------------------------------------------------------
-- 5. Interventi e ore per tipologia di contratto, con la fascia.
--
--    Le due dimensioni insieme rispondono alla domanda che il conteggio separato
--    non copre: su quali contratti si lavora fuori orario.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_team_contratto` AS
SELECT
    `codice_linea`,
    `contratto`,
    `modello`,
    `ha_ricavo`,
    `fascia_oraria`,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`ore_extra`), 2)                      AS ore_extra,
    COUNT(DISTINCT `tecnico`)                       AS tecnici,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `giorno`)                        AS giornate
FROM `v_cm_sd_moduli`
GROUP BY `codice_linea`, `contratto`, `modello`, `ha_ricavo`, `fascia_oraria`;

