-- ════════════════════════════════════════════════════════════════
-- v1.9.10 — Service Desk: quadro del perimetro e ripartizione
-- ════════════════════════════════════════════════════════════════
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Il perimetro, in tabella.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('sd_linee_perimetro', 'WTS-SD,WTS-ACM,WTS-CSS,WTS-CC,WTS-HD',
     'Linee di servizio che compongono il perimetro del Service Desk'),
    ('sd_ore_mese_fte', '168',
     'Ore mensili di un addetto a tempo pieno, per il calcolo degli equivalenti')
ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;

-- -----------------------------------------------------------------------------
-- 2. Le commesse del perimetro.
--
--    `margin_total` dal gestionale, non ricostruito: la v1.9.2 ha accertato che
--    ricostruirlo come valore meno costi sbaglia su 194 commesse su 1.092.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_commesse` AS
SELECT
    p.`id`                                          AS commessa_id,
    p.`project_code`                                AS commessa,
    p.`description`                                 AS denominazione,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`)          AS contratto,
    COALESCE(cm.`model`, 'da_classificare')         AS modello,
    COALESCE(cm.`has_revenue`, 1)                   AS ha_ricavo,
    COALESCE(p.`commercial_ref`, '(non attribuita)') AS agente,
    COALESCE(az.`name`, '(non attribuita)')         AS azienda,
    p.`operational_status`                          AS stato,
    p.`start_date`, p.`end_date`,
    ROUND(COALESCE(p.`value_total`, 0), 2)          AS valore,
    ROUND(COALESCE(p.`value_todate`, 0), 2)         AS maturato,
    ROUND(COALESCE(p.`actual_cost`, 0), 2)          AS costi,
    ROUND(COALESCE(p.`margin_total`, 0), 2)         AS margine,
    ROUND(COALESCE(p.`margin_todate`, 0), 2)        AS margine_maturato,
    CASE WHEN COALESCE(p.`value_total`, 0) > 0
         THEN ROUND(100 * COALESCE(p.`margin_total`, 0) / p.`value_total`, 1) END AS margine_pct,
    CASE WHEN COALESCE(p.`operational_status`,'') IN ('Chiusa','Annullata','Persa')
         THEN 0 ELSE 1 END                          AS aperta
FROM `cm_projects` p
LEFT JOIN `clients` cl            ON cl.`id` = p.`client_id`
LEFT JOIN `companies` az          ON az.`id` = p.`exec_company_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
WHERE FIND_IN_SET(p.`service_line`,
      (SELECT REPLACE(`setting_value`, ' ', '') FROM `app_settings`
        WHERE `setting_key` = 'sd_linee_perimetro')) > 0;

-- -----------------------------------------------------------------------------
-- 3. OBJ_2 — il quadro economico per linea.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj2_linee` AS
SELECT
    `codice_linea`,
    `contratto`,
    `modello`,
    `ha_ricavo`,
    COUNT(*)                                        AS commesse,
    SUM(`aperta` = 1)                               AS aperte,
    ROUND(SUM(`valore`), 2)                         AS valore,
    ROUND(SUM(`maturato`), 2)                       AS maturato,
    ROUND(SUM(`costi`), 2)                          AS costi,
    ROUND(SUM(`margine`), 2)                        AS margine,
    ROUND(SUM(`margine_maturato`), 2)               AS margine_maturato,
    CASE WHEN SUM(`valore`) > 0
         THEN ROUND(100 * SUM(`margine`) / SUM(`valore`), 1) END AS margine_pct,
    COUNT(DISTINCT `cliente`)                       AS clienti,
    ROUND(100 * SUM(`valore`) / NULLIF(
        (SELECT SUM(`valore`) FROM `v_cm_sd_commesse`), 0), 1) AS quota_valore_pct
FROM `v_cm_sd_commesse`
GROUP BY `codice_linea`, `contratto`, `modello`, `ha_ricavo`;

-- -----------------------------------------------------------------------------
-- 4. Gli addetti, con tre misure distinte.
--
--    Il denominatore dei mesi viene dai dati, non dal calendario: se un mese non
--    ha interventi non deve abbassare la media.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_addetti_mese` AS
SELECT
    DATE_FORMAT(r.`report_date`, '%Y-%m')           AS anno_mese,
    COUNT(DISTINCT r.`technician_raw`)              AS addetti,
    COUNT(*)                                        AS moduli,
    ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2)  AS ore,
    COUNT(DISTINCT r.`project_code`)                AS commesse
FROM `cm_intervention_reports` r
JOIN `v_cm_sd_commesse` c ON c.`commessa_id` = r.`project_id`
WHERE r.`report_date` IS NOT NULL AND r.`technician_raw` <> ''
GROUP BY DATE_FORMAT(r.`report_date`, '%Y-%m');

-- -----------------------------------------------------------------------------
-- 5. OBJ_2 — il quadro complessivo.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj2_quadro` AS
SELECT
    (SELECT COUNT(*) FROM `v_cm_sd_commesse`)                       AS commesse,
    (SELECT COUNT(*) FROM `v_cm_sd_commesse` WHERE `aperta` = 1)    AS commesse_aperte,
    (SELECT COUNT(DISTINCT `cliente`) FROM `v_cm_sd_commesse`)      AS clienti,
    (SELECT ROUND(SUM(`valore`), 2) FROM `v_cm_sd_commesse`)        AS valore_totale,
    (SELECT ROUND(SUM(`valore`), 2) FROM `v_cm_sd_commesse` WHERE `aperta` = 1) AS valore_aperte,
    (SELECT ROUND(SUM(`maturato`), 2) FROM `v_cm_sd_commesse`)      AS maturato,
    (SELECT ROUND(SUM(`costi`), 2) FROM `v_cm_sd_commesse`)         AS costi,
    (SELECT ROUND(SUM(`margine`), 2) FROM `v_cm_sd_commesse`)       AS margine,
    CASE WHEN (SELECT SUM(`valore`) FROM `v_cm_sd_commesse`) > 0
         THEN ROUND(100 * (SELECT SUM(`margine`) FROM `v_cm_sd_commesse`)
                  / (SELECT SUM(`valore`) FROM `v_cm_sd_commesse`), 1) END AS margine_pct,

    -- tre misure di "addetti", perche' "medio" richiede di dire su cosa
    (SELECT COUNT(DISTINCT r.`technician_raw`) FROM `cm_intervention_reports` r
       JOIN `v_cm_sd_commesse` c ON c.`commessa_id` = r.`project_id`
      WHERE r.`technician_raw` <> '')                               AS addetti_distinti,
    (SELECT ROUND(AVG(`addetti`), 1) FROM `v_cm_sd_addetti_mese`)   AS addetti_medi_mese,
    (SELECT MAX(`addetti`) FROM `v_cm_sd_addetti_mese`)             AS addetti_picco,
    (SELECT COUNT(*) FROM `v_cm_sd_addetti_mese`)                   AS mesi_con_attivita,
    (SELECT ROUND(SUM(`ore`), 2) FROM `v_cm_sd_addetti_mese`)       AS ore_totali,
    (SELECT ROUND(SUM(`ore`) / NULLIF(COUNT(*) * (SELECT CAST(`setting_value` AS DECIMAL(10,2))
             FROM `app_settings` WHERE `setting_key` = 'sd_ore_mese_fte'), 0), 1)
       FROM `v_cm_sd_addetti_mese`)                                 AS fte_equivalenti,

    -- i ticket: gestiti, scalati, e il tasso sui soli presi in carico
    (SELECT COUNT(*) FROM `v_cm_sd_ticket`)                         AS ticket,
    (SELECT COUNT(*) FROM `v_cm_sd_ticket`
      WHERE `gestione` <> 'mai preso in carico')                    AS ticket_presi,
    (SELECT COUNT(*) FROM `v_cm_sd_ticket`
      WHERE `gestione` = 'risolto dal Service Desk')                AS ticket_risolti,
    (SELECT COUNT(*) FROM `v_cm_sd_ticket`
      WHERE `gestione` = 'escalation di 2 livello verso specialisti') AS ticket_scalati,
    (SELECT COUNT(*) FROM `v_cm_sd_ticket`
      WHERE `gestione` = 'presa in carico diretta da specialisti')  AS ticket_diretti,
    (SELECT COUNT(*) FROM `v_cm_sd_ticket`
      WHERE `gestione` = 'mai preso in carico')                     AS ticket_mai_presi,
    -- il tasso sui PRESI IN CARICO, regola v1.8.84: un ticket mai preso non e'
    -- stato ne' risolto ne' scalato, e includerlo abbasserebbe il tasso per una
    -- ragione che non riguarda la capacita' del primo livello
    (SELECT CASE WHEN COUNT(*) > 0 THEN ROUND(100 *
              SUM(`gestione` = 'escalation di 2 livello verso specialisti')
            / COUNT(*), 1) END
       FROM `v_cm_sd_ticket` WHERE `gestione` <> 'mai preso in carico') AS escalation_pct;

-- -----------------------------------------------------------------------------
-- 6. OBJ_2.3 — la ripartizione per classe di gestione.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj23_ripartizione` AS
SELECT
    t.`gestione`,
    COUNT(*)                                        AS ticket,
    ROUND(100 * COUNT(*) / NULLIF(
        (SELECT COUNT(*) FROM `v_cm_sd_ticket`), 0), 1) AS quota_pct,
    COUNT(DISTINCT t.`coda`)                        AS code,
    ROUND(AVG(t.`messaggi`), 1)                     AS messaggi_medi,
    -- `durata_ore` e' apertura -> ultimo messaggio, NON il tempo di prima
    -- risposta: la vista non espone quest'ultimo. Media sui soli presi in
    -- carico, perche' un ticket mai preso ha una durata che misura l'attesa e
    -- non la lavorazione.
    ROUND(AVG(CASE WHEN t.`gestione` <> 'mai preso in carico'
              THEN t.`durata_ore` END), 1)          AS durata_media_ore,
    MIN(t.`aperto_il`)                              AS dal,
    MAX(t.`aperto_il`)                              AS al
FROM `v_cm_sd_ticket` t
GROUP BY t.`gestione`;

-- -----------------------------------------------------------------------------
-- 7. OBJ_2.3 — la ripartizione per coda.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj23_code` AS
SELECT
    COALESCE(t.`coda`, '(nessuna)')                 AS coda,
    COUNT(*)                                        AS ticket,
    ROUND(100 * COUNT(*) / NULLIF(
        (SELECT COUNT(*) FROM `v_cm_sd_ticket`), 0), 1) AS quota_pct,
    SUM(t.`gestione` = 'risolto dal Service Desk')  AS risolti,
    SUM(t.`gestione` = 'escalation di 2 livello verso specialisti') AS scalati,
    SUM(t.`gestione` = 'presa in carico diretta da specialisti')    AS diretti,
    SUM(t.`gestione` = 'mai preso in carico')       AS mai_presi,
    CASE WHEN SUM(t.`gestione` <> 'mai preso in carico') > 0
         THEN ROUND(100 * SUM(t.`gestione` = 'escalation di 2 livello verso specialisti')
                  / SUM(t.`gestione` <> 'mai preso in carico'), 1) END AS escalation_pct,
    ROUND(AVG(CASE WHEN t.`gestione` <> 'mai preso in carico'
              THEN t.`durata_ore` END), 1)          AS durata_media_ore
FROM `v_cm_sd_ticket` t
GROUP BY COALESCE(t.`coda`, '(nessuna)');

