-- ════════════════════════════════════════════════════════════════
-- v1.9.11 — OBJ_2.1 e OBJ_2.2 dai moduli di intervento
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. I parametri.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('sd_unita_organizzative', 'Service Desk,Help Desk',
     'Unita organizzative i cui tecnici compongono il Service Desk'),
    ('sd_tariffa_default', '0',
     'Tariffa oraria di listino predefinita. A zero il valore a listino non viene calcolato: va compilata dall azienda')
ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;

-- -----------------------------------------------------------------------------
-- 2. Il listino, per linea di servizio.
--
--    Tariffe a NULL e non a zero: zero significherebbe "gratis", NULL significa
--    "non ancora stabilita". La differenza conta, perche' un valore a listino
--    calcolato su tariffe assenti sarebbe zero e sembrerebbe un dato.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_sd_listino` (
    `id`            int(11)      NOT NULL AUTO_INCREMENT,
    `service_line`  varchar(60)  NOT NULL,
    `label`         varchar(160) DEFAULT NULL,
    `tariffa_ora`   decimal(10,2) DEFAULT NULL
        COMMENT 'NULL = non stabilita. Zero significherebbe gratis',
    `valuta`        varchar(3)   NOT NULL DEFAULT 'EUR',
    `note`          varchar(300) DEFAULT NULL,
    `is_active`     tinyint(1)   NOT NULL DEFAULT 1,
    `created_at`    datetime     NOT NULL DEFAULT current_timestamp(),
    `updated_at`    datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_sd_listino_line` (`service_line`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `cm_sd_listino` (`service_line`, `label`, `tariffa_ora`, `note`)
VALUES
    ('WTS-ACM', 'Attivita Chiavi in Mano',    NULL, 'Da stabilire'),
    ('WTS-CSS', 'Contratti Servizi Scalare',  NULL, 'Da stabilire'),
    ('WTS-CC',  'Contratti a Chiamata',       NULL, 'Da stabilire'),
    ('WTS-SD',  'Gestione Help Desk',         NULL, 'Da stabilire'),
    ('WTS-HD',  'Help Desk interno Wetechs',  NULL, 'Da stabilire - attivita interna'),
    ('NV_AI',   'Nval - Attivita Interne',    NULL, 'Da stabilire - attivita interna');

-- -----------------------------------------------------------------------------
-- 3. I tecnici del Service Desk, dall'unita' organizzativa.
--
--    `v_cm_nomi` concilia le forme del nome: i moduli usano "Cognome Nome",
--    l'anagrafica ha i campi separati. Senza, l'incrocio fallirebbe e i tecnici
--    risulterebbero senza moduli.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_tecnici_uo` AS
SELECT
    tp.`employee_id`,
    TRIM(CONCAT(COALESCE(e.`last_name`, ''), ' ', COALESCE(e.`first_name`, ''))) AS nome,
    u.`name`                                        AS unita,
    e.`status`                                      AS stato,
    LOWER(TRIM(CONCAT(COALESCE(e.`last_name`, ''), ' ', COALESCE(e.`first_name`, '')))) AS ordina
FROM `cm_tech_profiles` tp
JOIN `cm_tech_units` u  ON u.`id` = tp.`unit_id`
JOIN `employees` e      ON e.`id` = tp.`employee_id`
WHERE FIND_IN_SET(u.`name`,
      (SELECT REPLACE(`setting_value`, ', ', ',') FROM `app_settings`
        WHERE `setting_key` = 'sd_unita_organizzative')) > 0;

-- -----------------------------------------------------------------------------
-- 4. La riga elementare: un modulo di un tecnico SD, con natura e valore.
--
--    Il join sui nomi usa entrambe le forme: i moduli scrivono "Cognome Nome",
--    ma un'anagrafica incompleta puo' produrre l'ordine opposto.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_attivita` AS
SELECT
    r.`id`                                          AS report_id,
    r.`report_code`                                 AS modulo,
    r.`report_date`                                 AS giorno,
    DATE_FORMAT(r.`report_date`, '%Y-%m')           AS anno_mese,
    t.`nome`                                        AS tecnico,
    t.`unita`,
    t.`ordina`,
    r.`project_code`                                AS commessa,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    COALESCE(p.`service_line`, '(nessuna)')         AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`, '(nessuna)') AS contratto,
    COALESCE(cm.`model`, 'da_classificare')         AS modello,
    COALESCE(cm.`has_revenue`, 1)                   AS ha_ricavo,

    -- fatturabile o interna: la natura della COMMESSA, non del ticket
    CASE WHEN COALESCE(cm.`has_revenue`, 1) = 1
         THEN 'fatturabile' ELSE 'interna' END      AS natura,

    ROUND(COALESCE(r.`quantity_hours`, 0), 2)       AS ore,
    ROUND(COALESCE(r.`extra_hours`, 0), 2)          AS ore_extra,

    -- cio' che il gestionale ha addebitato: presente solo dove valorizzato
    CASE WHEN COALESCE(r.`company_cost_import`, 0) > 0
         THEN ROUND(r.`company_cost_import`, 2) END AS valore_addebitato,

    -- il valore a listino: NULL se la tariffa non e' stabilita, non zero
    CASE WHEN li.`tariffa_ora` IS NOT NULL
         THEN ROUND(COALESCE(r.`quantity_hours`, 0) * li.`tariffa_ora`, 2) END AS valore_listino,
    li.`tariffa_ora`
FROM `cm_intervention_reports` r
JOIN `v_cm_sd_tecnici_uo` t
      ON t.`nome` = r.`technician_raw`
      OR t.`employee_id` = r.`technician_id`
LEFT JOIN `cm_projects` p         ON p.`id` = r.`project_id`
LEFT JOIN `clients` cl            ON cl.`id` = p.`client_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
LEFT JOIN `cm_sd_listino` li      ON li.`service_line` = p.`service_line`
                                 AND li.`is_active` = 1
WHERE r.`report_date` IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 5. OBJ_2.1 — l'attivita' fatturabile, per contratto.
--
--    Il conteggio e' di MODULI, non di ticket: un ticket puo' generare piu'
--    moduli e un modulo coprire piu' ticket. Chiamarlo `interventi` evita di far
--    credere che sia la stessa cosa.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj21_fatturabili` AS
SELECT
    `codice_linea`,
    `contratto`,
    `modello`,
    COUNT(*)                                        AS interventi,
    COUNT(DISTINCT `tecnico`)                       AS tecnici,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `cliente`)                       AS clienti,
    COUNT(DISTINCT `giorno`)                        AS giornate,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`ore_extra`), 2)                      AS ore_extra,
    ROUND(SUM(`valore_addebitato`), 2)              AS valore_addebitato,
    SUM(`valore_addebitato` IS NOT NULL)            AS righe_addebitate,
    ROUND(SUM(`valore_listino`), 2)                 AS valore_listino,
    MAX(`tariffa_ora`)                              AS tariffa_ora,
    ROUND(100 * SUM(`ore`) / NULLIF(
        (SELECT SUM(`ore`) FROM `v_cm_sd_attivita` WHERE `natura` = 'fatturabile'), 0), 1)
                                                    AS quota_ore_pct
FROM `v_cm_sd_attivita`
WHERE `natura` = 'fatturabile'
GROUP BY `codice_linea`, `contratto`, `modello`;

-- -----------------------------------------------------------------------------
-- 6. OBJ_2.2 — l'attivita' interna.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj22_interne` AS
SELECT
    `codice_linea`,
    `contratto`,
    COUNT(*)                                        AS interventi,
    COUNT(DISTINCT `tecnico`)                       AS tecnici,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `giorno`)                        AS giornate,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`ore_extra`), 2)                      AS ore_extra,
    ROUND(SUM(`valore_listino`), 2)                 AS valore_listino,
    MAX(`tariffa_ora`)                              AS tariffa_ora,
    ROUND(100 * SUM(`ore`) / NULLIF(
        (SELECT SUM(`ore`) FROM `v_cm_sd_attivita` WHERE `natura` = 'interna'), 0), 1)
                                                    AS quota_ore_pct
FROM `v_cm_sd_attivita`
WHERE `natura` = 'interna'
GROUP BY `codice_linea`, `contratto`;

-- -----------------------------------------------------------------------------
-- 7. OBJ_2.1 + 2.2 — il quadro di sintesi.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj21_quadro` AS
SELECT
    (SELECT COUNT(*) FROM `v_cm_sd_tecnici_uo`)                     AS tecnici_uo,
    (SELECT COUNT(*) FROM `v_cm_sd_attivita`)                       AS interventi,
    (SELECT ROUND(SUM(`ore`), 2) FROM `v_cm_sd_attivita`)           AS ore,

    (SELECT COUNT(*) FROM `v_cm_sd_attivita` WHERE `natura` = 'fatturabile') AS interventi_fatt,
    (SELECT ROUND(SUM(`ore`), 2) FROM `v_cm_sd_attivita` WHERE `natura` = 'fatturabile') AS ore_fatt,
    (SELECT ROUND(SUM(`valore_addebitato`), 2) FROM `v_cm_sd_attivita`
      WHERE `natura` = 'fatturabile')                               AS valore_addebitato,
    (SELECT ROUND(SUM(`valore_listino`), 2) FROM `v_cm_sd_attivita`
      WHERE `natura` = 'fatturabile')                               AS valore_listino_fatt,

    (SELECT COUNT(*) FROM `v_cm_sd_attivita` WHERE `natura` = 'interna') AS interventi_int,
    (SELECT ROUND(SUM(`ore`), 2) FROM `v_cm_sd_attivita` WHERE `natura` = 'interna') AS ore_int,
    (SELECT ROUND(SUM(`valore_listino`), 2) FROM `v_cm_sd_attivita`
      WHERE `natura` = 'interna')                                   AS valore_listino_int,

    -- la quota di lavoro non fatturabile: l'indicatore che l'obiettivo cercava
    (SELECT CASE WHEN SUM(`ore`) > 0
              THEN ROUND(100 * SUM(CASE WHEN `natura` = 'interna' THEN `ore` ELSE 0 END)
                       / SUM(`ore`), 1) END
       FROM `v_cm_sd_attivita`)                                     AS quota_interna_pct,

    -- quante righe hanno una tariffa: senza, i valori a listino sono parziali
    (SELECT COUNT(*) FROM `v_cm_sd_attivita` WHERE `tariffa_ora` IS NOT NULL) AS righe_con_tariffa,
    (SELECT COUNT(*) FROM `cm_sd_listino` WHERE `tariffa_ora` IS NOT NULL)    AS linee_a_listino,
    (SELECT COUNT(*) FROM `cm_sd_listino`)                                    AS linee_listino;

-- -----------------------------------------------------------------------------
-- 8. OBJ_2.3 — la ripartizione fatturabile / interna per tecnico.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_obj23_tecnici` AS
SELECT
    t.`nome`                                        AS tecnico,
    t.`unita`,
    t.`ordina`,
    COALESCE(a.`interventi`, 0)                     AS interventi,
    ROUND(COALESCE(a.`ore`, 0), 2)                  AS ore,
    ROUND(COALESCE(a.`ore_fatt`, 0), 2)             AS ore_fatturabili,
    ROUND(COALESCE(a.`ore_int`, 0), 2)              AS ore_interne,
    CASE WHEN COALESCE(a.`ore`, 0) > 0
         THEN ROUND(100 * a.`ore_fatt` / a.`ore`, 1) END AS quota_fatturabile_pct,
    ROUND(COALESCE(a.`valore_addebitato`, 0), 2)    AS valore_addebitato,
    ROUND(COALESCE(a.`valore_listino`, 0), 2)       AS valore_listino,
    COALESCE(a.`commesse`, 0)                       AS commesse,
    COALESCE(a.`giornate`, 0)                       AS giornate
FROM `v_cm_sd_tecnici_uo` t
LEFT JOIN (
    SELECT `tecnico`, COUNT(*) AS interventi, SUM(`ore`) AS ore,
           SUM(CASE WHEN `natura` = 'fatturabile' THEN `ore` ELSE 0 END) AS ore_fatt,
           SUM(CASE WHEN `natura` = 'interna'     THEN `ore` ELSE 0 END) AS ore_int,
           SUM(`valore_addebitato`) AS valore_addebitato,
           SUM(`valore_listino`)    AS valore_listino,
           COUNT(DISTINCT `commessa`) AS commesse,
           COUNT(DISTINCT `giorno`)   AS giornate
      FROM `v_cm_sd_attivita` GROUP BY `tecnico`
) a ON a.`tecnico` = t.`nome`;

