-- ════════════════════════════════════════════════════════════════
-- v1.9.12 — Sincronizzazione moduli: stati case-insensitive
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 1. La colonna dello stato.
-- -----------------------------------------------------------------------------
ALTER TABLE `cm_intervention_reports`
    ADD COLUMN IF NOT EXISTS `source_status` varchar(40) DEFAULT NULL
        COMMENT 'Stato del modulo nel gestionale, normalizzato in maiuscolo';

ALTER TABLE `cm_intervention_reports`
    ADD INDEX IF NOT EXISTS `idx_ir_source_status` (`source_status`);

-- -----------------------------------------------------------------------------
-- 2. L'elenco degli stati ammessi, come parametro.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('sync_stati_moduli',
     'OPEN,ASSIGNED,COMPLETED,ACTIVE,PENDING,CLOSED,SUSPENDED,NOT_CLOSED,REJECTED,PASSED,TO_BE_DONE',
     'Stati dei moduli ammessi in sincronizzazione. Confronto case-insensitive')
ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);

-- -----------------------------------------------------------------------------
-- 3. La ripartizione per stato, dopo la sincronizzazione.
--
--    Serve a rispondere alla domanda che prima non si poteva porre: quanti
--    moduli ci sono per ciascuno stato, e quante ore rappresentano.
--
--    Se `OPEN` risultasse molto pesante, sarebbe il segnale che il portale sta
--    contabilizzando lavoro non ancora svolto.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_ir_stati` AS
SELECT
    COALESCE(NULLIF(TRIM(r.`source_status`), ''), '(non rilevato)') AS stato,
    COUNT(*)                                        AS moduli,
    ROUND(100 * COUNT(*) / NULLIF(
        (SELECT COUNT(*) FROM `cm_intervention_reports`), 0), 1) AS quota_pct,
    ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2)  AS ore,
    COUNT(DISTINCT r.`technician_raw`)              AS tecnici,
    COUNT(DISTINCT r.`project_code`)                AS commesse,
    MIN(r.`report_date`)                            AS dal,
    MAX(r.`report_date`)                            AS al,
    -- lo stato e' fra quelli dichiarati ammessi?
    CASE WHEN FIND_IN_SET(UPPER(TRIM(COALESCE(r.`source_status`, ''))),
              (SELECT REPLACE(`setting_value`, ' ', '') FROM `app_settings`
                WHERE `setting_key` = 'sync_stati_moduli')) > 0
         THEN 1 ELSE 0 END                          AS ammesso
FROM `cm_intervention_reports` r
GROUP BY COALESCE(NULLIF(TRIM(r.`source_status`), ''), '(non rilevato)');

-- -----------------------------------------------------------------------------
-- 4. La copertura per tecnico, per verificare casi come quello di Bressi.
--
--    `senza_stato` conta i moduli sincronizzati PRIMA di questa release: non
--    hanno lo stato perche' la colonna non esisteva. Non sono un difetto, ma
--    finche' non si risincronizza restano indistinguibili da uno stato mancante.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_ir_copertura_tecnico` AS
SELECT
    r.`technician_raw`                              AS tecnico,
    COUNT(*)                                        AS moduli,
    ROUND(SUM(COALESCE(r.`quantity_hours`, 0)), 2)  AS ore,
    SUM(r.`source_status` IS NULL OR TRIM(r.`source_status`) = '') AS senza_stato,
    COUNT(DISTINCT UPPER(TRIM(r.`source_status`)))  AS stati_distinti,
    GROUP_CONCAT(DISTINCT UPPER(TRIM(r.`source_status`))
                 ORDER BY r.`source_status` SEPARATOR ', ') AS stati,
    MIN(r.`report_date`)                            AS dal,
    MAX(r.`report_date`)                            AS al
FROM `cm_intervention_reports` r
WHERE r.`technician_raw` IS NOT NULL AND r.`technician_raw` <> ''
GROUP BY r.`technician_raw`;

