-- -----------------------------------------------------------------------------
-- 2. Il listino per fascia e scaglione.
--
--    `fascia` C = orario ordinario, D = extra-orario, come nel template.
--    `scaglione` distingue la tariffa entro la fascia.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_sd_tariffe` (
    `id`            int(11)       NOT NULL AUTO_INCREMENT,
    `service_line`  varchar(60)   NOT NULL,
    `fascia`        char(1)       NOT NULL COMMENT 'C = orario ordinario, D = extra-orario',
    `scaglione`     varchar(20)   NOT NULL COMMENT 'ora, mezza_giornata, giornata',
    `etichetta`     varchar(80)   NOT NULL COMMENT 'Descrizione tariffa, come nel riepilogo',
    `tariffa_ora`   decimal(10,2) DEFAULT NULL COMMENT 'NULL = non stabilita. Zero significherebbe gratis',
    `valuta`        varchar(3)    NOT NULL DEFAULT 'EUR',
    `origine`       varchar(40)   NOT NULL DEFAULT 'dedotta da template'
        COMMENT 'Da dove viene il valore: dedotta o dichiarata',
    `is_active`     tinyint(1)    NOT NULL DEFAULT 1,
    `created_at`    datetime      NOT NULL DEFAULT current_timestamp(),
    `updated_at`    datetime      NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_sd_tar` (`service_line`, `fascia`, `scaglione`),
    KEY `idx_sd_tar_line` (`service_line`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

