-- -----------------------------------------------------------------------------
-- 3. La riga elementare: un modulo, con fascia, scaglione e valore.
--
--    La fascia oraria segue la regola della v1.8.53, riusata: sabato e domenica
--    sono extra-orario per costruzione, poi le finestre 09-13 e 14-18.
--
--    Lo scaglione dipende dalla durata del SINGOLO modulo: e' la lettura che i
--    dati del template confermano.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_moduli` AS
SELECT
    r.`id`                                          AS report_id,
    r.`report_code`                                 AS modulo,
    r.`report_date`                                 AS giorno,
    DATE_FORMAT(r.`report_date`, '%Y-%m')           AS anno_mese,
    r.`technician_raw`                              AS tecnico,
    r.`project_code`                                AS commessa,
    p.`id`                                          AS commessa_id,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`)          AS contratto,
    ROUND(COALESCE(r.`quantity_hours`, 0), 2)       AS ore,

    -- in reperibilita': colonna del template
    CASE WHEN COALESCE(ao.`during_availability`, 0) = 1 THEN 'SI' ELSE 'NO' END AS reperibilita,

    -- fascia: C ordinario, D extra-orario. Fine settimana valutato PER PRIMO,
    -- altrimenti un intervento domenicale alle 10 cadrebbe nella finestra 09-13
    CASE
        WHEN DAYOFWEEK(r.`report_date`) IN (1, 7) THEN 'D'
        WHEN a.`date_start` IS NULL               THEN 'C'
        WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
          OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800 THEN 'C'
        ELSE 'D'
    END                                             AS fascia,

    -- scaglione: la durata del singolo modulo
    CASE
        WHEN COALESCE(r.`quantity_hours`, 0) >=
             (SELECT CAST(`setting_value` AS DECIMAL(10,2)) FROM `app_settings`
               WHERE `setting_key` = 'sd_soglia_giornata') THEN 'giornata'
        WHEN COALESCE(r.`quantity_hours`, 0) >
             (SELECT CAST(`setting_value` AS DECIMAL(10,2)) FROM `app_settings`
               WHERE `setting_key` = 'sd_soglia_mezza')    THEN 'mezza_giornata'
        ELSE 'ora'
    END                                             AS scaglione
FROM `cm_intervention_reports` r
JOIN `cm_projects` p              ON p.`id` = r.`project_id`
LEFT JOIN `clients` cl            ON cl.`id` = p.`client_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
LEFT JOIN `dgb_forms_activity` a  ON a.`id` = r.`dgb_activity_id`
LEFT JOIN `dgb_forms_activity_operator` ao
       ON ao.`id_activity` = r.`dgb_activity_id` AND ao.`id_operator` = a.`id_operator`
WHERE r.`report_date` IS NOT NULL
  AND FIND_IN_SET(p.`service_line`,
      (SELECT REPLACE(`setting_value`, ' ', '') FROM `app_settings`
        WHERE `setting_key` = 'sd_costi_linee')) > 0;

-- -----------------------------------------------------------------------------
-- 4. Il valore: ore x tariffa dello scaglione.
--
--    NON un pacchetto forfetario: tre mezze giornate valgono 14 ore x 87,50 e
--    non 3 x 350,00. Il template lo conferma con 1.225,00 contro 1.050,00.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_valorizzati` AS
SELECT
    m.*,
    t.`etichetta`                                   AS descrizione_tariffa,
    t.`tariffa_ora`,
    CASE WHEN t.`tariffa_ora` IS NOT NULL
         THEN ROUND(m.`ore` * t.`tariffa_ora`, 2) END AS valore
FROM `v_cm_sd_costi_moduli` m
LEFT JOIN `cm_sd_tariffe` t
       ON t.`service_line` = m.`codice_linea`
      AND t.`fascia`       = m.`fascia`
      AND t.`scaglione`    = m.`scaglione`
      AND t.`is_active`    = 1;

-- -----------------------------------------------------------------------------
-- 5. Il riepilogo per fascia e contratto — layout del template.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_riepilogo` AS
SELECT
    `codice_linea`,
    `contratto`,
    `fascia`,
    `scaglione`,
    COALESCE(`descrizione_tariffa`,
             CONCAT('Fascia ', `fascia`, ' (', `scaglione`, ')')) AS descrizione_tariffa,
    `reperibilita`,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`valore`), 2)                         AS valore,
    MAX(`tariffa_ora`)                              AS tariffa_ora,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `tecnico`)                       AS tecnici,
    -- quante righe non hanno tariffa: senza, il totale e' parziale e non lo dice
    SUM(`tariffa_ora` IS NULL)                      AS righe_senza_tariffa
FROM `v_cm_sd_costi_valorizzati`
GROUP BY `codice_linea`, `contratto`, `fascia`, `scaglione`,
         `descrizione_tariffa`, `reperibilita`;

-- -----------------------------------------------------------------------------
-- 6. Il riepilogo per singola commessa — secondo foglio del template.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_commessa` AS
SELECT
    `commessa`,
    `codice_linea`,
    `contratto`,
    `cliente`,
    `fascia`,
    `scaglione`,
    COALESCE(`descrizione_tariffa`,
             CONCAT('Fascia ', `fascia`, ' (', `scaglione`, ')')) AS descrizione_tariffa,
    `reperibilita`,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`valore`), 2)                         AS valore,
    MAX(`tariffa_ora`)                              AS tariffa_ora
FROM `v_cm_sd_costi_valorizzati`
GROUP BY `commessa`, `codice_linea`, `contratto`, `cliente`, `fascia`, `scaglione`,
         `descrizione_tariffa`, `reperibilita`;

-- -----------------------------------------------------------------------------
-- 7. Il quadro complessivo.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_quadro` AS
SELECT
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`valore`), 2)                         AS valore,
    SUM(`fascia` = 'C')                             AS interventi_ordinario,
    ROUND(SUM(CASE WHEN `fascia` = 'C' THEN `ore` ELSE 0 END), 2)    AS ore_ordinario,
    ROUND(SUM(CASE WHEN `fascia` = 'C' THEN `valore` ELSE 0 END), 2) AS valore_ordinario,
    SUM(`fascia` = 'D')                             AS interventi_extra,
    ROUND(SUM(CASE WHEN `fascia` = 'D' THEN `ore` ELSE 0 END), 2)    AS ore_extra,
    ROUND(SUM(CASE WHEN `fascia` = 'D' THEN `valore` ELSE 0 END), 2) AS valore_extra,
    SUM(`reperibilita` = 'SI')                      AS interventi_reperibilita,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `codice_linea`)                  AS linee,
    COUNT(DISTINCT `tecnico`)                       AS tecnici,
    SUM(`tariffa_ora` IS NULL)                      AS righe_senza_tariffa,
    (SELECT COUNT(*) FROM `cm_sd_tariffe` WHERE `tariffa_ora` IS NULL) AS tariffe_da_stabilire
FROM `v_cm_sd_costi_valorizzati`;

