-- ════════════════════════════════════════════════════════════════
-- v1.9.16 — Tariffe reali dal gestionale, sei fasce
-- ════════════════════════════════════════════════════════════════

-- -----------------------------------------------------------------------------
-- 2. La mappatura delle fasce, in tabella.
--
--    Sei fasce, non due. Il gestionale usa numeri, i documenti aziendali usano
--    lettere: la corrispondenza va scritta una volta sola.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_um_fasce` (
    `id_activitytype`  int(11)      NOT NULL,
    `fascia`           char(1)      NOT NULL,
    `etichetta`        varchar(80)  DEFAULT NULL,
    `ordine`           int(11)      NOT NULL DEFAULT 0,
    PRIMARY KEY (`id_activitytype`),
    UNIQUE KEY `uq_fascia` (`fascia`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

