    (3, 'C', 'Fascia C', 30),
    (4, 'D', 'Fascia D', 40),
    (5, 'E', 'Fascia E', 50),
    (6, 'X', 'Fascia X', 60);

-- -----------------------------------------------------------------------------
-- 3. La mappatura delle unita' di misura.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cm_um_tempi` (
    `um`          varchar(10)  NOT NULL,
    `etichetta`   varchar(80)  NOT NULL,
    `ore_min`     decimal(6,2) DEFAULT NULL COMMENT 'Ore da cui si applica, estremo incluso',
    `ore_max`     decimal(6,2) DEFAULT NULL COMMENT 'Ore fino a cui si applica, escluso',
    `tipo`        char(1)      NOT NULL DEFAULT 'R',
    `ordine`      int(11)      NOT NULL DEFAULT 0,
    PRIMARY KEY (`um`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `cm_um_tempi` (`um`, `etichetta`, `ore_min`, `ore_max`, `tipo`, `ordine`) VALUES
    ('H',   'Ora',                    0.00, 4.00, 'R', 10),
    ('HD',  'Mezza giornata',         4.00, 8.00, 'R', 20),
    ('D',   'Giornata',               8.00, NULL, 'R', 30),
    ('EH',  'Extra orario',           NULL, NULL, 'R', 40),
    ('CEH', 'Extra orario (costo)',   NULL, NULL, 'C', 50);

-- -----------------------------------------------------------------------------
-- 4. Copertura delle tariffe: quante combinazioni sono valorizzate.
--
--    Il 43% delle righe del gestionale e' a zero. Zero significa "non prevista
--    per questa combinazione", non "gratis": senza questa vista un totale
--    calcolato su tariffe assenti sarebbe zero e sembrerebbe un dato.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_rate_disponibili` AS
SELECT
    r.`activity_type`                               AS fascia_codice,
    SUBSTRING_INDEX(r.`activity_type`, '_', -1)     AS fascia,
    f.`etichetta`                                   AS fascia_etichetta,
    r.`rate_unit`                                   AS um,
    t.`etichetta`                                   AS um_etichetta,
    r.`rate_nature`                                 AS tipo,
    COUNT(*)                                        AS righe,
    COUNT(DISTINCT r.`project_code`)                AS commesse,
    SUM(r.`rate_value` > 0)                         AS valorizzate,
    SUM(r.`rate_value` = 0)                         AS a_zero,
    ROUND(100 * SUM(r.`rate_value` > 0) / NULLIF(COUNT(*), 0), 1) AS copertura_pct,
    ROUND(MIN(NULLIF(r.`rate_value`, 0)), 2)        AS minima,
    ROUND(MAX(r.`rate_value`), 2)                   AS massima,
    ROUND(AVG(NULLIF(r.`rate_value`, 0)), 2)        AS media
FROM `cm_contract_rates` r
LEFT JOIN `cm_um_fasce` f ON f.`fascia` = SUBSTRING_INDEX(r.`activity_type`, '_', -1)
LEFT JOIN `cm_um_tempi` t ON t.`um` = r.`rate_unit`
WHERE r.`activity_type` LIKE 'FASCIA\_%'
GROUP BY r.`activity_type`, fascia, f.`etichetta`, r.`rate_unit`, t.`etichetta`, r.`rate_nature`;

-- -----------------------------------------------------------------------------
-- 5. La tariffa applicabile a un modulo.
--
--    Tre livelli, in ordine di precisione:
--
--      1. fascia dall'ATTIVITA' (`id_activitytype`) e tariffa del suo contratto
--      2. fascia dedotta dall'orario, tariffa del contratto
--      3. nessuna tariffa
--
--    `fascia_origine` dichiara quale dei tre ha risolto: una fascia letta dal
--    modulo e una dedotta dall'ora hanno affidabilita' diversa.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_moduli` AS
SELECT
    r.`id`                                          AS report_id,
    r.`report_code`                                 AS modulo,
    r.`report_date`                                 AS giorno,
    DATE_FORMAT(r.`report_date`, '%Y-%m')           AS anno_mese,
    r.`technician_raw`                              AS tecnico,
    r.`project_code`                                AS commessa,
    p.`id`                                          AS commessa_id,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`)          AS contratto,
    ROUND(COALESCE(r.`quantity_hours`, 0), 2)       AS ore,

    CASE WHEN COALESCE(ao.`during_availability`, 0) = 1 THEN 'SI' ELSE 'NO' END AS reperibilita,

    -- la fascia: letta dall'attivita' quando c'e', dedotta dall'orario altrimenti
    COALESCE(fa.`fascia`,
        CASE
            WHEN DAYOFWEEK(r.`report_date`) IN (1, 7) THEN 'D'
            WHEN a.`date_start` IS NULL               THEN 'C'
            WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
              OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800 THEN 'C'
            ELSE 'D'
        END)                                        AS fascia,
    CASE WHEN fa.`fascia` IS NOT NULL THEN 'attivita' ELSE 'dedotta da orario' END AS fascia_origine,

    -- l'unita' di misura dalla durata
    CASE
        WHEN COALESCE(r.`quantity_hours`, 0) >= 8 THEN 'D'
        WHEN COALESCE(r.`quantity_hours`, 0) >= 4 THEN 'HD'
        ELSE 'H'
    END                                             AS um,

    -- lo scaglione, con i nomi della v1.9.15 per non rompere le viste esistenti
    CASE
        WHEN COALESCE(r.`quantity_hours`, 0) >= 8 THEN 'giornata'
        WHEN COALESCE(r.`quantity_hours`, 0) >= 4 THEN 'mezza_giornata'
        ELSE 'ora'
    END                                             AS scaglione,
    -- il contratto viene dall'ATTIVITA', non dalla commessa: e' l'attivita' che
    -- il gestionale lega al contratto tariffato. `cm_projects.dgb_contract_id`
    -- resta come ripiego dove l'attivita' non e' collegata.
    COALESCE(a.`id_contract`, p.`dgb_contract_id`)  AS id_contract
FROM `cm_intervention_reports` r
JOIN `cm_projects` p              ON p.`id` = r.`project_id`
LEFT JOIN `clients` cl            ON cl.`id` = p.`client_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
LEFT JOIN `dgb_forms_activity` a  ON a.`id` = r.`dgb_activity_id`
LEFT JOIN `cm_um_fasce` fa        ON fa.`id_activitytype` = a.`id_activitytype`
LEFT JOIN `dgb_forms_activity_operator` ao
       ON ao.`id_activity` = r.`dgb_activity_id` AND ao.`id_operator` = a.`id_operator`
WHERE r.`report_date` IS NOT NULL
  AND FIND_IN_SET(p.`service_line`,
      (SELECT REPLACE(`setting_value`, ' ', '') FROM `app_settings`
        WHERE `setting_key` = 'sd_costi_linee')) > 0;

-- -----------------------------------------------------------------------------
-- 6. Il valore, dalla tariffa del contratto.
--
--    Prima la tariffa del contratto specifico. Se manca, quella dedotta della
--    v1.9.15 come ripiego. `tariffa_origine` dichiara quale.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_sd_costi_valorizzati` AS
SELECT
    m.*,
    CONCAT('Fascia ', m.`fascia`, ' (', COALESCE(tm.`etichetta`, m.`um`), ')') AS descrizione_tariffa,
    COALESCE(ur.`rate_value`, td.`tariffa_ora`)        AS tariffa_ora,
    CASE
        WHEN ur.`rate_value` IS NOT NULL THEN 'contratto'
        WHEN td.`tariffa_ora` IS NOT NULL THEN 'dedotta da template'
        ELSE 'assente'
    END                                             AS tariffa_origine,
    CASE WHEN COALESCE(ur.`rate_value`, td.`tariffa_ora`) IS NOT NULL
         THEN ROUND(m.`ore` * COALESCE(ur.`rate_value`, td.`tariffa_ora`), 2) END AS valore
FROM `v_cm_sd_costi_moduli` m
LEFT JOIN `cm_um_tempi` tm ON tm.`um` = m.`um`
-- `cm_contract_rates` e' gia' sincronizzata dal dataset 'tariffe': 35.335
-- righe su 1.173 commesse, di cui 20.045 valorizzate. Il raccordo passa da
-- `project_code`, non dall'id del contratto del gestionale.
LEFT JOIN `cm_contract_rates` ur
       ON ur.`project_code`  = m.`commessa`
      AND ur.`activity_type` = CONCAT('FASCIA_', m.`fascia`)
      AND ur.`rate_unit`     = m.`um`
      AND ur.`rate_nature`   = 'R'
      AND ur.`rate_value`    > 0
LEFT JOIN `cm_sd_tariffe` td
       ON td.`service_line` = m.`codice_linea`
      AND td.`fascia`       = m.`fascia`
      AND td.`scaglione`    = m.`scaglione`
      AND td.`is_active`    = 1
      AND ur.`rate_value`   IS NULL;

