-- ════════════════════════════════════════════════════════════════
-- v1.9.18 — Giorni lavorati per persona (Relazione di Servizio IT)
-- ════════════════════════════════════════════════════════════════
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('it_giorni_linee_escluse',
     'WTS-GES,WTS-MON,WTS-REP,WTS-SD,WTS-SOC,NV_SC,WTS-AM,WTS-HD,WTS-PRES,NV_AI,NV_DT,NV_EVENTI,NV_FI,NV_GC,NV_GS,NV_TI',
     'Linee escluse dall analisi giorni lavorati: canone, presidio e interne'),
    ('it_giorni_solo_attive', '1',
     'Se 1 considera solo le commesse a stato aperto')
ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;

-- -----------------------------------------------------------------------------
-- 2. La riga elementare: un modulo del perimetro.
--
--    La fascia e lo scaglione seguono le regole gia' stabilite: fascia letta
--    dall'attivita' quando c'e', scaglione dalla durata del singolo intervento.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_giorni_base` AS
SELECT
    r.`id`                                          AS report_id,
    r.`report_date`                                 AS giorno,
    DATE_FORMAT(r.`report_date`, '%Y-%m')           AS anno_mese,
    r.`technician_raw`                              AS operatore,
    COALESCE(n.`ordina`, LOWER(r.`technician_raw`)) AS ordina,
    COALESCE(NULLIF(TRIM(r.`tech_sector`), ''), '(non indicata)') AS area_tecnologica,
    r.`project_code`                                AS commessa,
    COALESCE(cl.`name`, p.`client_raw`)             AS cliente,
    p.`service_line`                                AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`)          AS contratto,
    p.`operational_status`                          AS stato_commessa,
    CASE WHEN COALESCE(p.`operational_status`,'') IN ('Chiusa','Annullata','Persa')
         THEN 0 ELSE 1 END                          AS commessa_attiva,
    ROUND(COALESCE(r.`quantity_hours`, 0), 2)       AS ore,
    ROUND(COALESCE(r.`extra_hours`, 0), 2)          AS ore_extra,

    -- fascia: letta dall'attivita', dedotta dall'orario in mancanza
    COALESCE(fa.`fascia`,
        CASE
            WHEN DAYOFWEEK(r.`report_date`) IN (1, 7) THEN 'D'
            WHEN a.`date_start` IS NULL               THEN 'C'
            WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
              OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800 THEN 'C'
            ELSE 'D'
        END)                                        AS fascia,
    CASE WHEN fa.`fascia` IS NOT NULL THEN 'attivita' ELSE 'dedotta da orario' END AS fascia_origine,

    CASE
        WHEN COALESCE(r.`quantity_hours`, 0) >= 8 THEN 'D'
        WHEN COALESCE(r.`quantity_hours`, 0) >= 4 THEN 'HD'
        ELSE 'H'
    END                                             AS um,

    -- la produzione teorica: ore x tariffa di listino
    ur.`rate_value`                                 AS tariffa_ora,
    CASE WHEN ur.`rate_value` IS NOT NULL
         THEN ROUND(COALESCE(r.`quantity_hours`, 0) * ur.`rate_value`, 2) END AS produzione_teorica,
    ROUND(COALESCE(r.`company_cost_import`, 0), 2)  AS valore_addebitato
FROM `cm_intervention_reports` r
JOIN `cm_projects` p              ON p.`id` = r.`project_id`
LEFT JOIN `clients` cl            ON cl.`id` = p.`client_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
LEFT JOIN `v_cm_nomi` n           ON n.`forma` = r.`technician_raw`
LEFT JOIN `dgb_forms_activity` a  ON a.`id` = r.`dgb_activity_id`
LEFT JOIN `cm_um_fasce` fa        ON fa.`id_activitytype` = a.`id_activitytype`
LEFT JOIN `cm_contract_rates` ur
       ON ur.`project_code`  = r.`project_code`
      AND ur.`activity_type` = CONCAT('FASCIA_', COALESCE(fa.`fascia`,
            CASE WHEN DAYOFWEEK(r.`report_date`) IN (1,7) THEN 'D'
                 WHEN a.`date_start` IS NULL THEN 'C'
                 WHEN TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 32400 AND 46800
                   OR TIME_TO_SEC(TIME(a.`date_start`)) BETWEEN 50400 AND 64800 THEN 'C'
                 ELSE 'D' END))
      AND ur.`rate_unit`     = CASE
            WHEN COALESCE(r.`quantity_hours`, 0) >= 8 THEN 'D'
            WHEN COALESCE(r.`quantity_hours`, 0) >= 4 THEN 'HD'
            ELSE 'H' END
      AND ur.`rate_nature`   = 'R'
      AND ur.`rate_value`    > 0
WHERE r.`report_date` IS NOT NULL
  AND r.`technician_raw` IS NOT NULL AND r.`technician_raw` <> ''
  AND FIND_IN_SET(p.`service_line`,
      (SELECT REPLACE(`setting_value`, ' ', '') FROM `app_settings`
        WHERE `setting_key` = 'it_giorni_linee_escluse')) = 0;

-- -----------------------------------------------------------------------------
-- 3. Il riepilogo per operatore, sulle sole commesse attive.
--
--    `giorni_lavorati` sono giorni DISTINTI: chi lavora due ore al giorno per
--    venti giorni ne ha venti, non cinque.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_giorni_operatore` AS
SELECT
    `operatore`,
    `ordina`,
    COUNT(DISTINCT `giorno`)                        AS giorni_lavorati,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`ore`) / 8, 1)                        AS giornate_equiv,
    CASE WHEN COUNT(DISTINCT `giorno`) > 0
         THEN ROUND(SUM(`ore`) / COUNT(DISTINCT `giorno`), 1) END AS ore_per_giorno,

    -- il conteggio per fascia: giorni distinti, non interventi
    COUNT(DISTINCT CASE WHEN `fascia` = 'A' THEN `giorno` END) AS giorni_A,
    COUNT(DISTINCT CASE WHEN `fascia` = 'B' THEN `giorno` END) AS giorni_B,
    COUNT(DISTINCT CASE WHEN `fascia` = 'C' THEN `giorno` END) AS giorni_C,
    COUNT(DISTINCT CASE WHEN `fascia` = 'D' THEN `giorno` END) AS giorni_D,
    COUNT(DISTINCT CASE WHEN `fascia` = 'E' THEN `giorno` END) AS giorni_E,
    COUNT(DISTINCT CASE WHEN `fascia` = 'X' THEN `giorno` END) AS giorni_X,
    ROUND(SUM(CASE WHEN `fascia` = 'C' THEN `ore` ELSE 0 END), 2) AS ore_C,
    ROUND(SUM(CASE WHEN `fascia` = 'D' THEN `ore` ELSE 0 END), 2) AS ore_D,

    COUNT(DISTINCT `area_tecnologica`)              AS aree,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `cliente`)                       AS clienti,
    COUNT(DISTINCT `codice_linea`)                  AS linee,

    ROUND(SUM(`produzione_teorica`), 2)             AS produzione_teorica,
    ROUND(SUM(`valore_addebitato`), 2)              AS valore_addebitato,
    SUM(`produzione_teorica` IS NULL)               AS righe_senza_tariffa,
    CASE WHEN COUNT(DISTINCT `giorno`) > 0
         THEN ROUND(SUM(`produzione_teorica`) / COUNT(DISTINCT `giorno`), 2) END AS produzione_per_giorno,

    -- quanto della classificazione e' letta e quanto supposta
    SUM(`fascia_origine` = 'attivita')              AS fascia_letta,
    SUM(`fascia_origine` = 'dedotta da orario')     AS fascia_dedotta,

    MIN(`giorno`)                                   AS dal,
    MAX(`giorno`)                                   AS al
FROM `v_cm_it_giorni_base`
WHERE `commessa_attiva` = 1
GROUP BY `operatore`, `ordina`;

-- -----------------------------------------------------------------------------
-- 4. Gli stessi dati SENZA il filtro sullo stato, per riconciliare.
--
--    Un modulo su una commessa oggi chiusa non entra nella vista principale
--    anche se all'epoca la commessa era aperta: il totale cambia nel tempo, e
--    un report ristampato mesi dopo puo' dare numeri diversi. Questa vista
--    permette di misurare la differenza invece di subirla.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_giorni_tutte` AS
SELECT
    `operatore`,
    `ordina`,
    COUNT(DISTINCT `giorno`)                        AS giorni_lavorati,
    COUNT(DISTINCT CASE WHEN `commessa_attiva` = 1 THEN `giorno` END) AS giorni_su_attive,
    COUNT(DISTINCT CASE WHEN `commessa_attiva` = 0 THEN `giorno` END) AS giorni_su_chiuse,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(CASE WHEN `commessa_attiva` = 1 THEN `ore` ELSE 0 END), 2) AS ore_su_attive,
    ROUND(SUM(`produzione_teorica`), 2)             AS produzione_teorica,
    ROUND(SUM(CASE WHEN `commessa_attiva` = 1 THEN `produzione_teorica` ELSE 0 END), 2)
                                                    AS produzione_su_attive
FROM `v_cm_it_giorni_base`
GROUP BY `operatore`, `ordina`;

-- -----------------------------------------------------------------------------
-- 5. Il dettaglio per area tecnologica.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_giorni_area` AS
SELECT
    a.`operatore`,
    a.`ordina`,
    a.`area_tecnologica`,
    COUNT(DISTINCT a.`giorno`)                      AS giorni,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(a.`ore`), 2)                          AS ore,
    ROUND(SUM(a.`produzione_teorica`), 2)           AS produzione_teorica,
    COUNT(DISTINCT a.`commessa`)                    AS commesse,
    -- la quota si rapporta al totale dell'operatore: un JOIN e non una
    -- sottoquery correlata, che non puo' riferirsi alla vista che si sta
    -- definendo. E' anche la forma che l'ottimizzatore MariaDB gestisce bene
    -- sulle viste annidate (v1.8.88).
    ROUND(100 * SUM(a.`ore`) / NULLIF(MAX(t.`ore_tot`), 0), 1) AS quota_ore_pct
FROM `v_cm_it_giorni_base` a
JOIN (SELECT `operatore`, SUM(`ore`) AS ore_tot
        FROM `v_cm_it_giorni_base` WHERE `commessa_attiva` = 1
       GROUP BY `operatore`) t ON t.`operatore` = a.`operatore`
WHERE a.`commessa_attiva` = 1
GROUP BY a.`operatore`, a.`ordina`, a.`area_tecnologica`;

-- -----------------------------------------------------------------------------
-- 6. Il quadro complessivo.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_it_giorni_quadro` AS
SELECT
    COUNT(DISTINCT `operatore`)                     AS operatori,
    COUNT(DISTINCT `giorno`)                        AS giorni_calendario,
    COUNT(DISTINCT CONCAT(`operatore`, '|', `giorno`)) AS giorni_uomo,
    COUNT(*)                                        AS interventi,
    ROUND(SUM(`ore`), 2)                            AS ore,
    ROUND(SUM(`ore`) / 8, 1)                        AS giornate_equiv,
    COUNT(DISTINCT `area_tecnologica`)              AS aree,
    COUNT(DISTINCT `commessa`)                      AS commesse,
    COUNT(DISTINCT `codice_linea`)                  AS linee,
    ROUND(SUM(`produzione_teorica`), 2)             AS produzione_teorica,
    ROUND(SUM(`valore_addebitato`), 2)              AS valore_addebitato,
    SUM(`produzione_teorica` IS NULL)               AS righe_senza_tariffa,
    ROUND(100 * SUM(`fascia_origine` = 'attivita') / NULLIF(COUNT(*), 0), 1) AS fascia_letta_pct,
    COUNT(DISTINCT CASE WHEN `fascia` = 'C' THEN CONCAT(`operatore`,'|',`giorno`) END) AS giorni_uomo_C,
    COUNT(DISTINCT CASE WHEN `fascia` = 'D' THEN CONCAT(`operatore`,'|',`giorno`) END) AS giorni_uomo_D
FROM `v_cm_it_giorni_base`
WHERE `commessa_attiva` = 1;

