-- ════════════════════════════════════════════════════════════════
-- v1.9.22 — Ordinativi Pratix
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `cm_pratix_orders` (
    `id`               int(11)       NOT NULL AUTO_INCREMENT,
    `source_id`        int(11)       DEFAULT NULL COMMENT 'forms_contract_main_order.id',
    `code`             varchar(255)  NOT NULL    COMMENT 'forms_contract_main_order.code',
    `description`      varchar(1000) DEFAULT NULL,
    `amount`           decimal(12,2) DEFAULT NULL COMMENT 'Importo totale dichiarato',
    `allocated_amount` decimal(12,2) DEFAULT NULL COMMENT 'Importo gia allocato',
    `customer_name`    varchar(255)  DEFAULT NULL,
    `imported_at`      datetime      NOT NULL DEFAULT current_timestamp(),
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_pratix_code` (`code`),
    KEY `idx_pratix_amount` (`amount`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. I separatori che indicano piu' codici in una cella.
--
--    In tabella e non nel codice: l'elenco cresce guardando i dati, e ogni
--    aggiunta e' una riga invece di una release.
-- -----------------------------------------------------------------------------
INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    -- la classe POSIX degli spazi contiene un punto e virgola che gli splitter
    -- SQL interpretano come fine istruzione: uso [[:blank:]]
    -- v1.9.22 — riconosce anche i codici separati da soli SPAZI.
    --
    -- Il collaudo ha trovato 'C2501 C2500 C2499 C1401': quattro codici senza
    -- alcun separatore esplicito. La prima versione della regola cercava
    -- virgole, barre e trattini, e questa cella passava per singola.
    --
    -- Il criterio e' ora strutturale: DUE O PIU sequenze lettera+cifre. Cosi'
    -- 'Ordine A2245' resta singolo — una sola sequenza — mentre 'A0367 - A0489'
    -- e 'C2501 C2500' vengono entrambi riconosciuti.
    ('pratix_regex_multi', '[A-Za-z][0-9]{3,}.*[A-Za-z][0-9]{3,}',
     'Espressione che riconosce piu codici in una cella order_code')
ON DUPLICATE KEY UPDATE
    -- la regex e' una REGOLA di riconoscimento, non una preferenza: un
    -- aggiornamento che la migliora deve applicarsi anche dove esiste gia'.
    -- La tolleranza sotto e' invece una scelta, e resta com'e'.
    `setting_value` = VALUES(`setting_value`);

INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('pratix_tolleranza', '0.01',
     'Scostamento in euro entro il quale somma e totale sono considerati coincidenti')
ON DUPLICATE KEY UPDATE `setting_key` = `setting_key`;

-- -----------------------------------------------------------------------------
-- 3. La riga elementare: un'operazione con ordinativo.
--
--    `importo` usa `final_value` quando c'e', `revenue` altrimenti: il primo e'
--    il valore consolidato dell'operazione, il secondo quello previsto. Sommare
--    l'uno o l'altro indifferentemente darebbe un totale misto.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pratix_righe` AS
SELECT
    o.`id`                                          AS operazione_id,
    TRIM(o.`order_code`)                            AS order_code,
    o.`op_code`,
    o.`op_type_code`                                AS tipo_operazione,
    o.`op_name`                                     AS nome_operazione,
    o.`op_date`                                     AS data_operazione,
    o.`description`                                 AS descrizione,
    o.`project_code`                                AS commessa,
    p.`id`                                          AS commessa_id,
    p.`description`                                 AS denominazione,
    COALESCE(cl.`name`, p.`client_raw`, '(non indicato)') AS cliente,
    p.`service_line`                                AS codice_linea,
    COALESCE(cm.`label`, p.`service_line`, '(non classificato)') AS tipo_contratto,
    p.`operational_status`                          AS stato_commessa,
    CASE WHEN COALESCE(p.`operational_status`,'') IN ('Chiusa','Annullata','Persa')
         THEN 0 ELSE 1 END                          AS commessa_attiva,

    -- il valore consolidato quando c'e', quello previsto altrimenti
    ROUND(COALESCE(NULLIF(o.`final_value`, 0), o.`revenue`, o.`amount`, 0), 2) AS importo,
    CASE
        WHEN COALESCE(o.`final_value`, 0) <> 0 THEN 'consolidato'
        WHEN COALESCE(o.`revenue`, 0) <> 0     THEN 'previsto'
        ELSE 'non valorizzato'
    END                                             AS origine_importo,
    ROUND(COALESCE(o.`invoice_amount`, 0), 2)       AS importo_fatturato,
    COALESCE(o.`is_invoiced`, 0)                    AS fatturata,

    -- piu' codici nella stessa cella: segnalati, non divisi
    CASE WHEN TRIM(o.`order_code`) REGEXP
              (SELECT `setting_value` FROM `app_settings`
                WHERE `setting_key` = 'pratix_regex_multi')
         THEN 1 ELSE 0 END                          AS codici_multipli
FROM `cm_project_operations` o
LEFT JOIN `cm_projects` p         ON p.`id` = o.`project_id`
LEFT JOIN `clients` cl            ON cl.`id` = p.`client_id`
LEFT JOIN `cm_contract_models` cm ON cm.`service_line` = p.`service_line`
WHERE o.`order_code` IS NOT NULL AND TRIM(o.`order_code`) <> '';

-- -----------------------------------------------------------------------------
-- 4. Il raggruppamento per ordinativo, con la validazione.
--
--    `esito_validazione` distingue tre casi, e il terzo non e' un errore:
--
--      coincide             somma e totale differiscono meno della tolleranza
--      scostamento          differiscono di piu'
--      totale non disponibile   l'ordinativo non e' sincronizzato
--
--    Trattare il terzo come "scostamento" avrebbe segnalato come anomalia
--    l'assenza di un dato, e 896 ordinativi su 896 sarebbero risultati anomali.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pratix_ordinativi` AS
SELECT
    r.`order_code`,
    COUNT(*)                                        AS operazioni,
    COUNT(DISTINCT r.`commessa`)                    AS commesse,
    COUNT(DISTINCT r.`cliente`)                     AS clienti,
    COUNT(DISTINCT r.`tipo_contratto`)              AS tipi_contratto,
    SUM(r.`commessa_attiva` = 1)                    AS commesse_attive,
    ROUND(SUM(r.`importo`), 2)                      AS importo_totale,
    ROUND(SUM(r.`importo_fatturato`), 2)            AS importo_fatturato,
    SUM(r.`fatturata` = 1)                          AS operazioni_fatturate,
    SUM(r.`origine_importo` = 'non valorizzato')    AS righe_senza_importo,
    MAX(r.`codici_multipli`)                        AS ha_codici_multipli,
    MIN(r.`data_operazione`)                        AS dal,
    MAX(r.`data_operazione`)                        AS al,

    -- il totale dichiarato, quando l'ordinativo e' sincronizzato
    mo.`amount`                                     AS totale_dichiarato,
    mo.`description`                                AS descrizione_ordinativo,
    CASE WHEN mo.`amount` IS NOT NULL
         THEN ROUND(SUM(r.`importo`) - mo.`amount`, 2) END AS scostamento,
    CASE
        WHEN mo.`amount` IS NULL THEN 'totale non disponibile'
        WHEN ABS(SUM(r.`importo`) - mo.`amount`) <=
             (SELECT CAST(`setting_value` AS DECIMAL(10,2)) FROM `app_settings`
               WHERE `setting_key` = 'pratix_tolleranza') THEN 'coincide'
        ELSE 'scostamento'
    END                                             AS esito_validazione
FROM `v_cm_pratix_righe` r
LEFT JOIN `cm_pratix_orders` mo ON mo.`code` = r.`order_code`
GROUP BY r.`order_code`, mo.`amount`, mo.`description`;

-- -----------------------------------------------------------------------------
-- 5. Le anomalie, in un elenco solo.
--
--    Tre tipi distinti, con priorita': un ordinativo puo' presentarne piu' di
--    uno, e l'elenco li tiene separati invece di fonderli in un punteggio.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pratix_anomalie` AS
SELECT `order_code`, 'codici multipli nella cella' AS anomalia, 1 AS priorita,
       `operazioni`, `commesse`, `importo_totale`,
       'La cella contiene piu di un codice: importo non attribuibile a un solo ordinativo' AS nota
  FROM `v_cm_pratix_ordinativi` WHERE `ha_codici_multipli` = 1
UNION ALL
SELECT `order_code`, 'scostamento dal totale dichiarato', 2,
       `operazioni`, `commesse`, `importo_totale`,
       CONCAT('Somma ', FORMAT(`importo_totale`, 2), ' contro totale ',
              FORMAT(`totale_dichiarato`, 2), ': differenza ',
              FORMAT(`scostamento`, 2))
  FROM `v_cm_pratix_ordinativi` WHERE `esito_validazione` = 'scostamento'
UNION ALL
SELECT `order_code`, 'operazioni senza importo', 3,
       `operazioni`, `commesse`, `importo_totale`,
       CONCAT(`righe_senza_importo`, ' operazioni su ', `operazioni`,
              ' non hanno un importo: il totale e parziale')
  FROM `v_cm_pratix_ordinativi` WHERE `righe_senza_importo` > 0;

-- -----------------------------------------------------------------------------
-- 6. Il quadro complessivo.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_cm_pratix_quadro` AS
SELECT
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi`)                      AS ordinativi,
    (SELECT COUNT(*) FROM `v_cm_pratix_righe`)                           AS operazioni,
    (SELECT COUNT(DISTINCT `commessa`) FROM `v_cm_pratix_righe`)         AS commesse,
    (SELECT COUNT(DISTINCT `cliente`) FROM `v_cm_pratix_righe`)          AS clienti,
    (SELECT ROUND(SUM(`importo`), 2) FROM `v_cm_pratix_righe`)           AS importo_totale,
    (SELECT ROUND(SUM(`importo_fatturato`), 2) FROM `v_cm_pratix_righe`) AS importo_fatturato,
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi` WHERE `commesse` > 1) AS ordinativi_multi_commessa,
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi` WHERE `ha_codici_multipli` = 1) AS con_codici_multipli,
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi` WHERE `esito_validazione` = 'coincide') AS validati_ok,
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi` WHERE `esito_validazione` = 'scostamento') AS con_scostamento,
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi`
      WHERE `esito_validazione` = 'totale non disponibile')              AS senza_totale,
    (SELECT COUNT(*) FROM `v_cm_pratix_ordinativi` WHERE `righe_senza_importo` > 0) AS con_righe_vuote,
    (SELECT COUNT(*) FROM `cm_pratix_orders`)                            AS ordinativi_sincronizzati;

INSERT INTO `app_settings` (`setting_key`, `setting_value`, `description`)
VALUES
    ('app_version',    '1.9.22', 'Versione applicazione'),
    ('schema_version', '1.9.22', 'Versione schema database'),
    ('release_label',  '1.9.22', 'Etichetta release mostrata in footer')
ON DUPLICATE KEY UPDATE
